create or replace function public.revoke_user_role_admin(target_user_id uuid, target_role_key text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can revoke roles.' using errcode = '42501';
  end if;

  update public.user_role_assignments
  set status = 'revoked', updated_at = now()
  where user_id = target_user_id and role_key = target_role_key;

  perform public.record_admin_audit('role_revoked', 'user_role_assignments', target_user_id::text || ':' || target_role_key, target_user_id, 'Role revoked from admin users console.', jsonb_build_object('role_key', target_role_key));
  return true;
end;
$$

create or replace function public.revoke_user_scope_admin(scope_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  target_user uuid;
  payload jsonb;
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can revoke user scopes.' using errcode = '42501';
  end if;

  select user_id, jsonb_build_object('role_key', role_key, 'scope_type', scope_type, 'scope_value', scope_value)
  into target_user, payload
  from public.user_access_scopes
  where id = scope_id;

  update public.user_access_scopes set status = 'revoked', updated_at = now() where id = scope_id;
  perform public.record_admin_audit('scope_revoked', 'user_access_scopes', scope_id::text, target_user, 'Scope revoked from admin users console.', payload);
  return true;
end;
$$

create or replace function public.suspend_user_access_admin(target_user_id uuid, reason text default null)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can suspend users.' using errcode = '42501';
  end if;

  update public.user_profiles set status = 'suspended', updated_at = now() where user_id = target_user_id;
  update public.user_role_assignments set status = 'suspended', updated_at = now() where user_id = target_user_id and status = 'active';
  update public.user_access_scopes set status = 'suspended', updated_at = now() where user_id = target_user_id and status = 'active';
  perform public.record_admin_audit('user_suspended', 'user_profiles', target_user_id::text, target_user_id, coalesce(reason, 'User suspended from admin users console.'), jsonb_build_object('reason', reason));
  return true;
end;
$$

create or replace function public.record_password_reset_admin(
  target_user_id uuid,
  target_email text,
  redirect_to text default null,
  delivery_status text default 'requested',
  message text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  recovery_id uuid;
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can record password reset actions.' using errcode = '42501';
  end if;

  insert into public.admin_account_recovery_events (target_user_id, target_email, requested_by, recovery_type, delivery_status, redirect_to, message, metadata, created_at, updated_at)
  values (target_user_id, target_email, auth.uid(), 'password_reset', delivery_status, redirect_to, message, jsonb_build_object('source', 'admin_users_console'), now(), now())
  returning id into recovery_id;

  perform public.record_admin_audit('password_reset_requested', 'admin_account_recovery_events', recovery_id::text, target_user_id, coalesce(message, 'Password reset requested from admin users console.'), jsonb_build_object('target_email', target_email, 'redirect_to', redirect_to, 'delivery_status', delivery_status));
  return recovery_id;
end;
$$

create or replace function public.community_ensure_user_account(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_email text;
  v_display_name text;
  v_username text;
  v_cols text[];
  v_vals text[];
  v_updates text[];
begin
  if p_user_id is null then
    raise exception 'user_id is required';
  end if;

  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_user_id <> auth.uid() and not public.current_user_is_administrator() then
    raise exception 'not allowed';
  end if;

  select
    au.email,
    coalesce(
      au.raw_user_meta_data->>'full_name',
      au.raw_user_meta_data->>'name',
      split_part(coalesce(au.email, ''), '@', 1),
      'WAKILISHA user'
    )
  into v_email, v_display_name
  from auth.users au
  where au.id = p_user_id;

  if not found then
    raise exception 'auth user % not found', p_user_id;
  end if;

  insert into public.user_profiles (user_id, email, display_name, status, metadata, created_at, updated_at)
  values (
    p_user_id,
    v_email,
    v_display_name,
    'active',
    jsonb_build_object('created_by', 'community_ensure_user_account'),
    now(),
    now()
  )
  on conflict (user_id) do update set
    email = coalesce(excluded.email, public.user_profiles.email),
    display_name = coalesce(public.user_profiles.display_name, excluded.display_name),
    status = coalesce(public.user_profiles.status, 'active'),
    updated_at = now();

  -- Some community tables were introduced separately from the durable auth
  -- profile table. If community_profiles exists and notification prefs point to
  -- it in an older environment, ensure that row too without assuming every
  -- optional column exists.
  if to_regclass('public.community_profiles') is not null then
    v_username := regexp_replace(
      lower(coalesce(nullif(split_part(coalesce(v_email, ''), '@', 1), ''), 'user')),
      '[^a-z0-9_]+',
      '_',
      'g'
    );
    v_username := trim(both '_' from v_username);
    v_username := left(coalesce(nullif(v_username, ''), 'user'), 24) || '_' || replace(left(p_user_id::text, 8), '-', '');

    v_cols := array['user_id'];
    v_vals := array['$1'];
    v_updates := array[]::text[];

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'username') then
      v_cols := array_append(v_cols, 'username');
      v_vals := array_append(v_vals, '$2');
      v_updates := array_append(v_updates, 'username = coalesce(public.community_profiles.username, excluded.username)');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'display_name') then
      v_cols := array_append(v_cols, 'display_name');
      v_vals := array_append(v_vals, '$3');
      v_updates := array_append(v_updates, 'display_name = coalesce(public.community_profiles.display_name, excluded.display_name)');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'email') then
      v_cols := array_append(v_cols, 'email');
      v_vals := array_append(v_vals, '$4');
      v_updates := array_append(v_updates, 'email = coalesce(excluded.email, public.community_profiles.email)');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'is_public') then
      v_cols := array_append(v_cols, 'is_public');
      v_vals := array_append(v_vals, 'true');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'created_at') then
      v_cols := array_append(v_cols, 'created_at');
      v_vals := array_append(v_vals, 'now()');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'updated_at') then
      v_cols := array_append(v_cols, 'updated_at');
      v_vals := array_append(v_vals, 'now()');
      v_updates := array_append(v_updates, 'updated_at = now()');
    end if;

    execute format(
      'insert into public.community_profiles (%s) values (%s) on conflict (user_id) do update set %s',
      array_to_string(v_cols, ', '),
      array_to_string(v_vals, ', '),
      case
        when coalesce(array_length(v_updates, 1), 0) > 0 then array_to_string(v_updates, ', ')
        else 'user_id = excluded.user_id'
      end
    ) using p_user_id, v_username, v_display_name, v_email;
  end if;
end;
$$

create function public.community_get_user_profile(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile public.user_profiles%rowtype;
begin
  if p_user_id is null then
    return null;
  end if;

  if auth.uid() is not null and (p_user_id = auth.uid() or public.current_user_is_administrator()) then
    perform public.community_ensure_user_account(p_user_id);
  end if;

  select * into v_profile
  from public.user_profiles
  where user_id = p_user_id;

  if not found then
    return null;
  end if;

  if coalesce(v_profile.is_public, true) = false
    and (
      auth.uid() is null
      or (v_profile.user_id <> auth.uid() and not public.current_user_is_administrator())
    ) then
    return null;
  end if;

  return jsonb_build_object(
    'user_id', v_profile.user_id,
    'email', v_profile.email,
    'display_name', coalesce(v_profile.display_name, split_part(coalesce(v_profile.email, ''), '@', 1), 'WAKILISHA user'),
    'bio', coalesce(v_profile.bio, ''),
    'country', coalesce(v_profile.country, ''),
    'city', coalesce(v_profile.city, ''),
    'avatar_url', v_profile.avatar_url,
    'is_public', coalesce(v_profile.is_public, true),
    'created_at', v_profile.created_at,
    'updated_at', v_profile.updated_at
  );
end;
$$

create or replace function public.community_username_seed(p_seed text)
returns text
language plpgsql
immutable
as $$
declare
  v_seed text;
begin
  v_seed := lower(coalesce(p_seed, ''));
  v_seed := regexp_replace(v_seed, '[^a-z0-9_]+', '_', 'g');
  v_seed := regexp_replace(v_seed, '_+', '_', 'g');
  v_seed := trim(both '_' from v_seed);

  if length(coalesce(v_seed, '')) < 3 then
    v_seed := 'user';
  end if;

  v_seed := left(v_seed, 24);
  v_seed := trim(both '_' from v_seed);

  if length(coalesce(v_seed, '')) < 3 then
    v_seed := 'user';
  end if;

  if v_seed !~ '^[a-z0-9]' then
    v_seed := 'user' || v_seed;
  end if;

  if v_seed !~ '[a-z0-9]$' then
    v_seed := v_seed || 'user';
  end if;

  return left(v_seed, 24);
end;
$$

create or replace function public.community_generate_username(
  p_user_id uuid,
  p_email text,
  p_display_name text default null
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_base text;
  v_candidate text;
  v_suffix text;
  v_attempt integer := 0;
begin
  v_base := public.community_username_seed(
    coalesce(
      nullif(p_display_name, ''),
      nullif(split_part(coalesce(p_email, ''), '@', 1), ''),
      'user'
    )
  );

  v_candidate := v_base;

  if public.community_username_is_reserved(v_candidate)
    or exists (
      select 1
      from public.user_profiles up
      where up.username_normalized = v_candidate
        and up.user_id <> p_user_id
    )
  then
    v_suffix := '_' || left(replace(coalesce(p_user_id::text, gen_random_uuid()::text), '-', ''), 8);
    v_candidate := left(v_base, 30 - length(v_suffix)) || v_suffix;
  end if;

  while public.community_username_is_reserved(v_candidate)
    or exists (
      select 1
      from public.user_profiles up
      where up.username_normalized = v_candidate
        and up.user_id <> p_user_id
    )
  loop
    v_attempt := v_attempt + 1;
    v_suffix := '_' || left(replace(coalesce(p_user_id::text, gen_random_uuid()::text), '-', ''), 6) || v_attempt::text;
    v_candidate := left(v_base, 30 - length(v_suffix)) || v_suffix;

    if v_attempt > 99 then
      raise exception 'could not generate unique username for user %', p_user_id;
    end if;
  end loop;

  return v_candidate;
end;
$$

-- Backfill every existing profile with a stable, unique, valid username.
do $$
declare
  v_profile record;
  v_base text;
  v_candidate text;
  v_suffix text;
  v_attempt integer;
begin
  drop table if exists pg_temp.wk_taken_usernames;
  create temporary table wk_taken_usernames (
    username_normalized text primary key
  ) on commit drop;

  insert into wk_taken_usernames (username_normalized)
  select username from public.community_reserved_usernames
  on conflict do nothing;

  for v_profile in
    select user_id, email, display_name, username, created_at
    from public.user_profiles
    order by created_at nulls last, user_id
  loop
    v_candidate := public.community_normalize_username(v_profile.username);

    if v_candidate is null
      or not public.community_username_is_valid(v_candidate)
      or exists (select 1 from wk_taken_usernames where username_normalized = v_candidate)
    then
      v_base := public.community_username_seed(
        coalesce(
          nullif(v_profile.username, ''),
          nullif(v_profile.display_name, ''),
          nullif(split_part(coalesce(v_profile.email, ''), '@', 1), ''),
          'user'
        )
      );
      v_candidate := v_base;
    end if;

    if not public.community_username_is_valid(v_candidate)
      or exists (select 1 from wk_taken_usernames where username_normalized = v_candidate)
    then
      v_suffix := '_' || left(replace(v_profile.user_id::text, '-', ''), 8);
      v_candidate := left(v_base, 30 - length(v_suffix)) || v_suffix;
    end if;

    v_attempt := 0;
    while not public.community_username_is_valid(v_candidate)
      or exists (select 1 from wk_taken_usernames where username_normalized = v_candidate)
    loop
      v_attempt := v_attempt + 1;
      v_suffix := '_' || left(replace(v_profile.user_id::text, '-', ''), 6) || v_attempt::text;
      v_candidate := left(v_base, 30 - length(v_suffix)) || v_suffix;

      if v_attempt > 99 then
        raise exception 'could not backfill unique username for user %', v_profile.user_id;
      end if;
    end loop;

    update public.user_profiles
    set
      username = v_candidate,
      username_normalized = v_candidate,
      updated_at = now()
    where user_id = v_profile.user_id;

    insert into wk_taken_usernames (username_normalized)
    values (v_candidate)
    on conflict do nothing;
  end loop;
end;
$$

create or replace function public.community_ensure_user_account(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_email text;
  v_display_name text;
  v_username text;
  v_cols text[];
  v_vals text[];
  v_updates text[];
begin
  if p_user_id is null then
    raise exception 'user_id is required';
  end if;

  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_user_id <> auth.uid() and not public.current_user_is_administrator() then
    raise exception 'not allowed';
  end if;

  select
    au.email,
    coalesce(
      au.raw_user_meta_data->>'full_name',
      au.raw_user_meta_data->>'name',
      split_part(coalesce(au.email, ''), '@', 1),
      'WAKILISHA user'
    )
  into v_email, v_display_name
  from auth.users au
  where au.id = p_user_id;

  if not found then
    raise exception 'auth user % not found', p_user_id;
  end if;

  v_username := public.community_generate_username(p_user_id, v_email, v_display_name);

  insert into public.user_profiles (
    user_id,
    email,
    username,
    username_normalized,
    display_name,
    status,
    metadata,
    created_at,
    updated_at
  ) values (
    p_user_id,
    v_email,
    v_username,
    v_username,
    v_display_name,
    'active',
    jsonb_build_object('created_by', 'community_ensure_user_account'),
    now(),
    now()
  )
  on conflict (user_id) do update set
    email = coalesce(excluded.email, public.user_profiles.email),
    username = coalesce(public.user_profiles.username, excluded.username),
    username_normalized = coalesce(public.user_profiles.username_normalized, excluded.username_normalized),
    display_name = coalesce(public.user_profiles.display_name, excluded.display_name),
    status = coalesce(public.user_profiles.status, 'active'),
    updated_at = now();

  -- Keep legacy community_profiles environments hydrated without making it the
  -- canonical identity table.
  if to_regclass('public.community_profiles') is not null then
    v_cols := array['user_id'];
    v_vals := array['$1'];
    v_updates := array[]::text[];

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'username') then
      v_cols := array_append(v_cols, 'username');
      v_vals := array_append(v_vals, '$2');
      v_updates := array_append(v_updates, 'username = coalesce(public.community_profiles.username, excluded.username)');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'display_name') then
      v_cols := array_append(v_cols, 'display_name');
      v_vals := array_append(v_vals, '$3');
      v_updates := array_append(v_updates, 'display_name = coalesce(public.community_profiles.display_name, excluded.display_name)');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'email') then
      v_cols := array_append(v_cols, 'email');
      v_vals := array_append(v_vals, '$4');
      v_updates := array_append(v_updates, 'email = coalesce(excluded.email, public.community_profiles.email)');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'is_public') then
      v_cols := array_append(v_cols, 'is_public');
      v_vals := array_append(v_vals, 'true');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'created_at') then
      v_cols := array_append(v_cols, 'created_at');
      v_vals := array_append(v_vals, 'now()');
    end if;

    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'community_profiles' and column_name = 'updated_at') then
      v_cols := array_append(v_cols, 'updated_at');
      v_vals := array_append(v_vals, 'now()');
      v_updates := array_append(v_updates, 'updated_at = now()');
    end if;

    execute format(
      'insert into public.community_profiles (%s) values (%s) on conflict (user_id) do update set %s',
      array_to_string(v_cols, ', '),
      array_to_string(v_vals, ', '),
      case
        when coalesce(array_length(v_updates, 1), 0) > 0 then array_to_string(v_updates, ', ')
        else 'user_id = excluded.user_id'
      end
    ) using p_user_id, v_username, v_display_name, v_email;
  end if;
end;
$$

