create function public.community_username_available(p_username text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_username text;
  v_existing_user_id uuid;
begin
  v_username := public.community_normalize_username(p_username);

  if v_username is null or not public.community_username_is_valid(v_username) then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'invalid_format',
      'message', 'Use 3-30 lowercase letters, numbers, and underscores. Start and end with a letter or number.'
    );
  end if;

  if public.community_username_is_reserved(v_username) then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'reserved',
      'message', 'That handle is reserved.'
    );
  end if;

  select user_id into v_existing_user_id
  from public.user_profiles
  where username_normalized = v_username;

  if found and v_existing_user_id = auth.uid() then
    return jsonb_build_object(
      'available', true,
      'normalized', v_username,
      'reason', 'current',
      'message', 'This is your current handle.'
    );
  end if;

  if found then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'taken',
      'message', 'That handle is already taken.'
    );
  end if;

  if exists (
    select 1
    from public.user_profile_username_history h
    where h.old_username_normalized = v_username
      and h.user_id <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)
      and h.created_at > now() - interval '30 days'
  ) then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'recently_released',
      'message', 'That handle was recently released and is temporarily protected.'
    );
  end if;

  return jsonb_build_object(
    'available', true,
    'normalized', v_username,
    'reason', 'available',
    'message', 'Handle available.'
  );
end;
$$

create function public.community_update_username(p_username text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_username text;
  v_profile public.user_profiles%rowtype;
  v_old_username text;
  v_old_username_normalized text;
  v_is_admin boolean;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  perform public.community_ensure_user_account(v_user_id);

  v_username := public.community_normalize_username(p_username);

  if v_username is null or not public.community_username_is_valid(v_username) then
    raise exception 'invalid handle: use 3-30 lowercase letters, numbers, and underscores; start and end with a letter or number';
  end if;

  if public.community_username_is_reserved(v_username) then
    raise exception 'handle % is reserved', v_username;
  end if;

  v_is_admin := public.current_user_is_administrator();

  select * into v_profile
  from public.user_profiles
  where user_id = v_user_id
  for update;

  if not found then
    raise exception 'profile % not found', v_user_id;
  end if;

  if v_profile.username_normalized = v_username then
    return jsonb_build_object(
      'changed', false,
      'profile', public.community_profile_json(v_profile)
    );
  end if;

  if not v_is_admin
    and coalesce(v_profile.username_change_count, 0) > 0
    and v_profile.username_updated_at is not null
    and v_profile.username_updated_at > now() - interval '14 days'
  then
    raise exception 'handle can only be changed once every 14 days';
  end if;

  if exists (
    select 1
    from public.user_profiles up
    where up.username_normalized = v_username
      and up.user_id <> v_user_id
  ) then
    raise exception 'handle % is already taken', v_username;
  end if;

  if exists (
    select 1
    from public.user_profile_username_history h
    where h.old_username_normalized = v_username
      and h.user_id <> v_user_id
      and h.created_at > now() - interval '30 days'
  ) then
    raise exception 'handle % was recently released and is temporarily protected', v_username;
  end if;

  v_old_username := v_profile.username;
  v_old_username_normalized := v_profile.username_normalized;

  update public.user_profiles
  set
    username = v_username,
    username_normalized = v_username,
    username_updated_at = now(),
    username_change_count = coalesce(username_change_count, 0) + 1,
    updated_at = now()
  where user_id = v_user_id
  returning * into v_profile;

  insert into public.user_profile_username_history (
    user_id,
    old_username,
    old_username_normalized,
    new_username,
    new_username_normalized,
    changed_by,
    change_reason
  ) values (
    v_user_id,
    v_old_username,
    v_old_username_normalized,
    v_profile.username,
    v_profile.username_normalized,
    v_user_id,
    'user_update'
  );

  return jsonb_build_object(
    'changed', true,
    'profile', public.community_profile_json(v_profile)
  );
end;
$$

create function public.community_create_profile(
  p_user_id uuid,
  p_username text,
  p_display_name text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid;
  v_username text;
  v_profile public.user_profiles%rowtype;
begin
  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'authentication required';
  end if;

  if p_user_id <> v_actor and not public.current_user_is_administrator() then
    raise exception 'not allowed';
  end if;

  perform public.community_ensure_user_account(p_user_id);

  v_username := public.community_normalize_username(p_username);

  if v_username is null or not public.community_username_is_valid(v_username) then
    raise exception 'invalid handle: use 3-30 lowercase letters, numbers, and underscores; start and end with a letter or number';
  end if;

  if public.community_username_is_reserved(v_username) then
    raise exception 'handle % is reserved', v_username;
  end if;

  if exists (
    select 1
    from public.user_profiles up
    where up.username_normalized = v_username
      and up.user_id <> p_user_id
  ) then
    raise exception 'handle % is already taken', v_username;
  end if;

  update public.user_profiles
  set
    username = v_username,
    username_normalized = v_username,
    display_name = coalesce(nullif(p_display_name, ''), display_name),
    username_updated_at = coalesce(username_updated_at, now()),
    updated_at = now()
  where user_id = p_user_id
  returning * into v_profile;

  return public.community_profile_json(v_profile);
end;
$$

create or replace function public.community_update_comment(
  p_comment_id uuid,
  p_body_markdown text,
  p_body_plain text default null,
  p_body_html text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_comment public.community_comments%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if nullif(trim(coalesce(p_body_markdown, '')), '') is null then
    raise exception 'Comment body cannot be empty' using errcode = '22023';
  end if;

  select *
  into v_comment
  from public.community_comments
  where id = p_comment_id;

  if not found then
    raise exception 'Comment not found' using errcode = 'P0002';
  end if;

  if v_comment.author_id <> auth.uid() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  if v_comment.deleted_at is not null or v_comment.status::text in ('deleted', 'removed', 'spam') then
    raise exception 'Comment is no longer editable' using errcode = 'P0003';
  end if;

  if v_comment.created_at < now() - interval '1 hour' then
    raise exception 'Comment edit window has expired' using errcode = 'P0004';
  end if;

  update public.community_comments
  set
    body_markdown = trim(p_body_markdown),
    body_plain = coalesce(nullif(trim(p_body_plain), ''), trim(p_body_markdown)),
    body_html = p_body_html,
    edited_at = now(),
    updated_at = now()
  where id = p_comment_id
  returning * into v_comment;

  return jsonb_build_object('comment', to_jsonb(v_comment));
end;
$$

create or replace function public.community_save_entity(
  p_entity_type text,
  p_entity_id text default null,
  p_entity_slug text default null,
  p_entity_url text default null,
  p_title text default null,
  p_subtitle text default null,
  p_image_url text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_entity_type text := nullif(trim(coalesce(p_entity_type, '')), '');
  v_entity_id text := nullif(trim(coalesce(p_entity_id, '')), '');
  v_entity_slug text := nullif(trim(coalesce(p_entity_slug, '')), '');
  v_entity_url text := nullif(trim(coalesce(p_entity_url, '')), '');
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_subtitle text := nullif(trim(coalesce(p_subtitle, '')), '');
  v_image_url text := nullif(trim(coalesce(p_image_url, '')), '');
  v_save public.community_saves%rowtype;
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if v_entity_type is null then
    raise exception 'Entity type is required' using errcode = '22023';
  end if;

  if v_title is null then
    raise exception 'Title is required' using errcode = '22023';
  end if;

  if v_entity_id is null and v_entity_slug is null and v_entity_url is null then
    raise exception 'At least one entity identifier is required' using errcode = '22023';
  end if;

  -- Idempotent save: if the user already saved this entity by any known
  -- identifier, refresh its metadata and return saved=true instead of throwing
  -- a duplicate-key 409.
  select *
  into v_save
  from public.community_saves
  where user_id = v_user_id
    and entity_type = v_entity_type
    and (
      (v_entity_id is not null and entity_id = v_entity_id)
      or (v_entity_slug is not null and entity_slug = v_entity_slug)
      or (v_entity_url is not null and entity_url = v_entity_url)
    )
  order by created_at desc
  limit 1;

  if found then
    update public.community_saves
    set
      entity_id = coalesce(v_entity_id, entity_id),
      entity_slug = coalesce(v_entity_slug, entity_slug),
      entity_url = coalesce(v_entity_url, entity_url),
      title = v_title,
      subtitle = v_subtitle,
      image_url = v_image_url
    where id = v_save.id
    returning * into v_save;

    return jsonb_build_object(
      'saved', true,
      'existing', true,
      'save', to_jsonb(v_save)
    );
  end if;

  begin
    insert into public.community_saves (
      user_id,
      entity_type,
      entity_id,
      entity_slug,
      entity_url,
      title,
      subtitle,
      image_url
    ) values (
      v_user_id,
      v_entity_type,
      v_entity_id,
      v_entity_slug,
      v_entity_url,
      v_title,
      v_subtitle,
      v_image_url
    )
    returning * into v_save;
  exception when unique_violation then
    -- In case a unique index catches a duplicate not found above, normalize it
    -- into saved=true instead of leaking a 409 to the browser.
    select *
    into v_save
    from public.community_saves
    where user_id = v_user_id
      and entity_type = v_entity_type
      and (
        (v_entity_id is not null and entity_id = v_entity_id)
        or (v_entity_slug is not null and entity_slug = v_entity_slug)
        or (v_entity_url is not null and entity_url = v_entity_url)
      )
    order by created_at desc
    limit 1;

    if found then
      update public.community_saves
      set
        entity_id = coalesce(v_entity_id, entity_id),
        entity_slug = coalesce(v_entity_slug, entity_slug),
        entity_url = coalesce(v_entity_url, entity_url),
        title = v_title,
        subtitle = v_subtitle,
        image_url = v_image_url
      where id = v_save.id
      returning * into v_save;

      return jsonb_build_object(
        'saved', true,
        'existing', true,
        'save', to_jsonb(v_save)
      );
    end if;

    raise;
  end;

  return jsonb_build_object(
    'saved', true,
    'existing', false,
    'save', to_jsonb(v_save)
  );
end;
$$

