create or replace function public.admin_create_registry_artist_for_decouple(
  p_display_name text,
  p_slug text default null,
  p_status text default 'needs_review',
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_display_name text;
  v_slug text;
  v_status text;
  v_artist record;
  v_created boolean := false;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_display_name := nullif(trim(coalesce(p_display_name, '')), '');
  if v_display_name is null then
    raise exception 'display_name_required';
  end if;

  v_slug := public.wk_slugify_text(coalesce(nullif(trim(p_slug), ''), v_display_name));
  if v_slug = '' then
    raise exception 'artist_slug_required';
  end if;

  v_status := coalesce(nullif(trim(p_status), ''), 'needs_review');
  if v_status not in ('active', 'draft', 'needs_review') then
    raise exception 'invalid_artist_status';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url
  into v_artist
  from public.registry_artists
  where lower(slug) = lower(v_slug)
  limit 1;

  if v_artist.id is null then
    insert into public.registry_artists (
      slug,
      display_name,
      normalized_name,
      sort_name,
      status,
      metadata
    )
    values (
      v_slug,
      v_display_name,
      lower(regexp_replace(v_display_name, '\s+', ' ', 'g')),
      v_display_name,
      v_status,
      jsonb_build_object(
        'created_for', 'artist_decouple',
        'created_from_admin_decouple', true,
        'decouple_note', p_note,
        'created_at', now()
      )
    )
    returning id, slug, display_name, status, origin_iso2, public_image_url
    into v_artist;

    v_created := true;
  end if;

  return jsonb_build_object(
    'created', v_created,
    'artist', jsonb_build_object(
      'artist_id', v_artist.id,
      'artist_slug', v_artist.slug,
      'display_name', v_artist.display_name,
      'status', v_artist.status,
      'origin_iso2', v_artist.origin_iso2,
      'public_image_url', v_artist.public_image_url,
      'track_credit_count', 0,
      'release_credit_count', 0
    )
  );
end;
$$

create or replace function public.admin_log_artist_resolution_event(
  p_action text,
  p_status text,
  p_source_artist_id uuid default null,
  p_source_snapshot jsonb default '{}'::jsonb,
  p_replacement_artists jsonb default '[]'::jsonb,
  p_track_links jsonb default '[]'::jsonb,
  p_release_links jsonb default '[]'::jsonb,
  p_chart_entries jsonb default '[]'::jsonb,
  p_note text default null,
  p_error_message text default null,
  p_result jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_action text;
  v_status text;
  v_source_snapshot jsonb;
  v_event_id uuid;
  v_source_artist_id uuid;
  v_source_artist_slug text;
  v_source_artist_name text;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_action := nullif(trim(coalesce(p_action, '')), '');
  v_status := nullif(trim(coalesce(p_status, '')), '');

  if v_action not in ('alias_merge', 'artist_merge', 'artist_decouple') then
    raise exception 'invalid_resolution_action';
  end if;

  if v_status not in ('success', 'failed', 'cancelled') then
    raise exception 'invalid_resolution_status';
  end if;

  v_source_snapshot := coalesce(p_source_snapshot, '{}'::jsonb);
  v_source_artist_id := coalesce(
    p_source_artist_id,
    nullif(v_source_snapshot->>'artist_id', '')::uuid
  );
  v_source_artist_slug := nullif(coalesce(
    v_source_snapshot->>'artist_slug',
    v_source_snapshot->>'slug'
  ), '');
  v_source_artist_name := nullif(coalesce(
    v_source_snapshot->>'display_name',
    v_source_snapshot->>'name'
  ), '');

  if v_source_artist_id is not null then
    select
      coalesce(v_source_artist_slug, a.slug),
      coalesce(v_source_artist_name, a.display_name)
    into v_source_artist_slug, v_source_artist_name
    from public.registry_artists a
    where a.id = v_source_artist_id
    limit 1;
  end if;

  insert into public.registry_artist_resolution_events (
    action,
    status,
    source_artist_id,
    source_artist_slug,
    source_artist_name,
    source_snapshot,
    replacement_artists,
    track_links,
    release_links,
    chart_entries,
    note,
    error_message,
    result
  )
  values (
    v_action,
    v_status,
    v_source_artist_id,
    v_source_artist_slug,
    v_source_artist_name,
    v_source_snapshot,
    coalesce(p_replacement_artists, '[]'::jsonb),
    coalesce(p_track_links, '[]'::jsonb),
    coalesce(p_release_links, '[]'::jsonb),
    coalesce(p_chart_entries, '[]'::jsonb),
    nullif(p_note, ''),
    nullif(p_error_message, ''),
    coalesce(p_result, '{}'::jsonb)
  )
  returning id into v_event_id;

  return jsonb_build_object('eventId', v_event_id);
end;
$$

