alter table public.registry_entity_relationships
  add column if not exists source_entity_id uuid,
  add column if not exists target_entity_id uuid,
  add column if not exists plain_reason text,
  add column if not exists review_status text not null default 'unreviewed',
  add column if not exists public_safe boolean not null default false,
  add column if not exists valid_from date,
  add column if not exists valid_to date,
  add column if not exists reviewed_by uuid references auth.users(id) on delete set null,
  add column if not exists reviewed_at timestamptz,
  add column if not exists review_note text,
  add column if not exists status_reason text,
  add column if not exists superseded_by_relationship_id uuid references public.registry_entity_relationships(id) on delete set null,
  add column if not exists created_by uuid references auth.users(id) on delete set null,
  add column if not exists updated_by uuid references auth.users(id) on delete set null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'registry_entity_relationships_review_status_check') then
    alter table public.registry_entity_relationships
      add constraint registry_entity_relationships_review_status_check
      check (review_status in ('unreviewed','pending_review','approved','rejected','disputed','superseded')) not valid;
  end if;
end $$;

alter table public.registry_entity_relationships validate constraint registry_entity_relationships_review_status_check;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'registry_entity_relationships_valid_period_check') then
    alter table public.registry_entity_relationships
      add constraint registry_entity_relationships_valid_period_check
      check (valid_to is null or valid_from is null or valid_to >= valid_from) not valid;
  end if;
end $$;

alter table public.registry_entity_relationships validate constraint registry_entity_relationships_valid_period_check;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'registry_entity_relationships_review_fields_check') then
    alter table public.registry_entity_relationships
      add constraint registry_entity_relationships_review_fields_check
      check (review_status not in ('approved','rejected','disputed','superseded') or reviewed_at is not null) not valid;
  end if;
end $$;

alter table public.registry_entity_relationships validate constraint registry_entity_relationships_review_fields_check;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'registry_entity_relationships_supersession_check') then
    alter table public.registry_entity_relationships
      add constraint registry_entity_relationships_supersession_check
      check (review_status <> 'superseded' or superseded_by_relationship_id is not null) not valid;
  end if;
end $$;

alter table public.registry_entity_relationships validate constraint registry_entity_relationships_supersession_check;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'registry_entity_relationships_public_safe_check') then
    alter table public.registry_entity_relationships
      add constraint registry_entity_relationships_public_safe_check
      check (public_safe = false or (review_status = 'approved' and relationship_status = 'active' and reviewed_at is not null)) not valid;
  end if;
end $$;

alter table public.registry_entity_relationships validate constraint registry_entity_relationships_public_safe_check;

