create or replace function editorial.assert_resource_binding_integrity()
returns trigger
language plpgsql
set search_path = pg_catalog, editorial
as $function$
declare
  target_resource_id uuid;
  target_kind text;
  binding_count integer;
begin
  if tg_table_name = 'resources' then
    if tg_op = 'DELETE' then
      return null;
    end if;

    target_resource_id := new.id;
  else
    if tg_op = 'DELETE' then
      target_resource_id := old.resource_id;
    else
      target_resource_id := new.resource_id;
    end if;
  end if;

  select resource_kind
    into target_kind
  from editorial.resources
  where id = target_resource_id;

  if not found then
    return null;
  end if;

  case target_kind
    when 'article' then
      select count(*)
        into binding_count
      from editorial.article_resources
      where resource_id = target_resource_id;

    when 'playlist' then
      select count(*)
        into binding_count
      from editorial.playlist_resources
      where resource_id = target_resource_id;

    when 'registry_artist' then
      select count(*)
        into binding_count
      from editorial.registry_artist_resources
      where resource_id = target_resource_id;

    else
      raise exception
        'Unsupported resource kind: %',
        target_kind;
  end case;

  if binding_count <> 1 then
    raise exception
      'Resource % with kind % must have exactly one typed binding.',
      target_resource_id,
      target_kind;
  end if;

  return null;
end
$function$

-- Phase 2A: durable Article drafts and immutable versions.
--
-- This migration establishes:
-- 1. monotonic Article draft versions
-- 2. complete immutable Article snapshots
-- 3. normalized Article taxonomy relationships
-- 4. resource version pointers
-- 5. durable autosave and recovery commands
-- 6. transactional Article saves and slug redirects
-- 7. resource-based ownership enforcement

do $phase_2a_preflight$
declare
  revision_count bigint;
begin
  if to_regclass('public.wk_articles') is null then
    raise exception 'STOP: public.wk_articles does not exist';
  end if;

  if to_regclass('public.wk_article_revisions') is null then
    raise exception 'STOP: public.wk_article_revisions does not exist';
  end if;

  if to_regclass('editorial.resources') is null then
    raise exception 'STOP: editorial.resources does not exist';
  end if;

  if to_regclass('editorial.article_resources') is null then
    raise exception 'STOP: editorial.article_resources does not exist';
  end if;

  if to_regclass('public.registry_taxonomy_terms') is null then
    raise exception 'STOP: public.registry_taxonomy_terms does not exist';
  end if;

  select count(*)
  into revision_count
  from public.wk_article_revisions;

  if revision_count <> 0 then
    raise exception
      'STOP: Expected zero legacy Article revisions, found %',
      revision_count;
  end if;
end;
$phase_2a_preflight$

create or replace function editorial.protect_article_version()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, editorial
as $function$
begin
  if tg_op = 'UPDATE' then
    raise exception 'Article versions are immutable';
  end if;

  if old.version_kind in ('baseline', 'submitted') then
    raise exception
      'Baseline and submitted Article versions cannot be deleted';
  end if;

  if exists (
    select 1
    from editorial.resources resource
    where resource.current_working_version_id = old.id
       or resource.current_submitted_version_id = old.id
  ) then
    raise exception
      'An Article version referenced by a resource pointer cannot be deleted';
  end if;

  return old;
end;
$function$

do $article_resource_backfill_gate$
declare
  article_count bigint;
  binding_count bigint;
begin
  select count(*)
  into article_count
  from public.wk_articles;

  select count(*)
  into binding_count
  from editorial.article_resources;

  if article_count <> binding_count then
    raise exception
      'STOP: Expected one resource binding for each Article. Articles %, bindings %',
      article_count,
      binding_count;
  end if;
end;
$article_resource_backfill_gate$

create or replace function editorial.current_user_can_edit_article(
  p_resource_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, editorial
as $function$
  select
    auth.uid() is not null
    and (
      public.current_user_is_administrator()
      or public.current_user_has_capability(
        'edit_others_articles'
      )
      or (
        public.current_user_has_capability(
          'edit_own_articles'
        )
        and exists (
          select 1
          from editorial.resources resource
          where resource.id = p_resource_id
            and resource.owner_id = auth.uid()
        )
      )
    );
$function$

create policy article_versions_authenticated_read
on editorial.article_versions
for select
to authenticated
using (
  editorial.current_user_can_edit_article(
    resource_id
  )
  or version_kind = 'submitted'
)

create policy article_taxonomy_terms_authenticated_read
on editorial.article_taxonomy_terms
for select
to authenticated
using (
  editorial.current_user_can_edit_article(
    resource_id
  )
)

do $phase_2a_exit_gate$
declare
  article_count bigint;
  binding_count bigint;
  baseline_count bigint;
  pointer_count bigint;
begin
  select count(*)
  into article_count
  from public.wk_articles;

  select count(*)
  into binding_count
  from editorial.article_resources;

  select count(*)
  into baseline_count
  from editorial.article_versions
  where version_kind = 'baseline';

  select count(*)
  into pointer_count
  from editorial.resources
  where resource_kind = 'article'
    and current_working_version_id is not null;

  if binding_count <> article_count then
    raise exception
      'STOP: Article resource binding count mismatch';
  end if;

  if baseline_count <> article_count then
    raise exception
      'STOP: Article baseline version count mismatch';
  end if;

  if pointer_count <> article_count then
    raise exception
      'STOP: Article working version pointer count mismatch';
  end if;

  if exists (
    select 1
    from editorial.article_versions version
    join editorial.resources resource
      on resource.id = version.resource_id
    where resource.resource_kind <> 'article'
  ) then
    raise exception
      'STOP: Article version attached to a non-Article resource';
  end if;
end;
$phase_2a_exit_gate$

do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'wk_article_publication_snapshots'
      and policyname = 'Active article publication snapshots are public readable'
  ) then
    create policy "Active article publication snapshots are public readable"
      on public.wk_article_publication_snapshots
      for select
      using (is_active = true);
  end if;
end;
$$

create or replace function public.submit_article_for_review(
  p_article_id uuid,
  p_expected_draft_version bigint,
  p_note text default null
)
returns table (
  article_id uuid,
  article_slug text,
  draft_version bigint,
  version_id uuid,
  version_number bigint,
  lifecycle_status text
)
language plpgsql
security definer
set search_path = pg_catalog, public, editorial
as $function$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_prior_status text;
  v_version_id uuid;
  v_version_number bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_edit_article(v_resource.id) then
    raise exception 'Permission denied';
  end if;

  if v_article.draft_version <> p_expected_draft_version then
    raise exception
      'STALE_ARTICLE_VERSION: expected %, current %',
      p_expected_draft_version,
      v_article.draft_version;
  end if;

  v_prior_status := v_article.wp_status;

  update public.wk_articles as article
  set
    wp_status = 'pending',
    draft_version = article.draft_version + 1,
    updated_at = now(),
    modified_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  select created.version_id, created.version_number
  into v_version_id, v_version_number
  from editorial.insert_article_lifecycle_version_from_article(
    v_resource,
    v_article,
    'submitted',
    'submitted'
  ) created;

  update editorial.resources
  set
    current_submitted_version_id = v_version_id,
    lifecycle_state = 'active',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_version_id,
    'submitted',
    v_prior_status,
    'pending',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_version_id;
  version_number := v_version_number;
  lifecycle_status := 'submitted';
  return next;
end;
$function$

