create or replace function public.publish_due_article_publications(
  p_limit integer default 25
)
returns table (
  article_id uuid,
  article_slug text,
  schedule_id uuid,
  version_id uuid,
  published_at timestamptz,
  status text
)
language plpgsql
security definer
set search_path = pg_catalog, public, editorial
as $function$
declare
  due_schedule editorial.article_scheduled_publications%rowtype;
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_version_id uuid;
  v_version_number bigint;
  v_limit integer;
begin
  if auth.role() <> 'service_role'
     and not editorial.current_user_can_publish_article()
  then
    raise exception 'Permission denied';
  end if;

  v_limit := least(greatest(coalesce(p_limit, 25), 1), 100);

  for due_schedule in
    select scheduled.*
    from editorial.article_scheduled_publications scheduled
    where scheduled.status = 'scheduled'
      and scheduled.run_after <= now()
    order by scheduled.run_after asc
    limit v_limit
    for update skip locked
  loop
    select article.*
    into v_article
    from public.wk_articles article
    where article.id = due_schedule.article_id
    for update;

    if not found then
      update editorial.article_scheduled_publications
      set
        status = 'failed',
        updated_at = now()
      where id = due_schedule.id;

      continue;
    end if;

    select resource.*
    into v_resource
    from editorial.resources resource
    where resource.id = due_schedule.resource_id
    for update;

    if not found then
      update editorial.article_scheduled_publications
      set
        status = 'failed',
        updated_at = now()
      where id = due_schedule.id;

      continue;
    end if;

    select copied.version_id, copied.version_number
    into v_version_id, v_version_number
    from editorial.copy_article_lifecycle_version(
      due_schedule.version_id,
      'published',
      'published',
      'publish',
      due_schedule.run_after
    ) copied;

    perform editorial.publish_article_snapshot(
      v_version_id,
      due_schedule.run_after,
      true
    );

    update public.wk_articles as article
    set
      wp_status = 'publish',
      published_at = due_schedule.run_after,
      updated_at = now()
    where article.id = due_schedule.article_id
    returning article.*
    into v_article;

    update editorial.resources
    set
      current_published_version_id = v_version_id,
      lifecycle_state = 'published',
      visibility = 'public',
      updated_at = now()
    where id = due_schedule.resource_id;

    update editorial.article_scheduled_publications
    set
      status = 'published',
      updated_at = now()
    where id = due_schedule.id;

    insert into editorial.article_lifecycle_events (
      resource_id,
      article_id,
      version_id,
      action,
      prior_status,
      resulting_status,
      note,
      metadata
    )
    values (
      due_schedule.resource_id,
      due_schedule.article_id,
      v_version_id,
      'published',
      'future',
      'publish',
      due_schedule.note,
      jsonb_build_object(
        'scheduledPublicationId',
        due_schedule.id,
        'scheduledFor',
        due_schedule.run_after
      )
    );

    article_id := due_schedule.article_id;
    article_slug := v_article.slug;
    schedule_id := due_schedule.id;
    version_id := v_version_id;
    published_at := due_schedule.run_after;
    status := 'published';
    return next;
  end loop;
end;
$function$

create or replace function public.create_article_preview_link(
  p_article_id uuid,
  p_version_id uuid default null,
  p_expires_at timestamptz default null
)
returns table (
  nonce text,
  expires_at timestamptz,
  version_id uuid
)
language plpgsql
security definer
set search_path = public, editorial, pg_temp
as $$
declare
  v_version editorial.article_versions%rowtype;
  v_nonce text := gen_random_uuid()::text;
  v_expires_at timestamptz := coalesce(
    p_expires_at,
    now() + interval '7 days'
  );
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_article_id is null then
    raise exception 'article id is required';
  end if;

  if v_expires_at <= now() then
    raise exception 'preview expiry must be in the future';
  end if;

  if p_version_id is null then
    select version.*
      into v_version
    from editorial.article_versions version
    where version.article_id = p_article_id
    order by version.version_number desc
    limit 1;
  else
    select version.*
      into v_version
    from editorial.article_versions version
    where version.id = p_version_id
      and version.article_id = p_article_id
    limit 1;
  end if;

  if v_version.id is null then
    raise exception 'article version not found';
  end if;

  insert into public.wk_article_preview_links (
    nonce,
    article_id,
    version_id,
    created_by,
    expires_at
  )
  values (
    v_nonce,
    p_article_id,
    v_version.id,
    auth.uid(),
    v_expires_at
  );

  update public.wk_articles article
     set preview_nonce = v_nonce,
         preview_nonce_expires_at = v_expires_at,
         updated_at = now()
   where article.id = p_article_id;

  return query
  select
    v_nonce,
    v_expires_at,
    v_version.id;
end;
$$

