create or replace function public.accept_article_suggestion(
  p_suggestion_id uuid,
  p_expected_draft_version bigint,
  p_note text default null
)
returns table (
  suggestion_id uuid,
  decision_status text,
  article_id uuid,
  article_slug text,
  draft_version bigint,
  applied_version_id uuid,
  applied_version_number bigint
)
language plpgsql
security definer
set search_path = pg_catalog, public, editorial
as $function$
declare
  v_suggestion editorial.article_suggestions%rowtype;
  v_thread editorial.article_review_threads%rowtype;
  v_resource editorial.resources%rowtype;
  v_article public.wk_articles%rowtype;
  v_target editorial.article_versions%rowtype;

  v_new_version_id uuid;
  v_new_version_number bigint;
  v_decided_at timestamptz := now();
  v_prior_status text;

  v_stale record;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_review_article() then
    raise exception 'Permission denied';
  end if;

  select suggestion.*
  into v_suggestion
  from editorial.article_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception 'Article suggestion not found';
  end if;

  if v_suggestion.status <> 'open' then
    raise exception 'Only open suggestions can be accepted';
  end if;

  select thread.*
  into v_thread
  from editorial.article_review_threads thread
  where thread.id = v_suggestion.thread_id
  for update;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id = v_thread.resource_id
  for update;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = v_thread.article_id
  for update;

  select version.*
  into v_target
  from editorial.article_versions version
  where version.id = v_thread.target_version_id;

  if not found then
    raise exception 'Suggestion target version not found';
  end if;

  if v_resource.current_submitted_version_id
       is distinct from v_thread.target_version_id
     or v_article.wp_status <> 'pending'
     or v_target.content_fingerprint
       <> v_suggestion.target_version_fingerprint
  then
    update editorial.article_suggestions
    set
      status = 'stale',
      decided_by = auth.uid(),
      decided_at = v_decided_at,
      decision_note =
        'Suggestion no longer targets the active submitted version'
    where id = p_suggestion_id;

    update editorial.article_review_threads
    set
      status = 'resolved',
      resolved_by = auth.uid(),
      resolved_at = v_decided_at
    where id = v_thread.id;

    insert into editorial.article_suggestion_events (
      suggestion_id,
      action,
      note
    )
    values (
      p_suggestion_id,
      'marked_stale',
      'Suggestion no longer targets the active submitted version'
    );

    suggestion_id := p_suggestion_id;
    decision_status := 'stale';
    article_id := v_article.id;
    article_slug := v_article.slug;
    draft_version := v_article.draft_version;
    applied_version_id := null;
    applied_version_number := null;
    return next;
    return;
  end if;

  v_prior_status := v_article.wp_status;

  select
    persisted.version_id,
    persisted.version_number
  into
    v_new_version_id,
    v_new_version_number
  from editorial.apply_article_review_snapshot(
    v_article.id,
    v_resource.id,
    p_expected_draft_version,
    v_suggestion.proposed_content_html
  ) persisted;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = v_thread.article_id;

  update editorial.article_suggestions
  set
    status = 'accepted',
    decided_by = auth.uid(),
    decided_at = v_decided_at,
    decision_note = nullif(btrim(coalesce(p_note, '')), ''),
    applied_version_id = v_new_version_id
  where id = p_suggestion_id;

  update editorial.article_review_threads
  set
    status = 'resolved',
    resolved_by = auth.uid(),
    resolved_at = v_decided_at
  where id = v_thread.id;

  insert into editorial.article_suggestion_events (
    suggestion_id,
    action,
    note,
    applied_version_id
  )
  values (
    p_suggestion_id,
    'accepted',
    nullif(btrim(coalesce(p_note, '')), ''),
    v_new_version_id
  );

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note,
    metadata
  )
  values (
    v_resource.id,
    v_article.id,
    v_thread.target_version_id,
    'changes_requested',
    v_prior_status,
    'draft',
    coalesce(
      nullif(btrim(coalesce(p_note, '')), ''),
      'Accepted editorial suggestion'
    ),
    jsonb_build_object(
      'suggestion_id',
      p_suggestion_id,
      'applied_version_id',
      v_new_version_id,
      'decision',
      'accepted',
      'review_round_closed',
      true,
      'remaining_open_suggestions_marked_stale',
      true
    )
  );

  -- Quality PR 2 deliberately accepts at most one
  -- suggestion from a submitted review round. Every suggestion stores
  -- a complete proposed document snapshot. Remaining suggestions cannot
  -- be silently rebased after the Article returns to draft.
  for v_stale in
    update editorial.article_suggestions suggestion
    set
      status = 'stale',
      decided_by = auth.uid(),
      decided_at = v_decided_at,
      decision_note =
        'Review round closed after another suggestion was accepted; resubmission is required before reconsideration'
    from editorial.article_review_threads competing_thread
    where competing_thread.id = suggestion.thread_id
      and competing_thread.target_version_id =
        v_thread.target_version_id
      and suggestion.id <> p_suggestion_id
      and suggestion.status = 'open'
    returning
      suggestion.id,
      suggestion.thread_id
  loop
    update editorial.article_review_threads
    set
      status = 'resolved',
      resolved_by = auth.uid(),
      resolved_at = v_decided_at
    where id = v_stale.thread_id;

    insert into editorial.article_suggestion_events (
      suggestion_id,
      action,
      note
    )
    values (
      v_stale.id,
      'marked_stale',
      'Review round closed after another suggestion was accepted; resubmission is required before reconsideration'
    );
  end loop;

  suggestion_id := p_suggestion_id;
  decision_status := 'accepted';
  article_id := v_article.id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  applied_version_id := v_new_version_id;
  applied_version_number := v_new_version_number;
  return next;
end;
$function$

revoke all on function
  public.accept_article_suggestion(uuid, bigint, text)
from public

grant execute on function
  public.accept_article_suggestion(uuid, bigint, text)
to authenticated

do $restore$
declare
  v_article_id constant uuid :=
    '30027d46-113e-475b-818e-ce4383c5865a';

  v_resource_id constant uuid :=
    '221d781c-c3d9-4caf-acf5-6a5a2e712d44';

  v_accepted_version_id constant uuid :=
    'bd55c762-1409-4324-a40f-b774c4c89528';

  v_stale_working_version_id constant uuid :=
    '5266ec05-45dc-43a3-9fd8-e25306d38c6e';

  v_stale_submitted_version_id constant uuid :=
    '52687a72-bc9a-448c-8e58-31f35ab3243d';

  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_accepted editorial.article_versions%rowtype;
  v_actor_id uuid;
begin
  select article.*
  into v_article
  from public.wk_articles article
  where article.id = v_article_id
  for update;

  if not found then
    raise exception 'Restore stopped: Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id = v_resource_id
  for update;

  if not found then
    raise exception 'Restore stopped: resource not found';
  end if;

  select version.*
  into v_accepted
  from editorial.article_versions version
  where version.id = v_accepted_version_id;

  if not found then
    raise exception 'Restore stopped: accepted version 33 not found';
  end if;

  select suggestion.decided_by
  into v_actor_id
  from editorial.article_suggestions suggestion
  where suggestion.applied_version_id =
    v_accepted_version_id
    and suggestion.status = 'accepted'
  order by suggestion.decided_at desc
  limit 1;

  if v_article.wp_status <> 'draft'
     or v_article.draft_version <> 32
  then
    raise exception
      'Restore stopped: Article state changed';
  end if;

  if v_resource.current_working_version_id
       is distinct from v_stale_working_version_id
     or v_resource.current_submitted_version_id
       is distinct from v_stale_submitted_version_id
  then
    raise exception
      'Restore stopped: version pointers changed';
  end if;

  if v_accepted.version_number <> 33
     or v_accepted.version_kind <> 'review_applied'
     or v_accepted.wp_status <> 'draft'
     or v_accepted.article_id <> v_article_id
     or v_accepted.resource_id <> v_resource_id
  then
    raise exception
      'Restore stopped: version 33 is not authoritative';
  end if;

  if strpos(
    v_accepted.content_html,
    'No simulated cassette noise.'
  ) = 0 then
    raise exception
      'Restore stopped: accepted wording is missing';
  end if;

  if strpos(
    v_accepted.content_html,
    'No fake cassette noise.'
  ) > 0 then
    raise exception
      'Restore stopped: version 33 contains stale wording';
  end if;

  if strpos(
    v_article.content_html,
    'No fake cassette noise.'
  ) = 0 then
    raise exception
      'Restore stopped: current Article no longer matches stale state';
  end if;

  update public.wk_articles
  set
    content_html = v_accepted.content_html,
    wp_status = 'draft',
    draft_version = draft_version + 1,
    modified_at = now(),
    updated_at = now()
  where id = v_article_id;

  update editorial.resources
  set
    current_working_version_id =
      v_accepted_version_id,
    current_submitted_version_id =
      null,
    lifecycle_state = 'draft',
    visibility = 'private',
    updated_at = now()
  where id = v_resource_id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note,
    metadata,
    actor_id
  )
  values (
    v_resource_id,
    v_article_id,
    v_accepted_version_id,
    'restored',
    'draft',
    'draft',
    'Restored accepted review-applied version 33 after editor hydration verification.',
    jsonb_build_object(
      'repair_kind',
      'restore_existing_review_applied_version',
      'accepted_version_id',
      v_accepted_version_id,
      'replaced_working_version_id',
      v_stale_working_version_id,
      'cleared_submitted_version_id',
      v_stale_submitted_version_id
    ),
    v_actor_id
  );

  if not exists (
    select 1
    from public.wk_articles article
    where article.id = v_article_id
      and article.wp_status = 'draft'
      and article.draft_version = 33
      and strpos(
        article.content_html,
        'No simulated cassette noise.'
      ) > 0
      and strpos(
        article.content_html,
        'No fake cassette noise.'
      ) = 0
  ) then
    raise exception
      'Restore stopped: Article assertion failed';
  end if;

  if not exists (
    select 1
    from editorial.resources resource
    where resource.id = v_resource_id
      and resource.current_working_version_id =
        v_accepted_version_id
      and resource.current_submitted_version_id
        is null
      and resource.lifecycle_state = 'draft'
  ) then
    raise exception
      'Restore stopped: resource assertion failed';
  end if;

  raise notice
    'Restored accepted review-applied version 33 as the working draft';
end;
$restore$

