do $phase_4a_m3_runtime_acceptance$
declare
  v_actor constant uuid :=
    'f4a30000-0000-4000-8000-000000000001';
  v_asset_corr constant uuid :=
    'f4a30000-0000-4000-8000-000000000101';
  v_revision_corr constant uuid :=
    'f4a30000-0000-4000-8000-000000000102';

  v_asset record;
  v_original record;
  v_revision record;
  v_derived_one record;
  v_derived_two record;
  v_variant_one record;
  v_variant_two record;
  v_selection record;
  v_governance record;
  v_lifecycle record;

  v_asset_id uuid;
  v_original_id uuid;
  v_revision_id uuid;
  v_derived_one_id uuid;
  v_derived_two_id uuid;
  v_variant_one_id uuid;
  v_variant_two_id uuid;

  v_blocked boolean;
  v_rejected boolean;
  v_event_count bigint;
begin
  perform set_config(
    'request.jwt.claim.role',
    'authenticated',
    true
  );
  perform set_config(
    'request.jwt.claim.sub',
    v_actor::text,
    true
  );
  perform set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'role',
      'authenticated',
      'sub',
      v_actor
    )::text,
    true
  );

  if auth.uid() is distinct from v_actor
     or not public.current_user_is_administrator()
  then
    raise exception 'STOP: M3 verifier actor context failed';
  end if;

  select *
  into v_asset
  from public.create_media_asset(
    'image',
    'general',
    'Phase 4A M3 verifier asset',
    null,
    v_asset_corr
  );

  v_asset_id := v_asset.asset_id;

  if v_asset.authority_revision <> 1
     or v_asset.correlation_id is distinct from v_asset_corr
  then
    raise exception 'STOP: create_media_asset failed';
  end if;

  select *
  into v_original
  from public.register_media_file_object(
    'lightsail_media',
    'phase4a-m3-verifier',
    'phase4a/m3/verifier/original.png',
    'https://media.invalid/phase4a/m3/original.png',
    'original.png',
    'image/png',
    3,
    '{"width":1,"height":1}'::jsonb,
    gen_random_uuid()
  );

  v_original_id := v_original.file_object_id;

  perform 1
  from public.verify_media_file_object(
    v_original_id,
    'verified',
    repeat('a', 64),
    3,
    'image/png',
    '{"width":1,"height":1}'::jsonb,
    null,
    gen_random_uuid()
  );

  select *
  into v_revision
  from public.create_media_asset_revision(
    v_asset_id,
    1,
    v_original_id,
    'Create verifier revision 1',
    v_revision_corr
  );

  v_revision_id := v_revision.asset_revision_id;

  if v_revision.revision_number <> 1
     or v_revision.authority_revision <> 2
  then
    raise exception 'STOP: create_media_asset_revision failed';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.create_media_asset_revision(
      v_asset_id,
      1,
      v_original_id,
      'Stale verifier revision',
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'stale media authority revision'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception 'STOP: Stale authority revision was accepted';
  end if;

  select *
  into v_derived_one
  from public.register_media_file_object(
    'lightsail_media',
    'phase4a-m3-verifier',
    'phase4a/m3/verifier/thumbnail-one.png',
    'https://media.invalid/phase4a/m3/thumbnail-one.png',
    'thumbnail-one.png',
    'image/png',
    2,
    '{}'::jsonb,
    gen_random_uuid()
  );

  v_derived_one_id := v_derived_one.file_object_id;

  perform 1
  from public.verify_media_file_object(
    v_derived_one_id,
    'verified',
    repeat('b', 64),
    2,
    'image/png',
    '{}'::jsonb,
    null,
    gen_random_uuid()
  );

  select *
  into v_variant_one
  from public.register_media_variant(
    v_asset_id,
    v_revision_id,
    v_original_id,
    v_derived_one_id,
    'thumbnail',
    '{"operation":"resize","width":1}'::jsonb,
    '{"width":1,"height":1}'::jsonb,
    'phase4a-m3-verifier',
    '1',
    gen_random_uuid()
  );

  v_variant_one_id := v_variant_one.variant_id;

  select *
  into v_selection
  from public.activate_media_variant(
    v_revision_id,
    'thumbnail',
    v_variant_one_id,
    0,
    'Activate verifier thumbnail one',
    gen_random_uuid()
  );

  if v_selection.selection_revision <> 1 then
    raise exception 'STOP: First variant activation failed';
  end if;

  select *
  into v_derived_two
  from public.register_media_file_object(
    'lightsail_media',
    'phase4a-m3-verifier',
    'phase4a/m3/verifier/thumbnail-two.png',
    'https://media.invalid/phase4a/m3/thumbnail-two.png',
    'thumbnail-two.png',
    'image/png',
    2,
    '{}'::jsonb,
    gen_random_uuid()
  );

  v_derived_two_id := v_derived_two.file_object_id;

  perform 1
  from public.verify_media_file_object(
    v_derived_two_id,
    'verified',
    repeat('c', 64),
    2,
    'image/png',
    '{}'::jsonb,
    null,
    gen_random_uuid()
  );

  select *
  into v_variant_two
  from public.register_media_variant(
    v_asset_id,
    v_revision_id,
    v_original_id,
    v_derived_two_id,
    'thumbnail',
    '{"operation":"resize","width":1,"revision":2}'::jsonb,
    '{"width":1,"height":1}'::jsonb,
    'phase4a-m3-verifier',
    '2',
    gen_random_uuid()
  );

  v_variant_two_id := v_variant_two.variant_id;

  select *
  into v_selection
  from public.activate_media_variant(
    v_revision_id,
    'thumbnail',
    v_variant_two_id,
    1,
    'Activate verifier thumbnail two',
    gen_random_uuid()
  );

  if v_selection.selection_revision <> 2 then
    raise exception 'STOP: Replacement variant activation failed';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.activate_media_variant(
      v_revision_id,
      'thumbnail',
      v_variant_one_id,
      1,
      'Stale verifier selection',
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'stale media selection revision'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception 'STOP: Stale selection revision was accepted';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.create_media_governance_version(
      v_asset_id,
      2,
      jsonb_build_object(
        'rights_status',
        'owned'
      ),
      'Incomplete verifier governance',
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'complete media governance state payload is required'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception
      'STOP: Incomplete governance payload was accepted';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.create_media_governance_version(
      v_asset_id,
      2,
      jsonb_build_object(
        'rights_status',
        'owned',
        'consent_status',
        'not_required',
        'sensitivity',
        'none',
        'embargo_state',
        'none',
        'source_protection_class',
        'internal',
        'preservation_state',
        'working_copy',
        'retention_state',
        'purge_approved',
        'public_safety_state',
        'internal'
      ),
      'Illegal verifier retention approval',
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'media retention actions require dedicated retention commands'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception
      'STOP: Governance command bypassed retention authority';
  end if;

  select *
  into v_governance
  from public.create_media_governance_version(
    v_asset_id,
    2,
    jsonb_build_object(
      'rights_status',
      'owned',
      'consent_status',
      'not_required',
      'sensitivity',
      'none',
      'embargo_state',
      'none',
      'source_protection_class',
      'internal',
      'preservation_state',
      'working_copy',
      'retention_state',
      'retain',
      'public_safety_state',
      'internal'
    ),
    'Create verifier governance version 2',
    gen_random_uuid()
  );

  if v_governance.version_number <> 2
     or v_governance.authority_revision <> 3
  then
    raise exception 'STOP: Governance version activation failed';
  end if;

  select *
  into v_lifecycle
  from public.archive_media_asset(
    v_asset_id,
    3,
    'Archive verifier asset',
    gen_random_uuid()
  );

  if v_lifecycle.lifecycle_state <> 'archived'
     or v_lifecycle.authority_revision <> 4
  then
    raise exception 'STOP: Asset archive failed';
  end if;

  select *
  into v_lifecycle
  from public.restore_media_asset(
    v_asset_id,
    4,
    'Restore verifier asset',
    gen_random_uuid()
  );

  if v_lifecycle.lifecycle_state <> 'active'
     or v_lifecycle.authority_revision <> 5
  then
    raise exception 'STOP: Asset restore failed';
  end if;

  v_blocked := false;
  begin
    update media.file_objects
    set delivery_url =
      'https://media.invalid/phase4a/m3/illegal.png'
    where id = v_original_id;
  exception
    when others then
      v_blocked :=
        position('immutable' in lower(sqlerrm)) > 0;
  end;

  if not v_blocked then
    raise exception 'STOP: File-object immutability failed';
  end if;

  v_blocked := false;
  begin
    update media.asset_revisions
    set replacement_reason = 'Illegal rewrite'
    where id = v_revision_id;
  exception
    when others then
      v_blocked :=
        position('immutable' in lower(sqlerrm)) > 0;
  end;

  if not v_blocked then
    raise exception 'STOP: Revision immutability failed';
  end if;

  v_blocked := false;
  begin
    update media.variants
    set generator_name = 'illegal-rewrite'
    where id = v_variant_one_id;
  exception
    when others then
      v_blocked :=
        position('immutable' in lower(sqlerrm)) > 0;
  end;

  if not v_blocked then
    raise exception 'STOP: Variant immutability failed';
  end if;

  v_blocked := false;
  begin
    update media.events
    set reason = 'Illegal rewrite'
    where correlation_id = v_asset_corr;
  exception
    when others then
      v_blocked :=
        position('immutable' in lower(sqlerrm)) > 0;
  end;

  if not v_blocked then
    raise exception 'STOP: Event immutability failed';
  end if;

  select count(*)
  into v_event_count
  from media.events event
  where event.actor_id = v_actor
    and (
      event.asset_id = v_asset_id
      or event.file_object_id in (
        v_original_id,
        v_derived_one_id,
        v_derived_two_id
      )
    );

  if v_event_count <> 17 then
    raise exception
      'STOP: Expected 17 Media command events, found %',
      v_event_count;
  end if;

  if not exists (
    select 1
    from media.assets asset
    where asset.id = v_asset_id
      and asset.lifecycle_state = 'active'
      and asset.authority_revision = 5
      and asset.current_revision_id = v_revision_id
      and asset.current_governance_version_id =
        v_governance.governance_version_id
  ) then
    raise exception 'STOP: Final Media authority state is invalid';
  end if;
end;
$phase_4a_m3_runtime_acceptance$

create or replace function media.require_media_read_actor()
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, auth
as $function$
declare
  v_actor_id uuid;
begin
  v_actor_id := auth.uid();

  if v_actor_id is null then
    raise exception
      'Authenticated Media read actor is required';
  end if;

  if not (
    public.current_user_has_capability(
      'view_media_records'
    )
    or public.current_user_has_capability(
      'manage_media_assets'
    )
    or public.current_user_has_capability(
      'manage_media_usage'
    )
    or public.current_user_has_capability(
      'review_media_governance'
    )
    or public.current_user_is_administrator()
  ) then
    raise exception
      'Media read authority is required';
  end if;

  return v_actor_id;
end;
$function$

create or replace function media.validate_usage_target(
  p_actor_id uuid,
  p_target_authority text,
  p_target_kind text,
  p_target_id uuid,
  p_target_version_kind text default null,
  p_target_version_id uuid default null,
  p_require_edit_authority boolean default true,
  p_require_attachable_target boolean default true
)
returns void
language plpgsql
security definer
set search_path = pg_catalog, public, editorial, auth
as $function$
declare
  v_exists boolean := false;
  v_authorized boolean := false;
  v_version_kind text;
  v_target_snapshot jsonb;
begin
  if p_actor_id is null then
    raise exception
      'Media target validation requires an actor';
  end if;

  if p_target_id is null then
    raise exception
      'Media usage target identity is required';
  end if;

  if not (
    (p_target_authority = 'editorial'
      and p_target_kind = 'article')
    or
    (p_target_authority = 'registry'
      and p_target_kind in (
        'artist',
        'author',
        'release',
        'track',
        'highlight'
      ))
    or
    (p_target_authority = 'charts'
      and p_target_kind = 'chart_entry')
    or
    (p_target_authority = 'guides'
      and p_target_kind in (
        'guide',
        'guide_page'
      ))
    or
    (p_target_authority = 'sources'
      and p_target_kind = 'source')
  ) then
    raise exception
      'Unsupported Media usage target authority and kind';
  end if;

  case
    when p_target_authority = 'editorial'
     and p_target_kind = 'article'
    then
      select to_jsonb(article_row)
      into v_target_snapshot
      from public.wk_articles article_row
      where article_row.id = p_target_id;

    when p_target_authority = 'registry'
     and p_target_kind = 'artist'
    then
      select to_jsonb(artist_row)
      into v_target_snapshot
      from public.registry_artists artist_row
      where artist_row.id = p_target_id;

    when p_target_authority = 'registry'
     and p_target_kind = 'author'
    then
      select to_jsonb(author_row)
      into v_target_snapshot
      from public.registry_authors author_row
      where author_row.id = p_target_id;

    when p_target_authority = 'registry'
     and p_target_kind = 'release'
    then
      select to_jsonb(release_row)
      into v_target_snapshot
      from public.registry_releases release_row
      where release_row.id = p_target_id;

    when p_target_authority = 'registry'
     and p_target_kind = 'track'
    then
      select to_jsonb(track_row)
      into v_target_snapshot
      from public.registry_tracks track_row
      where track_row.id = p_target_id;

    when p_target_authority = 'registry'
     and p_target_kind = 'highlight'
    then
      select to_jsonb(highlight_row)
      into v_target_snapshot
      from public.registry_artist_highlights highlight_row
      where highlight_row.id = p_target_id;

    when p_target_authority = 'charts'
     and p_target_kind = 'chart_entry'
    then
      select to_jsonb(entry_row)
      into v_target_snapshot
      from public.chart_entries entry_row
      where entry_row.id = p_target_id;

    when p_target_authority = 'guides'
     and p_target_kind = 'guide'
    then
      select to_jsonb(guide_row)
      into v_target_snapshot
      from public.guides guide_row
      where guide_row.id = p_target_id;

    when p_target_authority = 'guides'
     and p_target_kind = 'guide_page'
    then
      select to_jsonb(page_row)
      into v_target_snapshot
      from public.guide_pages page_row
      where page_row.id = p_target_id;

    when p_target_authority = 'sources'
     and p_target_kind = 'source'
    then
      select to_jsonb(source_row)
      into v_target_snapshot
      from editorial.sources source_row
      where source_row.id = p_target_id;
  end case;

  v_exists := v_target_snapshot is not null;

  if not v_exists then
    raise exception
      'Media usage target does not exist';
  end if;

  if p_require_attachable_target
     and not media.usage_target_snapshot_is_attachable(
       v_target_snapshot
     )
  then
    raise exception
      'Media usage target is archived or unresolved';
  end if;

  if (
    p_target_version_kind is null
    and p_target_version_id is not null
  )
     or (
       p_target_version_kind is not null
       and p_target_version_id is null
     )
  then
    raise exception
      'Media target-version kind and identity must be supplied together';
  end if;

  if p_target_version_id is not null then
    if p_target_authority = 'editorial'
       and p_target_kind = 'article'
    then
      select version_row.version_kind
      into v_version_kind
      from editorial.article_versions version_row
      where version_row.id = p_target_version_id
        and version_row.article_id = p_target_id;

      if not found
         or v_version_kind is distinct from
           p_target_version_kind
      then
        raise exception
          'Media Article target version is invalid';
      end if;

    elsif p_target_authority = 'sources'
          and p_target_kind = 'source'
    then
      if p_target_version_kind <> 'source_version'
         or not exists (
           select 1
           from editorial.source_versions version_row
           where version_row.id = p_target_version_id
             and version_row.source_id = p_target_id
         )
      then
        raise exception
          'Media Source target version is invalid';
      end if;

    else
      raise exception
        'This Media usage target does not support version identity';
    end if;
  end if;

  if not p_require_edit_authority then
    return;
  end if;

  if public.current_user_is_administrator() then
    return;
  end if;

  case p_target_authority
    when 'editorial' then
      v_authorized :=
        public.current_user_has_capability(
          'edit_others_articles'
        )
        or public.current_user_has_capability(
          'publish_articles'
        )
        or (
          public.current_user_has_capability(
            'edit_own_articles'
          )
          and exists (
            select 1
            from editorial.article_resources binding
            join editorial.resources resource_row
              on resource_row.id = binding.resource_id
            where binding.article_id = p_target_id
              and resource_row.owner_id = p_actor_id
          )
        );

    when 'registry' then
      v_authorized :=
        public.current_user_has_capability(
          'manage_registry'
        );

    when 'charts' then
      v_authorized :=
        public.current_user_has_capability(
          'manage_charts'
        );

    when 'guides' then
      v_authorized :=
        public.current_user_has_capability(
          'edit_guides'
        );

    when 'sources' then
      v_authorized :=
        public.current_user_has_capability(
          'manage_sources'
        );
  end case;

  if not coalesce(v_authorized, false) then
    raise exception
      'Edit authority for the Media usage target is required';
  end if;
end;
$function$

create or replace function public.resolve_media_asset_delivery(
  p_asset_id uuid,
  p_usage_link_id uuid default null,
  p_exact_asset_revision_id uuid default null,
  p_requested_variant_role text default null
)
returns table (
  logical_asset_id uuid,
  resolved_mode text,
  resolved_asset_revision_id uuid,
  resolved_file_object_id uuid,
  safe_delivery_url text,
  resolved_mime_type text,
  width integer,
  height integer,
  duration_seconds numeric,
  approved_alt_text text,
  approved_caption text,
  approved_credit text
)
language plpgsql
security definer
set search_path = pg_catalog, public, media
as $function$
declare
  v_usage media.usage_links%rowtype;
  v_asset_lifecycle text;
  v_current_revision_id uuid;
  v_rights_status text;
  v_consent_status text;
  v_embargo_state text;
  v_embargo_until timestamptz;
  v_source_protection_class text;
  v_retention_state text;
  v_public_safety_state text;
  v_resolution_mode text;
  v_revision_id uuid;
  v_file_object_id uuid;
  v_delivery_url text;
  v_mime_type text;
  v_technical_metadata jsonb;
  v_legacy_snapshot jsonb;
  v_alt_text text;
  v_caption text;
  v_credit text;
  v_width integer;
  v_height integer;
  v_duration numeric;
begin
  if p_asset_id is null then
    raise exception
      'Media resolver requires a logical asset identity';
  end if;

  select
    asset_row.lifecycle_state,
    asset_row.current_revision_id,
    governance_row.rights_status,
    governance_row.consent_status,
    governance_row.embargo_state,
    governance_row.embargo_until,
    governance_row.source_protection_class,
    governance_row.retention_state,
    governance_row.public_safety_state
  into
    v_asset_lifecycle,
    v_current_revision_id,
    v_rights_status,
    v_consent_status,
    v_embargo_state,
    v_embargo_until,
    v_source_protection_class,
    v_retention_state,
    v_public_safety_state
  from media.assets asset_row
  join media.asset_governance_versions governance_row
    on governance_row.id =
      asset_row.current_governance_version_id
  where asset_row.id = p_asset_id;

  if not found then
    raise exception
      'Media resolver asset does not exist or lacks current governance';
  end if;

  if v_asset_lifecycle <> 'active'
     or v_public_safety_state not in (
       'approved_public',
       'approved_redacted'
     )
     or v_rights_status not in (
       'owned',
       'licensed',
       'public_domain',
       'fair_use'
     )
     or v_consent_status not in (
       'granted',
       'not_required'
     )
     or v_source_protection_class not in (
       'public',
       'public_redacted'
     )
     or v_retention_state not in (
       'retain',
       'review_required'
     )
     or v_embargo_state = 'active'
     or (
       v_embargo_state = 'scheduled'
       and v_embargo_until is not null
       and v_embargo_until > now()
     )
  then
    raise exception
      'Media delivery is blocked by current governance';
  end if;

  if p_usage_link_id is not null then
    select usage_row.*
    into v_usage
    from media.usage_links usage_row
    where usage_row.id = p_usage_link_id;

    if not found
       or v_usage.usage_state <> 'active'
    then
      raise exception
        'Active Media usage does not exist';
    end if;

    if v_usage.asset_id <> p_asset_id then
      raise exception
        'Media usage does not belong to the supplied asset';
    end if;

    if p_exact_asset_revision_id is not null
       and p_exact_asset_revision_id is distinct from
         v_usage.asset_revision_id
    then
      raise exception
        'Supplied Media revision does not match the usage';
    end if;

    v_resolution_mode := v_usage.resolution_mode;
    v_revision_id := v_usage.asset_revision_id;
    v_alt_text := v_usage.alt_text_snapshot;
    v_caption := v_usage.caption_snapshot;
    v_credit := v_usage.credit_snapshot;

    if v_resolution_mode = 'current_revision'
       and media.usage_role_requires_stability(
         v_usage.usage_role
       )
    then
      raise exception
        'Publication-stable Media usage cannot resolve through current revision';
    end if;

  elsif p_exact_asset_revision_id is not null then
    v_resolution_mode := 'exact_revision';
    v_revision_id := p_exact_asset_revision_id;

  else
    v_resolution_mode := 'current_revision';
    v_revision_id := v_current_revision_id;
  end if;

  if v_resolution_mode = 'legacy_snapshot' then
    if p_usage_link_id is null then
      raise exception
        'Legacy-snapshot delivery requires a usage link';
    end if;

    if p_requested_variant_role is not null then
      raise exception
        'Legacy-snapshot delivery cannot resolve a variant';
    end if;

    if v_revision_id is not null then
      raise exception
        'Legacy-snapshot usage cannot bind a revision';
    end if;

    select bridge_row.legacy_snapshot
    into v_legacy_snapshot
    from media.legacy_asset_links bridge_row
    where bridge_row.asset_id = p_asset_id;

    if not found
       or nullif(
         btrim(v_legacy_snapshot ->> 'url'),
         ''
       ) is null
    then
      raise exception
        'Legacy-snapshot delivery requires one immutable captured URL';
    end if;

    v_delivery_url :=
      btrim(v_legacy_snapshot ->> 'url');
    v_mime_type :=
      nullif(
        btrim(v_legacy_snapshot ->> 'mime_type'),
        ''
      );

    v_width :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,width}',
          ''
        ) ~ '^[0-9]+$'
          then (
            v_legacy_snapshot #>>
              '{metadata,width}'
          )::integer
        else null
      end;

    v_height :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,height}',
          ''
        ) ~ '^[0-9]+$'
          then (
            v_legacy_snapshot #>>
              '{metadata,height}'
          )::integer
        else null
      end;

    v_duration :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,duration}',
          ''
        ) ~ '^[0-9]+([.][0-9]+)?$'
          then (
            v_legacy_snapshot #>>
              '{metadata,duration}'
          )::numeric
        else null
      end;

    return query
    select
      p_asset_id,
      v_resolution_mode,
      null::uuid,
      null::uuid,
      v_delivery_url,
      v_mime_type,
      v_width,
      v_height,
      v_duration,
      v_alt_text,
      v_caption,
      v_credit;

    return;
  end if;

  if v_revision_id is null then
    raise exception
      'Media delivery has no valid asset revision';
  end if;

  if not exists (
    select 1
    from media.asset_revisions revision_row
    where revision_row.id = v_revision_id
      and revision_row.asset_id = p_asset_id
  ) then
    raise exception
      'Media delivery revision does not belong to the asset';
  end if;

  if p_requested_variant_role is null then
    select revision_row.original_file_object_id
    into v_file_object_id
    from media.asset_revisions revision_row
    where revision_row.id = v_revision_id;
  else
    select variant_row.derived_file_object_id
    into v_file_object_id
    from media.variant_selections selection_row
    join media.variants variant_row
      on variant_row.id = selection_row.variant_id
    where selection_row.asset_revision_id =
      v_revision_id
      and selection_row.variant_role =
        p_requested_variant_role
      and variant_row.asset_revision_id =
        v_revision_id
      and variant_row.variant_role =
        p_requested_variant_role;

    if not found then
      raise exception
        'Requested Media variant has no governed selection';
    end if;
  end if;

  select
    file_row.delivery_url,
    file_row.mime_type,
    file_row.technical_metadata
  into
    v_delivery_url,
    v_mime_type,
    v_technical_metadata
  from media.file_objects file_row
  where file_row.id = v_file_object_id
    and file_row.verification_state = 'verified';

  if not found
     or nullif(btrim(v_delivery_url), '') is null
  then
    raise exception
      'Media delivery requires one verified file object with a safe URL';
  end if;

  v_width :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'width'
      ) = 'number'
        then (
          v_technical_metadata ->> 'width'
        )::numeric::integer
      else null
    end;

  v_height :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'height'
      ) = 'number'
        then (
          v_technical_metadata ->> 'height'
        )::numeric::integer
      else null
    end;

  v_duration :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'duration'
      ) = 'number'
        then (
          v_technical_metadata ->> 'duration'
        )::numeric
      else null
    end;

  return query
  select
    p_asset_id,
    v_resolution_mode,
    v_revision_id,
    v_file_object_id,
    v_delivery_url,
    v_mime_type,
    v_width,
    v_height,
    v_duration,
    v_alt_text,
    v_caption,
    v_credit;
end;
$function$

do $phase_4a_m4_source_usage_gate$
declare
  v_count bigint;
  v_source_usage record;
begin
  select count(*)
  into v_count
  from phase_4a_m4_source_usage;

  if v_count <> 987 then
    raise exception
      'STOP: Expected 987 real Media placements, found %',
      v_count;
  end if;

  if (
    select count(*)
    from phase_4a_m4_source_usage source_usage
    where source_usage.target_is_attachable
  ) <> 985
     or (
       select count(*)
       from phase_4a_m4_source_usage source_usage
       where not source_usage.target_is_attachable
     ) <> 2
  then
    raise exception
      'STOP: Expected 985 attachable and 2 archived-target Media placements';
  end if;

  if exists (
    select 1
    from phase_4a_m4_source_usage source_usage
    where not source_usage.target_is_attachable
      and (
        source_usage.source_table <> 'registry_artists'
        or source_usage.source_column <> 'public_image_id'
        or source_usage.target_authority <> 'registry'
        or source_usage.target_kind <> 'artist'
        or source_usage.usage_role <> 'artist_portrait'
        or (
          source_usage.target_id,
          source_usage.asset_id
        ) not in (
          (
            'd3c7ebee-4354-4df5-b3ee-91998719b7b4'::uuid,
            '7bff42c9-fe93-4568-a4cd-b683fae97418'::uuid
          ),
          (
            'dbc82131-40f6-4e45-8ae5-d08d7b86a0bc'::uuid,
            '8f37b111-60c4-4578-8274-5d73e0a337ca'::uuid
          )
        )
      )
  ) then
    raise exception
      'STOP: Archived-target Media placement identity changed after diagnosis';
  end if;

  if exists (
    select 1
    from phase_4a_m4_source_usage source_usage
    left join media.assets asset_row
      on asset_row.id = source_usage.asset_id
    left join media.legacy_asset_links bridge_row
      on bridge_row.asset_id = source_usage.asset_id
    where asset_row.id is null
       or bridge_row.asset_id is null
       or nullif(
         btrim(bridge_row.legacy_snapshot ->> 'url'),
         ''
       ) is null
  ) then
    raise exception
      'STOP: One or more real Media placements lack an immutable legacy URL snapshot';
  end if;

  if exists (
    select 1
    from phase_4a_m4_source_usage source_usage
    group by
      source_usage.source_schema,
      source_usage.source_table,
      source_usage.source_column,
      source_usage.target_id
    having count(*) <> 1
  ) then
    raise exception
      'STOP: Real Media placement identity is not unique';
  end if;

  for v_source_usage in
    select source_row.*
    from phase_4a_m4_source_usage source_row
    order by
      source_row.source_schema,
      source_row.source_table,
      source_row.target_id
  loop
    perform media.validate_usage_target(
      '00000000-0000-4000-8000-000000000001'::uuid,
      v_source_usage.target_authority,
      v_source_usage.target_kind,
      v_source_usage.target_id,
      null,
      null,
      false,
      v_source_usage.target_is_attachable
    );

    if not media.usage_role_matches_target(
         v_source_usage.usage_role,
         v_source_usage.target_authority,
         v_source_usage.target_kind
       )
    then
      raise exception
        'STOP: Real Media placement role does not match its typed target';
    end if;
  end loop;
end;
$phase_4a_m4_source_usage_gate$

do $phase_4a_m4_contract_acceptance$
declare
  v_definition text;
  v_attach_definition text;
  v_target_definition text;
begin
  select pg_get_functiondef(
    'public.resolve_media_asset_delivery(uuid,uuid,uuid,text)'::regprocedure
  )
  into v_definition;

  select pg_get_functiondef(
    'public.attach_media_usage(uuid,text,text,text,uuid,text,uuid,text,uuid,jsonb,integer,text,text,text,uuid)'::regprocedure
  )
  into v_attach_definition;

  select pg_get_functiondef(
    'media.validate_usage_target(uuid,text,text,uuid,text,uuid,boolean,boolean)'::regprocedure
  )
  into v_target_definition;

  if position(
       'media.legacy_asset_links'
       in v_definition
     ) = 0
     or position(
       'media.variant_selections'
       in v_definition
     ) = 0
     or position(
       'public.registry_media_assets'
       in v_definition
     ) > 0
  then
    raise exception
      'STOP: Public Media resolver violates the accepted authority boundary';
  end if;

  if position(
       'media.usage_role_matches_target'
       in v_attach_definition
     ) = 0
     or position(
       'Media usage role does not match the target authority and kind'
       in v_attach_definition
     ) = 0
     or position(
       'media.usage_target_snapshot_is_attachable'
       in v_target_definition
     ) = 0
     or position(
       'Media usage target is archived or unresolved'
       in v_target_definition
     ) = 0
     or position(
       'public.wk_chart_entries_v2'
       in v_target_definition
     ) > 0
  then
    raise exception
      'STOP: Typed target-role or target-lifecycle authority is missing';
  end if;

  if not has_function_privilege(
       'anon',
       'public.resolve_media_asset_delivery(uuid,uuid,uuid,text)',
       'EXECUTE'
     )
     or has_function_privilege(
       'anon',
       'public.attach_media_usage(uuid,text,text,text,uuid,text,uuid,text,uuid,jsonb,integer,text,text,text,uuid)',
       'EXECUTE'
     )
     or has_function_privilege(
       'anon',
       'public.detach_media_usage(uuid,bigint,text,uuid)',
       'EXECUTE'
     )
     or has_function_privilege(
       'anon',
       'public.archive_media_usage(uuid,bigint,text,uuid)',
       'EXECUTE'
     )
  then
    raise exception
      'STOP: Migration 4 function grants are incorrect';
  end if;
end;
$phase_4a_m4_contract_acceptance$

do $phase_4a_m4_actor_collision$
begin
  if exists (
    select 1
    from auth.users
    where id =
      'f4a40000-0000-4000-8000-000000000001'::uuid
  ) then
    raise exception
      'STOP: Reserved Phase 4A M4 verifier actor exists';
  end if;
end;
$phase_4a_m4_actor_collision$

do $phase_4a_m4_runtime_acceptance$
declare
  v_actor constant uuid :=
    'f4a40000-0000-4000-8000-000000000001';
  v_target_id uuid;
  v_asset record;
  v_original record;
  v_revision record;
  v_governance record;
  v_derived record;
  v_variant record;
  v_selection record;
  v_usage_one record;
  v_usage_two record;
  v_lifecycle record;
  v_delivery record;
  v_asset_id uuid;
  v_original_id uuid;
  v_revision_id uuid;
  v_derived_id uuid;
  v_variant_id uuid;
  v_rejected boolean;
  v_event_count bigint;
  v_detail jsonb;
begin
  perform set_config(
    'request.jwt.claim.role',
    'authenticated',
    true
  );
  perform set_config(
    'request.jwt.claim.sub',
    v_actor::text,
    true
  );
  perform set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'role',
      'authenticated',
      'sub',
      v_actor
    )::text,
    true
  );

  if auth.uid() is distinct from v_actor
     or not public.current_user_is_administrator()
  then
    raise exception
      'STOP: M4 verifier actor context failed';
  end if;

  select article_row.id
  into v_target_id
  from public.wk_articles article_row
  order by article_row.id
  limit 1;

  if v_target_id is null then
    raise exception
      'STOP: M4 verifier requires one Article target';
  end if;

  select *
  into v_asset
  from public.create_media_asset(
    'image',
    'article_inline',
    'Phase 4A M4 verifier asset',
    null,
    'f4a40000-0000-4000-8000-000000000101'
  );

  v_asset_id := v_asset.asset_id;

  select *
  into v_original
  from public.register_media_file_object(
    'lightsail_media',
    'phase4a-m4-verifier',
    'phase4a/m4/verifier/original.png',
    'https://media.invalid/phase4a/m4/original.png',
    'original.png',
    'image/png',
    3,
    '{"width":10,"height":20}'::jsonb,
    'f4a40000-0000-4000-8000-000000000102'
  );

  v_original_id := v_original.file_object_id;

  perform 1
  from public.verify_media_file_object(
    v_original_id,
    'verified',
    repeat('d', 64),
    3,
    'image/png',
    '{"width":10,"height":20}'::jsonb,
    null,
    'f4a40000-0000-4000-8000-000000000103'
  );

  select *
  into v_revision
  from public.create_media_asset_revision(
    v_asset_id,
    1,
    v_original_id,
    'Create Migration 4 verifier revision',
    'f4a40000-0000-4000-8000-000000000104'
  );

  v_revision_id := v_revision.asset_revision_id;

  select *
  into v_governance
  from public.create_media_governance_version(
    v_asset_id,
    2,
    jsonb_build_object(
      'rights_status', 'owned',
      'consent_status', 'not_required',
      'sensitivity', 'none',
      'embargo_state', 'none',
      'source_protection_class', 'public',
      'preservation_state', 'working_copy',
      'retention_state', 'retain',
      'public_safety_state', 'approved_public'
    ),
    'Approve Migration 4 verifier delivery',
    'f4a40000-0000-4000-8000-000000000105'
  );

  select *
  into v_derived
  from public.register_media_file_object(
    'lightsail_media',
    'phase4a-m4-verifier',
    'phase4a/m4/verifier/thumbnail.png',
    'https://media.invalid/phase4a/m4/thumbnail.png',
    'thumbnail.png',
    'image/png',
    2,
    '{"width":5,"height":10}'::jsonb,
    'f4a40000-0000-4000-8000-000000000106'
  );

  v_derived_id := v_derived.file_object_id;

  perform 1
  from public.verify_media_file_object(
    v_derived_id,
    'verified',
    repeat('e', 64),
    2,
    'image/png',
    '{"width":5,"height":10}'::jsonb,
    null,
    'f4a40000-0000-4000-8000-000000000107'
  );

  select *
  into v_variant
  from public.register_media_variant(
    v_asset_id,
    v_revision_id,
    v_original_id,
    v_derived_id,
    'thumbnail',
    '{"operation":"resize","width":5}'::jsonb,
    '{"width":5,"height":10}'::jsonb,
    'phase4a-m4-verifier',
    '1',
    'f4a40000-0000-4000-8000-000000000108'
  );

  v_variant_id := v_variant.variant_id;

  select *
  into v_selection
  from public.activate_media_variant(
    v_revision_id,
    'thumbnail',
    v_variant_id,
    0,
    'Activate Migration 4 verifier thumbnail',
    'f4a40000-0000-4000-8000-000000000109'
  );

  if v_selection.selection_revision <> 1 then
    raise exception
      'STOP: M4 verifier variant activation failed';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.attach_media_usage(
      v_asset_id,
      'exact_revision',
      'registry',
      'artist',
      'd3c7ebee-4354-4df5-b3ee-91998719b7b4'::uuid,
      'artist_portrait',
      v_revision_id,
      null,
      null,
      '{"acceptance":"archived-target"}'::jsonb,
      0,
      null,
      null,
      null,
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'media usage target is archived or unresolved'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception
      'STOP: Archived Media usage target was accepted';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.attach_media_usage(
      v_asset_id,
      'exact_revision',
      'editorial',
      'article',
      v_target_id,
      'release_artwork',
      v_revision_id,
      null,
      null,
      '{"acceptance":"invalid-role"}'::jsonb,
      0,
      null,
      null,
      null,
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'media usage role does not match the target authority and kind'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception
      'STOP: Mismatched Media usage role was accepted';
  end if;

  if media.usage_target_snapshot_is_attachable(
       '{"status":"archived"}'::jsonb
     )
     or media.usage_target_snapshot_is_attachable(
       '{"archived_at":"2026-08-05T00:00:00Z"}'::jsonb
     )
     or not media.usage_target_snapshot_is_attachable(
       '{"status":"active"}'::jsonb
     )
  then
    raise exception
      'STOP: Media target lifecycle classification failed';
  end if;

  select *
  into v_usage_one
  from public.attach_media_usage(
    v_asset_id,
    'exact_revision',
    'editorial',
    'article',
    v_target_id,
    'article_inline',
    v_revision_id,
    null,
    null,
    '{"acceptance":"original"}'::jsonb,
    0,
    'Verifier alt text',
    'Verifier caption',
    'Verifier credit',
    'f4a40000-0000-4000-8000-000000000110'
  );

  select *
  into v_delivery
  from public.resolve_media_asset_delivery(
    v_asset_id,
    v_usage_one.usage_link_id,
    null,
    null
  );

  if v_delivery.resolved_asset_revision_id
       is distinct from v_revision_id
     or v_delivery.resolved_file_object_id
       is distinct from v_original_id
     or v_delivery.safe_delivery_url <>
       'https://media.invalid/phase4a/m4/original.png'
     or v_delivery.width <> 10
     or v_delivery.height <> 20
     or v_delivery.approved_alt_text <>
       'Verifier alt text'
  then
    raise exception
      'STOP: M4 original delivery resolution failed';
  end if;

  select *
  into v_usage_two
  from public.attach_media_usage(
    v_asset_id,
    'exact_revision',
    'editorial',
    'article',
    v_target_id,
    'article_inline',
    v_revision_id,
    null,
    null,
    '{"acceptance":"variant"}'::jsonb,
    1,
    null,
    null,
    null,
    'f4a40000-0000-4000-8000-000000000111'
  );

  select *
  into v_delivery
  from public.resolve_media_asset_delivery(
    v_asset_id,
    v_usage_two.usage_link_id,
    v_revision_id,
    'thumbnail'
  );

  if v_delivery.resolved_file_object_id
       is distinct from v_derived_id
     or v_delivery.safe_delivery_url <>
       'https://media.invalid/phase4a/m4/thumbnail.png'
     or v_delivery.width <> 5
     or v_delivery.height <> 10
  then
    raise exception
      'STOP: M4 governed variant delivery resolution failed';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.attach_media_usage(
      v_asset_id,
      'exact_revision',
      'editorial',
      'article',
      v_target_id,
      'article_inline',
      v_revision_id,
      null,
      null,
      '{"acceptance":"variant"}'::jsonb,
      1,
      null,
      null,
      null,
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'duplicate active media usage'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception
      'STOP: Duplicate active Media usage was accepted';
  end if;

  if not exists (
    select 1
    from public.list_media_assets_v2(
      'Phase 4A M4 verifier',
      null,
      null,
      null,
      10,
      0
    ) asset_list
    where asset_list.asset_id = v_asset_id
      and asset_list.active_usage_count = 2
  ) then
    raise exception
      'STOP: M4 list read model failed';
  end if;

  v_detail :=
    public.get_media_asset_v2(v_asset_id);

  if v_detail #>> '{asset,id}' <>
     v_asset_id::text
     or jsonb_array_length(
       v_detail -> 'usages'
     ) <> 2
  then
    raise exception
      'STOP: M4 detail read model failed';
  end if;

  select *
  into v_lifecycle
  from public.detach_media_usage(
    v_usage_one.usage_link_id,
    1,
    'Detach Migration 4 verifier usage',
    'f4a40000-0000-4000-8000-000000000112'
  );

  if v_lifecycle.usage_state <> 'detached'
     or v_lifecycle.usage_revision <> 2
  then
    raise exception
      'STOP: M4 usage detachment failed';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.detach_media_usage(
      v_usage_one.usage_link_id,
      1,
      'Stale Migration 4 verifier detachment',
      gen_random_uuid()
    );
  exception
    when others then
      v_rejected :=
        position(
          'stale media usage revision'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception
      'STOP: Stale Media usage revision was accepted';
  end if;

  select *
  into v_lifecycle
  from public.archive_media_usage(
    v_usage_one.usage_link_id,
    2,
    'Archive detached Migration 4 verifier usage',
    'f4a40000-0000-4000-8000-000000000113'
  );

  if v_lifecycle.usage_state <> 'archived'
     or v_lifecycle.usage_revision <> 3
  then
    raise exception
      'STOP: M4 detached usage archive failed';
  end if;

  select *
  into v_lifecycle
  from public.archive_media_usage(
    v_usage_two.usage_link_id,
    1,
    'Archive active Migration 4 verifier usage',
    'f4a40000-0000-4000-8000-000000000114'
  );

  if v_lifecycle.usage_state <> 'archived'
     or v_lifecycle.usage_revision <> 2
  then
    raise exception
      'STOP: M4 active usage archive failed';
  end if;

  v_rejected := false;
  begin
    perform 1
    from public.resolve_media_asset_delivery(
      v_asset_id,
      v_usage_one.usage_link_id,
      null,
      null
    );
  exception
    when others then
      v_rejected :=
        position(
          'active media usage does not exist'
          in lower(sqlerrm)
        ) > 0;
  end;

  if not v_rejected then
    raise exception
      'STOP: Archived Media usage still resolved publicly';
  end if;

  select count(*)
  into v_event_count
  from media.events event_row
  where event_row.asset_id = v_asset_id
    and event_row.event_type in (
      'usage_attached',
      'usage_detached',
      'usage_archived'
    );

  if v_event_count <> 5 then
    raise exception
      'STOP: M4 usage lifecycle event set is incomplete';
  end if;
end;
$phase_4a_m4_runtime_acceptance$

do $phase_4a_m4_post_runtime_acceptance$
begin
  if (select count(*) from media.usage_links) <> 987 then
    raise exception
      'STOP: Transactional M4 acceptance rows persisted';
  end if;

  if (select count(*) from media.events) <> 3147 then
    raise exception
      'STOP: Transactional M4 acceptance events persisted';
  end if;

  if (
    (select count(*) from media.file_objects)
    + (select count(*) from media.asset_revisions)
    + (select count(*) from media.variants)
    + (select count(*) from media.variant_selections)
  ) <> 0 then
    raise exception
      'STOP: Transactional M4 file or revision rows persisted';
  end if;
end;
$phase_4a_m4_post_runtime_acceptance$

create or replace function public.resolve_media_asset_delivery(
  p_asset_id uuid,
  p_usage_link_id uuid default null,
  p_exact_asset_revision_id uuid default null,
  p_requested_variant_role text default null
)
returns table (
  logical_asset_id uuid,
  resolved_mode text,
  resolved_asset_revision_id uuid,
  resolved_file_object_id uuid,
  safe_delivery_url text,
  resolved_mime_type text,
  width integer,
  height integer,
  duration_seconds numeric,
  approved_alt_text text,
  approved_caption text,
  approved_credit text
)
language plpgsql
security definer
set search_path = pg_catalog, public, media
as $function$
declare
  v_usage media.usage_links%rowtype;
  v_asset_lifecycle text;
  v_current_revision_id uuid;
  v_governance_version_number bigint;
  v_rights_status text;
  v_consent_status text;
  v_sensitivity text;
  v_embargo_state text;
  v_embargo_until timestamptz;
  v_source_protection_class text;
  v_preservation_state text;
  v_retention_state text;
  v_public_safety_state text;
  v_internal_reason text;
  v_resolution_mode text;
  v_revision_id uuid;
  v_file_object_id uuid;
  v_delivery_url text;
  v_mime_type text;
  v_technical_metadata jsonb;
  v_legacy_snapshot jsonb;
  v_compatibility_status text;
  v_compatibility_url text;
  v_alt_text text;
  v_caption text;
  v_credit text;
  v_width integer;
  v_height integer;
  v_duration numeric;
  v_is_approved_public boolean;
  v_is_legacy_compatibility boolean;
begin
  if p_asset_id is null then
    raise exception
      'Media resolver requires a logical asset identity';
  end if;

  select
    asset_row.lifecycle_state,
    asset_row.current_revision_id,
    governance_row.version_number,
    governance_row.rights_status,
    governance_row.consent_status,
    governance_row.sensitivity,
    governance_row.embargo_state,
    governance_row.embargo_until,
    governance_row.source_protection_class,
    governance_row.preservation_state,
    governance_row.retention_state,
    governance_row.public_safety_state,
    governance_row.internal_reason
  into
    v_asset_lifecycle,
    v_current_revision_id,
    v_governance_version_number,
    v_rights_status,
    v_consent_status,
    v_sensitivity,
    v_embargo_state,
    v_embargo_until,
    v_source_protection_class,
    v_preservation_state,
    v_retention_state,
    v_public_safety_state,
    v_internal_reason
  from media.assets asset_row
  join media.asset_governance_versions governance_row
    on governance_row.id =
      asset_row.current_governance_version_id
  where asset_row.id = p_asset_id;

  if not found then
    raise exception
      'Media resolver asset does not exist or lacks current governance';
  end if;

  if p_usage_link_id is not null then
    select usage_row.*
    into v_usage
    from media.usage_links usage_row
    where usage_row.id = p_usage_link_id;

    if not found
       or v_usage.usage_state <> 'active'
    then
      raise exception
        'Active Media usage does not exist';
    end if;

    if v_usage.asset_id <> p_asset_id then
      raise exception
        'Media usage does not belong to the supplied asset';
    end if;

    if p_exact_asset_revision_id is not null
       and p_exact_asset_revision_id is distinct from
         v_usage.asset_revision_id
    then
      raise exception
        'Supplied Media revision does not match the usage';
    end if;

    v_resolution_mode := v_usage.resolution_mode;
    v_revision_id := v_usage.asset_revision_id;
    v_alt_text := v_usage.alt_text_snapshot;
    v_caption := v_usage.caption_snapshot;
    v_credit := v_usage.credit_snapshot;

    if v_resolution_mode = 'current_revision'
       and media.usage_role_requires_stability(
         v_usage.usage_role
       )
    then
      raise exception
        'Publication-stable Media usage cannot resolve through current revision';
    end if;

  elsif p_exact_asset_revision_id is not null then
    v_resolution_mode := 'exact_revision';
    v_revision_id := p_exact_asset_revision_id;

  else
    v_resolution_mode := 'current_revision';
    v_revision_id := v_current_revision_id;
  end if;

  v_is_approved_public := coalesce(
    v_asset_lifecycle = 'active'
    and v_public_safety_state in (
      'approved_public',
      'approved_redacted'
    )
    and v_rights_status in (
      'owned',
      'licensed',
      'public_domain',
      'fair_use'
    )
    and v_consent_status in (
      'granted',
      'not_required'
    )
    and v_source_protection_class in (
      'public',
      'public_redacted'
    )
    and v_retention_state in (
      'retain',
      'review_required'
    )
    and v_embargo_state <> 'active'
    and not (
      v_embargo_state = 'scheduled'
      and v_embargo_until is not null
      and v_embargo_until > now()
    ),
    false
  );

  v_is_legacy_compatibility := coalesce(
    v_asset_lifecycle = 'active'
    and v_governance_version_number = 1
    and v_rights_status = 'unknown'
    and v_consent_status = 'unknown'
    and v_sensitivity = 'none'
    and v_embargo_state = 'none'
    and v_embargo_until is null
    and v_source_protection_class = 'internal'
    and v_preservation_state = 'unassessed'
    and v_retention_state = 'retain'
    and v_public_safety_state = 'internal'
    and v_internal_reason =
      'Initial governance copied without inference from registry_media_assets',
    false
  );

  if v_resolution_mode = 'legacy_snapshot' then
    if p_usage_link_id is null then
      raise exception
        'Legacy-snapshot delivery requires a usage link';
    end if;

    if p_requested_variant_role is not null then
      raise exception
        'Legacy-snapshot delivery cannot resolve a variant';
    end if;

    if v_revision_id is not null then
      raise exception
        'Legacy-snapshot usage cannot bind a revision';
    end if;

    select
      bridge_row.legacy_snapshot,
      compatibility_row.status,
      compatibility_row.url
    into
      v_legacy_snapshot,
      v_compatibility_status,
      v_compatibility_url
    from media.legacy_asset_links bridge_row
    join public.registry_media_assets compatibility_row
      on compatibility_row.id =
        bridge_row.legacy_asset_id
    where bridge_row.asset_id = p_asset_id
      and bridge_row.legacy_asset_id =
        p_asset_id;

    if not found
       or nullif(
         btrim(v_legacy_snapshot ->> 'url'),
         ''
       ) is null
    then
      raise exception
        'Legacy-snapshot delivery requires one immutable captured URL';
    end if;

    if v_compatibility_status <> 'active' then
      raise exception
        'Legacy Media compatibility row is not active';
    end if;

    if btrim(v_compatibility_url) is distinct from
       btrim(v_legacy_snapshot ->> 'url')
    then
      raise exception
        'Legacy Media compatibility URL changed after capture';
    end if;

    if not (
      v_is_approved_public
      or v_is_legacy_compatibility
    ) then
      raise exception
        'Media delivery is blocked by current governance';
    end if;

    v_delivery_url :=
      btrim(v_legacy_snapshot ->> 'url');
    v_mime_type :=
      nullif(
        btrim(v_legacy_snapshot ->> 'mime_type'),
        ''
      );

    v_width :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,width}',
          ''
        ) ~ '^[0-9]+$'
          then (
            v_legacy_snapshot #>>
              '{metadata,width}'
          )::integer
        else null
      end;

    v_height :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,height}',
          ''
        ) ~ '^[0-9]+$'
          then (
            v_legacy_snapshot #>>
              '{metadata,height}'
          )::integer
        else null
      end;

    v_duration :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,duration}',
          ''
        ) ~ '^[0-9]+([.][0-9]+)?$'
          then (
            v_legacy_snapshot #>>
              '{metadata,duration}'
          )::numeric
        else null
      end;

    return query
    select
      p_asset_id,
      v_resolution_mode,
      null::uuid,
      null::uuid,
      v_delivery_url,
      v_mime_type,
      v_width,
      v_height,
      v_duration,
      v_alt_text,
      v_caption,
      v_credit;

    return;
  end if;

  if not v_is_approved_public then
    raise exception
      'Media delivery is blocked by current governance';
  end if;

  if v_revision_id is null then
    raise exception
      'Media delivery has no valid asset revision';
  end if;

  if not exists (
    select 1
    from media.asset_revisions revision_row
    where revision_row.id = v_revision_id
      and revision_row.asset_id = p_asset_id
  ) then
    raise exception
      'Media delivery revision does not belong to the asset';
  end if;

  if p_requested_variant_role is null then
    select revision_row.original_file_object_id
    into v_file_object_id
    from media.asset_revisions revision_row
    where revision_row.id = v_revision_id;
  else
    select variant_row.derived_file_object_id
    into v_file_object_id
    from media.variant_selections selection_row
    join media.variants variant_row
      on variant_row.id = selection_row.variant_id
    where selection_row.asset_revision_id =
      v_revision_id
      and selection_row.variant_role =
        p_requested_variant_role
      and variant_row.asset_revision_id =
        v_revision_id
      and variant_row.variant_role =
        p_requested_variant_role;

    if not found then
      raise exception
        'Requested Media variant has no governed selection';
    end if;
  end if;

  select
    file_row.delivery_url,
    file_row.mime_type,
    file_row.technical_metadata
  into
    v_delivery_url,
    v_mime_type,
    v_technical_metadata
  from media.file_objects file_row
  where file_row.id = v_file_object_id
    and file_row.verification_state = 'verified';

  if not found
     or nullif(btrim(v_delivery_url), '') is null
  then
    raise exception
      'Media delivery requires one verified file object with a safe URL';
  end if;

  v_width :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'width'
      ) = 'number'
        then (
          v_technical_metadata ->> 'width'
        )::numeric::integer
      else null
    end;

  v_height :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'height'
      ) = 'number'
        then (
          v_technical_metadata ->> 'height'
        )::numeric::integer
      else null
    end;

  v_duration :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'duration'
      ) = 'number'
        then (
          v_technical_metadata ->> 'duration'
        )::numeric
      else null
    end;

  return query
  select
    p_asset_id,
    v_resolution_mode,
    v_revision_id,
    v_file_object_id,
    v_delivery_url,
    v_mime_type,
    v_width,
    v_height,
    v_duration,
    v_alt_text,
    v_caption,
    v_credit;
end;
$function$

do $phase_4a_m5a_assertions$
declare
  v_count bigint;
  v_fingerprint text;
  v_definition text;
begin
  select pg_get_functiondef(
    'public.resolve_media_asset_delivery(uuid,uuid,uuid,text)'::regprocedure
  )
  into v_definition;

  if position(
    'Legacy Media compatibility URL changed after capture'
    in v_definition
  ) = 0
     or position(
       'Initial governance copied without inference from registry_media_assets'
       in v_definition
     ) = 0
  then
    raise exception
      'STOP: Legacy compatibility resolver contract is incomplete';
  end if;

  if not has_function_privilege(
    'anon',
    'public.resolve_media_asset_delivery(uuid,uuid,uuid,text)',
    'EXECUTE'
  )
     or not has_function_privilege(
       'authenticated',
       'public.resolve_media_asset_delivery(uuid,uuid,uuid,text)',
       'EXECUTE'
     )
     or not has_function_privilege(
       'service_role',
       'public.resolve_media_asset_delivery(uuid,uuid,uuid,text)',
       'EXECUTE'
     )
  then
    raise exception
      'STOP: Resolver grants are incomplete';
  end if;

  if (
    select count(*)
    from media.assets
  ) <> 1079
     or (
       select count(*)
       from media.legacy_asset_links
     ) <> 1079
     or (
       select count(*)
       from media.usage_links
     ) <> 987
     or (
       select count(*)
       from media.events
     ) <> 3147
     or (
       select count(*)
       from media.file_objects
     ) <> 0
     or (
       select count(*)
       from media.asset_revisions
     ) <> 0
     or (
       select count(*)
       from media.variants
     ) <> 0
     or (
       select count(*)
       from media.variant_selections
     ) <> 0
  then
    raise exception
      'STOP: Migration 5A changed canonical Media rows';
  end if;

  select count(*)
  into v_count
  from public.registry_media_assets;

  if v_count <> 1079 then
    raise exception
      'STOP: Compatibility row count changed: %',
      v_count;
  end if;

  select md5(
    string_agg(
      to_jsonb(asset_row)::text,
      E'\n'
      order by asset_row.id::text
    )
  )
  into v_fingerprint
  from public.registry_media_assets asset_row;

  if v_fingerprint <>
     'f32e074f96b01549b5e597ad8b5f4324'
  then
    raise exception
      'STOP: Compatibility asset fingerprint changed: %',
      v_fingerprint;
  end if;
end;
