      where target_resource_id = 'a0ba2456-07bb-4d20-8031-87dc8a998179'::uuid)
    + (select count(*) from editorial.correction_applications
      where target_resource_id = 'a0ba2456-07bb-4d20-8031-87dc8a998179'::uuid)
    + (select count(*) from editorial.correction_public_notes
      where affected_resource_id = 'a0ba2456-07bb-4d20-8031-87dc8a998179'::uuid)
    + (select count(*) from editorial.correction_related_resource_reviews
      where related_resource_id = 'a0ba2456-07bb-4d20-8031-87dc8a998179'::uuid)
    + (select count(*) from editorial.media_asset_resources
      where resource_id = 'a0ba2456-07bb-4d20-8031-87dc8a998179'::uuid)
  into fake_resource_dependency_count;

  if fake_resource_dependency_count <> 0 then
    raise exception
      'STOP: Fake Playlist Resource acquired % dependent record(s)',
      fake_resource_dependency_count;
  end if;

  select count(*)
  into fake_review_packet_count
  from public.institute_review_packets
  where snapshot_json #>> '{workProduct,productId}' in (
      '4a422c74-1257-4dc6-b58e-516491ace629',
      '8df68493-70dd-417f-bd04-69c74d7ff1e8'
    )
     or snapshot_json #>> '{workProduct,productSlug}' in (
      'between-2018-and-2024-in-what-ways-did-sheng-function-inside-kenyan-gengeton',
      'between-2018-and-2024-in-what-ways-did-sheng-function-inside-kenyan-gengeton-2'
    );

  if fake_review_packet_count <> 0 then
    raise exception
      'STOP: Found % Institute review packet(s) tied to fake Playlist data',
      fake_review_packet_count;
  end if;
end;
$phase_5a_m208_preflight$

create or replace function media.validate_usage_target(
  p_actor_id uuid,
  p_target_authority text,
  p_target_kind text,
  p_target_id uuid,
  p_target_version_kind text default null,
  p_target_version_id uuid default null,
  p_require_edit_authority boolean default true,
  p_require_attachable_target boolean default true
)
returns void
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'editorial', 'auth'
as $function$
declare
  v_exists boolean := false;
  v_authorized boolean := false;
  v_version_kind text;
  v_target_snapshot jsonb;
begin
  if p_actor_id is null then
    raise exception 'Media target validation requires an actor';
  end if;

  if p_target_id is null then
    raise exception 'Media usage target identity is required';
  end if;

  if not (
    (
      p_target_authority = 'editorial'
      and p_target_kind in ('article', 'playlist')
    )
    or (
      p_target_authority = 'registry'
      and p_target_kind in (
        'artist',
        'author',
        'release',
        'track',
        'highlight'
      )
    )
    or (
      p_target_authority = 'charts'
      and p_target_kind = 'chart_entry'
    )
    or (
      p_target_authority = 'guides'
      and p_target_kind in ('guide', 'guide_page')
    )
    or (
      p_target_authority = 'sources'
      and p_target_kind = 'source'
    )
  ) then
    raise exception 'Unsupported Media usage target authority and kind';
  end if;

  case
    when p_target_authority = 'editorial'
      and p_target_kind = 'article'
    then
      select to_jsonb(article_row)
      into v_target_snapshot
      from public.wk_articles article_row
      where article_row.id = p_target_id;

    when p_target_authority = 'editorial'
      and p_target_kind = 'playlist'
    then
      select to_jsonb(playlist_row)
      into v_target_snapshot
      from public.wk_playlists playlist_row
      where playlist_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'artist'
    then
      select to_jsonb(artist_row)
      into v_target_snapshot
      from public.registry_artists artist_row
      where artist_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'author'
    then
      select to_jsonb(author_row)
      into v_target_snapshot
      from public.registry_authors author_row
      where author_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'release'
    then
      select to_jsonb(release_row)
      into v_target_snapshot
      from public.registry_releases release_row
      where release_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'track'
    then
      select to_jsonb(track_row)
      into v_target_snapshot
      from public.registry_tracks track_row
      where track_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'highlight'
    then
      select to_jsonb(highlight_row)
      into v_target_snapshot
      from public.registry_artist_highlights highlight_row
      where highlight_row.id = p_target_id;

    when p_target_authority = 'charts'
      and p_target_kind = 'chart_entry'
    then
      select to_jsonb(entry_row)
      into v_target_snapshot
      from public.chart_entries entry_row
      where entry_row.id = p_target_id;

    when p_target_authority = 'guides'
      and p_target_kind = 'guide'
    then
      select to_jsonb(guide_row)
      into v_target_snapshot
      from public.guides guide_row
      where guide_row.id = p_target_id;

    when p_target_authority = 'guides'
      and p_target_kind = 'guide_page'
    then
      select to_jsonb(page_row)
      into v_target_snapshot
      from public.guide_pages page_row
      where page_row.id = p_target_id;

    when p_target_authority = 'sources'
      and p_target_kind = 'source'
    then
      select to_jsonb(source_row)
      into v_target_snapshot
      from editorial.sources source_row
      where source_row.id = p_target_id;
  end case;

  v_exists := v_target_snapshot is not null;

  if not v_exists then
    raise exception 'Media usage target does not exist';
  end if;

  if p_require_attachable_target
    and not media.usage_target_snapshot_is_attachable(v_target_snapshot)
  then
    raise exception 'Media usage target is archived or unresolved';
  end if;

  if (
    p_target_version_kind is null
    and p_target_version_id is not null
  ) or (
    p_target_version_kind is not null
    and p_target_version_id is null
  ) then
    raise exception 'Media target-version kind and identity must be supplied together';
  end if;

  if p_target_version_id is not null then
    if p_target_authority = 'editorial'
      and p_target_kind = 'article'
    then
      select version_row.version_kind
      into v_version_kind
      from editorial.article_versions version_row
      where version_row.id = p_target_version_id
        and version_row.article_id = p_target_id;

      if not found
        or v_version_kind is distinct from p_target_version_kind
      then
        raise exception 'Media Article target version is invalid';
      end if;

    elsif p_target_authority = 'editorial'
      and p_target_kind = 'playlist'
    then
      select version_row.version_kind
      into v_version_kind
      from editorial.playlist_versions version_row
      where version_row.id = p_target_version_id
        and version_row.playlist_id = p_target_id;

      if not found
        or v_version_kind is distinct from p_target_version_kind
      then
        raise exception 'Media Playlist target version is invalid';
      end if;

    elsif p_target_authority = 'sources'
      and p_target_kind = 'source'
    then
      if p_target_version_kind <> 'source_version'
        or not exists (
          select 1
          from editorial.source_versions version_row
          where version_row.id = p_target_version_id
            and version_row.source_id = p_target_id
        )
      then
        raise exception 'Media Source target version is invalid';
      end if;

    else
      raise exception 'This Media usage target does not support version identity';
    end if;
  end if;

  if not p_require_edit_authority then
    return;
  end if;

  if public.current_user_is_administrator() then
    return;
  end if;

  case p_target_authority
    when 'editorial' then
      if p_target_kind = 'article' then
        v_authorized :=
          public.current_user_has_capability('edit_others_articles')
          or public.current_user_has_capability('publish_articles')
          or (
            public.current_user_has_capability('edit_own_articles')
            and exists (
              select 1
              from editorial.article_resources binding
              join editorial.resources resource_row
                on resource_row.id = binding.resource_id
              where binding.article_id = p_target_id
                and resource_row.owner_id = p_actor_id
            )
          );
      elsif p_target_kind = 'playlist' then
        v_authorized :=
          public.current_user_has_capability('edit_others_playlists')
          or public.current_user_has_capability('publish_playlists')
          or (
            public.current_user_has_capability('edit_own_playlists')
            and exists (
              select 1
              from editorial.playlist_resources binding
              join editorial.resources resource_row
                on resource_row.id = binding.resource_id
              where binding.playlist_id = p_target_id
                and resource_row.owner_id = p_actor_id
            )
          );
      end if;

    when 'registry' then
      v_authorized := public.current_user_has_capability('manage_registry');

    when 'charts' then
      v_authorized := public.current_user_has_capability('manage_charts');

    when 'guides' then
      v_authorized := public.current_user_has_capability('edit_guides');

    when 'sources' then
      v_authorized := public.current_user_has_capability('manage_sources');
  end case;

  if not coalesce(v_authorized, false) then
    raise exception 'Edit authority for the Media usage target is required';
  end if;
end;
$function$

do $phase_5a_m208_cleanup_proof$
begin
  if exists (select 1 from public.wk_playlists) then
    raise exception 'STOP: Playlist cleanup did not converge to zero rows';
  end if;

  if exists (select 1 from public.wk_playlist_items) then
    raise exception 'STOP: Playlist-item cleanup did not converge to zero rows';
  end if;

  if exists (select 1 from editorial.playlist_resources) then
    raise exception 'STOP: Playlist Resource cleanup did not converge to zero rows';
  end if;

  if exists (
    select 1
    from editorial.resources
    where id = 'a0ba2456-07bb-4d20-8031-87dc8a998179'::uuid
  ) then
    raise exception 'STOP: Fake Playlist Resource identity still exists';
  end if;
end;
$phase_5a_m208_cleanup_proof$

do $phase_5a_m208_postconditions$
declare
  playlist_capability_count bigint;
begin
  if exists (select 1 from public.wk_playlists) then
    raise exception 'STOP: Canonical Playlist foundation did not begin from zero Playlist rows';
  end if;

  if exists (select 1 from public.wk_playlist_items) then
    raise exception 'STOP: Canonical Playlist foundation did not begin from zero Playlist items';
  end if;

  if not exists (
    select 1
    from editorial.resource_kinds
    where kind = 'playlist_item'
      and enabled
  ) then
    raise exception 'STOP: playlist_item Resource kind was not registered';
  end if;

  if to_regclass('editorial.playlist_item_resources') is null
     or to_regclass('editorial.playlist_versions') is null
     or to_regclass('editorial.playlist_version_items') is null then
    raise exception 'STOP: One or more Playlist authority tables were not created';
  end if;

  if not exists (
    select 1
    from media.usage_roles
    where usage_role = 'playlist_cover'
      and enabled
  ) then
    raise exception 'STOP: Playlist cover Media usage role was not registered';
  end if;

  select count(*)
  into playlist_capability_count
  from public.capability_definitions
  where capability_key in (
    'view_playlists',
    'edit_own_playlists',
    'edit_others_playlists',
    'publish_playlists',
    'delete_playlists'
  );

  if playlist_capability_count <> 5 then
    raise exception
      'STOP: Expected 5 Playlist capabilities, found %',
      playlist_capability_count;
  end if;
end;
$phase_5a_m208_postconditions$

do $phase_5a_m209_preflight$
declare
  v_playlist_count bigint;
  v_item_count bigint;
  v_existing_command_count bigint;
begin
  if to_regclass('public.wk_playlists') is null
     or to_regclass('public.wk_playlist_items') is null
     or to_regclass('editorial.resources') is null
     or to_regclass('editorial.playlist_resources') is null
     or to_regclass('editorial.playlist_item_resources') is null
  then
    raise exception 'STOP: Phase 5A Migration 208 Playlist authority is incomplete';
  end if;

  if to_regclass('platform_private.command_types') is null
     or to_regclass('platform_private.command_receipts') is null
     or to_regclass('platform_private.outbox_events') is null
  then
    raise exception 'STOP: Shared command receipt/outbox authority is missing';
  end if;

  if to_regprocedure(
       'platform_private.complete_resource_command(uuid,jsonb)'
     ) is null
     or to_regprocedure(
       'platform_private.reject_resource_command(uuid,text,text,jsonb)'
     ) is null
  then
    raise exception 'STOP: Shared resource-command completion authority is missing';
  end if;

  if to_regprocedure('public.current_user_has_capability(text)') is null
     or to_regprocedure('public.current_user_is_administrator()') is null
  then
    raise exception 'STOP: Capability helpers are missing';
  end if;

  if not exists (
    select 1
    from pg_extension
    where extname = 'pgcrypto'
  ) then
    raise exception 'STOP: pgcrypto extension is missing';
  end if;

  if exists (
    select 1
    from (
      values
        ('view_playlists'),
        ('edit_own_playlists'),
        ('edit_others_playlists'),
        ('publish_playlists'),
        ('delete_playlists')
    ) required(capability_key)
    where not exists (
      select 1
      from public.capability_definitions definition
      where definition.capability_key = required.capability_key
    )
  ) then
    raise exception 'STOP: One or more Phase 5A Playlist capabilities are missing';
  end if;

  select count(*)
  into v_playlist_count
  from public.wk_playlists;

  select count(*)
  into v_item_count
  from public.wk_playlist_items;

  if v_playlist_count <> 0 or v_item_count <> 0 then
    raise exception
      'STOP: Migration 209 expects the accepted empty canonical Playlist starting state. Found % Playlist(s) and % item(s)',
      v_playlist_count,
      v_item_count;
  end if;

  select count(*)
  into v_existing_command_count
  from platform_private.command_types
  where command_type in (
    'playlist.create',
    'playlist.metadata.update',
    'playlist.item.add',
    'playlist.item.update',
    'playlist.item.remove',
    'playlist.items.reorder',
    'playlist.item.note.save',
    'playlist.item.match.resolve'
  );

  if v_existing_command_count <> 0 then
    raise exception
      'STOP: One or more Playlist command types already exist';
  end if;

  if to_regprocedure(
       'public.create_playlist(text,text,text,text,text,jsonb,uuid)'
     ) is not null
     or to_regprocedure(
       'public.update_playlist_metadata(uuid,bigint,jsonb,text,uuid)'
     ) is not null
     or to_regprocedure(
       'public.reorder_playlist_items(uuid,bigint,uuid[],text,uuid)'
     ) is not null
  then
    raise exception 'STOP: One or more Migration 209 Playlist RPCs already exist';
  end if;
end;
$phase_5a_m209_preflight$

-- ---------------------------------------------------------------------------
-- Canonical Playlist creation.
-- ---------------------------------------------------------------------------

create or replace function public.create_playlist(
  p_title text,
  p_slug text,
  p_idempotency_key text,
  p_description text default null,
  p_curator_label text default null,
  p_metadata jsonb default '{}'::jsonb,
  p_correlation_id uuid default null
)
returns table(
  command_receipt_id uuid,
  receipt_status text,
  playlist_id uuid,
  resource_id uuid,
  authority_revision bigint,
  result_payload jsonb,
  idempotent_replay boolean
)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
as $function$
declare
  v_actor uuid;
  v_principal_key text;
  v_title text;
  v_slug text;
  v_description text;
  v_curator_label text;
  v_metadata jsonb;
  v_correlation_id uuid;
  v_request jsonb;
  v_existing platform_private.command_receipts%rowtype;
  v_expected_fingerprint text;
  v_resource_id uuid;
  v_begin record;
  v_read record;
  v_result jsonb;
begin
  select context.actor_user_id, context.principal_key
  into v_actor, v_principal_key
  from platform_private.command_actor_context() context;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('edit_own_playlists')
    or public.current_user_has_capability('edit_others_playlists')
  ) then
    raise exception
      using errcode = '42501', message = 'Playlist creation permission is required.';
  end if;

  if p_idempotency_key is null
     or p_idempotency_key !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception
      using errcode = '22023', message = 'idempotency_key is invalid.';
  end if;

  v_title := nullif(btrim(p_title), '');
  v_slug := nullif(btrim(lower(p_slug)), '');
  v_description := nullif(btrim(p_description), '');
  v_curator_label := nullif(btrim(p_curator_label), '');
  v_metadata := coalesce(p_metadata, '{}'::jsonb);
  v_correlation_id := coalesce(p_correlation_id, gen_random_uuid());

  if v_title is null or length(v_title) > 300 then
    raise exception
      using errcode = '22023', message = 'Playlist title is required and must not exceed 300 characters.';
  end if;

  if v_slug is null
     or length(v_slug) > 200
     or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
  then
    raise exception
      using errcode = '22023', message = 'Playlist slug is invalid.';
  end if;

  if length(coalesce(v_description, '')) > 10000
     or length(coalesce(v_curator_label, '')) > 500
  then
    raise exception
      using errcode = '22023', message = 'Playlist description or curator label is too long.';
  end if;

  if jsonb_typeof(v_metadata) <> 'object'
     or octet_length(v_metadata::text) > 16384
  then
    raise exception
      using errcode = '22023', message = 'Playlist metadata must be an object no larger than 16 KB.';
  end if;

  v_request := jsonb_build_object(
    'title', v_title,
    'slug', v_slug,
    'description', v_description,
    'curator_label', v_curator_label,
    'metadata', v_metadata,
    'correlation_id', v_correlation_id
  );

  perform pg_advisory_xact_lock(
    hashtextextended(
      v_principal_key || ':playlist.create:' || p_idempotency_key,
      0
    )
  );

  select receipt.*
  into v_existing
  from platform_private.command_receipts receipt
  where receipt.principal_key = v_principal_key
    and receipt.command_type = 'playlist.create'
    and receipt.idempotency_key = p_idempotency_key
  for update;

  if found then
    v_expected_fingerprint :=
      platform_private.command_request_fingerprint(
        'playlist.create',
        v_existing.resource_id,
        v_request
      );

    if v_existing.request_fingerprint <> v_expected_fingerprint then
      raise exception
        using
          errcode = '23505',
          message = 'The idempotency key was already used for a different Playlist create request.';
    end if;

    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_existing.id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := nullif(v_read.result_payload ->> 'playlist_id', '')::uuid;
    resource_id := v_read.resource_id;
    authority_revision := nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if exists (
    select 1
    from public.wk_playlists playlist
    where playlist.slug = v_slug
  ) then
    raise exception
      using errcode = '23505', message = 'Playlist slug already exists.';
  end if;

  v_resource_id := gen_random_uuid();

  insert into editorial.resources (
    id,
    resource_kind,
    owner_id,
    visibility,
    lifecycle_state,
    created_by
  )
  values (
    v_resource_id,
    'playlist',
    v_actor,
    'internal',
    'active',
    v_actor
  );

  insert into public.wk_playlists (
    id,
    title,
    slug,
    description,
    curator_label,
    status,
    cover_image_url,
    canonical_url,
    source_inquiry_id,
    source_work_product_link_id,
    metadata,
    created_by,
    authority_revision
  )
  values (
    v_resource_id,
    v_title,
    v_slug,
    v_description,
    v_curator_label,
    'draft',
    null,
    null,
    null,
    null,
    v_metadata,
    v_actor,
    1
  );

  insert into editorial.playlist_resources (
    resource_id,
    resource_kind,
    playlist_id
  )
  values (
    v_resource_id,
    'playlist',
    v_resource_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.create',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    raise exception 'Unexpected Playlist create replay after serialized preflight.';
  end if;

  v_result := jsonb_build_object(
    'playlist_id', v_resource_id,
    'resource_id', v_resource_id,
    'slug', v_slug,
    'authority_revision', 1,
    'status', 'draft',
    'correlation_id', v_correlation_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  command_receipt_id := v_begin.command_receipt_id;
  receipt_status := 'succeeded';
  playlist_id := v_resource_id;
  resource_id := v_resource_id;
  authority_revision := 1;
  result_payload := v_result;
  idempotent_replay := false;
  return next;
end;
$function$

-- ---------------------------------------------------------------------------
-- Playlist metadata update.
-- ---------------------------------------------------------------------------

create or replace function public.update_playlist_metadata(
  p_playlist_id uuid,
  p_expected_authority_revision bigint,
  p_payload jsonb,
  p_idempotency_key text,
  p_correlation_id uuid default null
)
returns table(
  command_receipt_id uuid,
  receipt_status text,
  playlist_id uuid,
  resource_id uuid,
  authority_revision bigint,
  result_payload jsonb,
  idempotent_replay boolean
)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
as $function$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_new_title text;
  v_new_slug text;
  v_new_description text;
  v_new_curator_label text;
  v_new_metadata jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using errcode = '22023', message = 'Playlist and expected authority revision are required.';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
     or p_payload = '{}'::jsonb
     or p_payload - array[
       'title',
       'slug',
       'description',
       'curator_label',
       'metadata'
     ] <> '{}'::jsonb
  then
    raise exception
      using errcode = '22023', message = 'Playlist metadata payload is invalid.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision', p_expected_authority_revision,
    'payload', p_payload,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.metadata.update',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision := nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this metadata update could be applied.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    v_new_title := case
      when p_payload ? 'title'
        then nullif(btrim(p_payload ->> 'title'), '')
      else v_playlist.title
    end;

    v_new_slug := case
      when p_payload ? 'slug'
        then nullif(btrim(lower(p_payload ->> 'slug')), '')
      else v_playlist.slug
    end;

    v_new_description := case
      when p_payload ? 'description'
        then nullif(btrim(p_payload ->> 'description'), '')
      else v_playlist.description
    end;

    v_new_curator_label := case
      when p_payload ? 'curator_label'
        then nullif(btrim(p_payload ->> 'curator_label'), '')
      else v_playlist.curator_label
    end;

    v_new_metadata := case
      when p_payload ? 'metadata'
        then coalesce(p_payload -> 'metadata', '{}'::jsonb)
      else v_playlist.metadata
    end;

    if v_new_title is null or length(v_new_title) > 300 then
      raise exception
        using errcode = '22023', message = 'Playlist title is invalid.';
    end if;

    if v_new_slug is null
       or length(v_new_slug) > 200
       or v_new_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    then
      raise exception
        using errcode = '22023', message = 'Playlist slug is invalid.';
    end if;

    if length(coalesce(v_new_description, '')) > 10000
       or length(coalesce(v_new_curator_label, '')) > 500
       or jsonb_typeof(v_new_metadata) <> 'object'
       or octet_length(v_new_metadata::text) > 16384
    then
      raise exception
        using errcode = '22023', message = 'Playlist metadata values are invalid.';
    end if;

    if v_new_slug <> v_playlist.slug
       and exists (
         select 1
         from public.wk_playlists other_playlist
         where other_playlist.slug = v_new_slug
           and other_playlist.id <> p_playlist_id
       )
    then
      raise exception
        using errcode = '23505', message = 'Playlist slug already exists.';
    end if;

    update public.wk_playlists playlist
    set
      title = v_new_title,
      slug = v_new_slug,
      description = v_new_description,
      curator_label = v_new_curator_label,
      metadata = v_new_metadata,
      authority_revision = playlist.authority_revision + 1
    where playlist.id = p_playlist_id
    returning playlist.*
    into v_playlist;

    v_result := jsonb_build_object(
      'playlist_id', p_playlist_id,
      'resource_id', v_resource_id,
      'slug', v_playlist.slug,
      'authority_revision', v_playlist.authority_revision,
      'correlation_id', v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision := nullif(
    v_read.result_payload ->> 'authority_revision',
    ''
  )::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$function$

-- ---------------------------------------------------------------------------
-- Playlist item intake.
-- ---------------------------------------------------------------------------

create or replace function public.add_playlist_item(
  p_playlist_id uuid,
  p_expected_authority_revision bigint,
  p_idempotency_key text,
  p_registry_track_id uuid default null,
  p_provider_key text default null,
  p_provider_track_id text default null,
  p_provider_url text default null,
  p_title text default null,
  p_artist_names text[] default '{}'::text[],
  p_release_title text default null,
  p_correlation_id uuid default null
)
returns table(
  command_receipt_id uuid,
  receipt_status text,
  playlist_id uuid,
  resource_id uuid,
  playlist_item_id uuid,
  authority_revision bigint,
  result_payload jsonb,
  idempotent_replay boolean
)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
as $function$
declare
  v_playlist public.wk_playlists%rowtype;
  v_playlist_resource editorial.resources%rowtype;
  v_resource_id uuid;
  v_item_id uuid;
  v_position integer;
  v_provider_key text := nullif(btrim(lower(p_provider_key)), '');
  v_provider_track_id text := nullif(btrim(p_provider_track_id), '');
  v_provider_url text := nullif(btrim(p_provider_url), '');
  v_registry_track_id uuid := p_registry_track_id;
  v_registry_release_id uuid;
  v_title text := nullif(btrim(p_title), '');
  v_artist_names text[] := coalesce(p_artist_names, '{}'::text[]);
  v_release_title text := nullif(btrim(p_release_title), '');
  v_artwork_url text;
  v_preview_url text;
  v_duration_ms integer;
  v_isrc text;
  v_match_status text;
  v_match_confidence numeric(5,4);
  v_normalization jsonb := '{}'::jsonb;
  v_provider_link public.registry_track_provider_links%rowtype;
  v_duplicate_ids uuid[];
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using errcode = '22023', message = 'Playlist and expected authority revision are required.';
  end if;

  if (v_provider_key is null) <> (v_provider_track_id is null) then
    raise exception
      using errcode = '22023', message = 'Provider key and provider track identity must be supplied together.';
  end if;

  if v_provider_key is not null
     and v_provider_key !~ '^[a-z0-9_]+$'
  then
    raise exception
      using errcode = '22023', message = 'Provider key is invalid.';
  end if;

  if v_registry_track_id is null
     and v_provider_key is null
     and (
       v_title is null
       or cardinality(v_artist_names) = 0
       or nullif(btrim(coalesce(v_artist_names[1], '')), '') is null
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'A Registry track, provider identity, or external title and artist are required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  select resource_row.*
  into v_playlist_resource
  from editorial.resources resource_row
  where resource_row.id = v_resource_id;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision', p_expected_authority_revision,
    'registry_track_id', p_registry_track_id,
    'provider_key', v_provider_key,
    'provider_track_id', v_provider_track_id,
    'provider_url', v_provider_url,
    'title', v_title,
    'artist_names', to_jsonb(v_artist_names),
    'release_title', v_release_title,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.add',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    playlist_item_id := nullif(
      v_read.result_payload ->> 'playlist_item_id',
      ''
    )::uuid;
    authority_revision := nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this track could be added.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    if v_provider_key is not null then
      select provider_link.*
      into v_provider_link
      from public.registry_track_provider_links provider_link
      where provider_link.provider_key = v_provider_key
        and provider_link.provider_track_id = v_provider_track_id;

      if found then
        if p_registry_track_id is not null
           and v_provider_link.match_status = 'matched'
           and v_provider_link.track_id <> p_registry_track_id
        then
          raise exception
            using
              errcode = '22023',
              message = 'Provider identity is matched to a different Registry track.';
        end if;

        if p_registry_track_id is null
           and v_provider_link.match_status = 'matched'
        then
          v_registry_track_id := v_provider_link.track_id;
        elsif p_registry_track_id is null
              and v_provider_link.match_status = 'needs_review'
        then
          v_normalization := jsonb_build_object(
            'suggested_registry_track_id', v_provider_link.track_id,
            'provider_match_status', v_provider_link.match_status,
            'provider_match_method', v_provider_link.match_method
          );
        end if;

        v_match_confidence := v_provider_link.match_confidence;
        v_preview_url := v_provider_link.preview_url;
        v_artwork_url := v_provider_link.artwork_url;
        v_duration_ms := v_provider_link.duration_ms;
        v_isrc := v_provider_link.isrc;
      end if;
    end if;

    if v_registry_track_id is not null then
      select
        track.title,
        track.release_id,
        release.title,
        coalesce(track.artwork_url, v_artwork_url),
        coalesce(track.preview_url, v_preview_url),
        coalesce(track.duration_ms, v_duration_ms),
        coalesce(track.isrc, v_isrc),
        coalesce(
          array_agg(
            coalesce(artist.display_name, link.artist_name_text)
            order by link.credit_order, link.id
          ) filter (
            where coalesce(artist.display_name, link.artist_name_text) is not null
          ),
          '{}'::text[]
        )
      into
        v_title,
        v_registry_release_id,
        v_release_title,
        v_artwork_url,
        v_preview_url,
        v_duration_ms,
        v_isrc,
        v_artist_names
      from public.registry_tracks track
      left join public.registry_releases release
        on release.id = track.release_id
      left join public.registry_track_artists link
        on link.track_id = track.id
        and link.status = 'active'
      left join public.registry_artists artist
        on artist.id = link.artist_id
      where track.id = v_registry_track_id
        and track.status = 'active'
      group by
        track.id,
        track.title,
        track.release_id,
        release.title,
        track.artwork_url,
        track.preview_url,
        track.duration_ms,
        track.isrc;

      if not found then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'registry_track_unavailable',
          'The selected Registry track is not active.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision
          )
        );
      else
        v_match_status := 'matched';
        v_match_confidence := coalesce(v_match_confidence, 1.0000);
      end if;
    elsif v_provider_key is not null then
      if v_normalization ? 'suggested_registry_track_id' then
        v_match_status := 'needs_review';
      else
        v_match_status := 'pending';
      end if;
    else
      v_match_status := 'external_only';
    end if;

    if v_begin.command_receipt_id is not null
       and exists (
         select 1
         from platform_private.command_receipts receipt
         where receipt.id = v_begin.command_receipt_id
           and receipt.status = 'accepted'
       )
    then
      select coalesce(max(item.position), 0) + 1
      into v_position
      from public.wk_playlist_items item
      where item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active';

      v_item_id := gen_random_uuid();

      insert into editorial.resources (
        id,
        resource_kind,
        owner_id,
        visibility,
        lifecycle_state,
        created_by
      )
      values (
        v_item_id,
        'playlist_item',
        v_playlist_resource.owner_id,
        'internal',
        'active',
        auth.uid()
      );

      insert into public.wk_playlist_items (
        id,
        playlist_id,
        position,
        registry_track_id,
        registry_release_id,
        provider_key,
        provider_track_id,
        provider_url,
        title,
        artist_names,
        release_title,
        artwork_url,
        preview_url,
        duration_ms,
        isrc,
        match_status,
        match_confidence,
        normalization_payload,
        notes,
        created_by,
        lifecycle_state
      )
      values (
        v_item_id,
        p_playlist_id,
        v_position,
        v_registry_track_id,
        v_registry_release_id,
        v_provider_key,
        v_provider_track_id,
        v_provider_url,
        v_title,
        v_artist_names,
        v_release_title,
        v_artwork_url,
        v_preview_url,
        v_duration_ms,
        v_isrc,
        v_match_status,
        v_match_confidence,
        v_normalization,
        null,
        auth.uid(),
        'active'
      );

      insert into editorial.playlist_item_resources (
        resource_id,
        resource_kind,
        playlist_item_id
      )
      values (
        v_item_id,
        'playlist_item',
        v_item_id
      );

      v_duplicate_ids := editorial.playlist_duplicate_item_ids(
        p_playlist_id,
        v_item_id,
        v_registry_track_id,
        v_provider_key,
        v_provider_track_id,
        v_title,
        v_artist_names
      );

      update public.wk_playlists playlist
      set authority_revision = playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.authority_revision
      into v_playlist.authority_revision;

      v_result := jsonb_build_object(
        'playlist_id', p_playlist_id,
        'resource_id', v_resource_id,
        'playlist_item_id', v_item_id,
        'playlist_item_resource_id', v_item_id,
        'position', v_position,
        'match_status', v_match_status,
        'registry_track_id', v_registry_track_id,
        'duplicate_warning', cardinality(v_duplicate_ids) > 0,
        'duplicate_item_ids', to_jsonb(v_duplicate_ids),
        'authority_revision', v_playlist.authority_revision,
        'correlation_id', v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  playlist_item_id := nullif(
    v_read.result_payload ->> 'playlist_item_id',
    ''
  )::uuid;
  authority_revision := nullif(
    v_read.result_payload ->> 'authority_revision',
    ''
  )::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$function$

-- ---------------------------------------------------------------------------
-- Lightweight item presentation update. Match identity has a separate command.
-- ---------------------------------------------------------------------------

create or replace function public.update_playlist_item(
  p_playlist_id uuid,
  p_playlist_item_id uuid,
  p_expected_authority_revision bigint,
  p_payload jsonb,
  p_idempotency_key text,
  p_correlation_id uuid default null
)
returns table(
  command_receipt_id uuid,
  receipt_status text,
  playlist_id uuid,
  resource_id uuid,
  playlist_item_id uuid,
  authority_revision bigint,
  result_payload jsonb,
  idempotent_replay boolean
)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
as $function$
declare
  v_playlist public.wk_playlists%rowtype;
  v_item public.wk_playlist_items%rowtype;
  v_resource_id uuid;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_artist_names text[];
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_playlist_item_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist, item, and expected authority revision are required.';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
     or p_payload = '{}'::jsonb
     or p_payload - array[
       'title',
       'artist_names',
       'release_title',
       'provider_url'
     ] <> '{}'::jsonb
  then
    raise exception
      using errcode = '22023', message = 'Playlist-item update payload is invalid.';
  end if;

  if p_payload ? 'artist_names'
     and jsonb_typeof(p_payload -> 'artist_names') <> 'array'
  then
    raise exception
      using errcode = '22023', message = 'artist_names must be an array.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'playlist_item_id', p_playlist_item_id,
    'expected_authority_revision', p_expected_authority_revision,
    'payload', p_payload,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.update',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if not v_begin.idempotent_replay then
    if v_playlist.authority_revision <> p_expected_authority_revision then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_revision_changed',
        'The Playlist changed before this item update could be applied.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      select item.*
      into v_item
      from public.wk_playlist_items item
      where item.id = p_playlist_item_id
        and item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active'
      for update;

      if not found then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'playlist_item_not_active',
          'The Playlist item is missing or no longer active.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision
          )
        );
      else
        if v_item.registry_track_id is not null
           and (
             p_payload ? 'title'
             or p_payload ? 'artist_names'
             or p_payload ? 'release_title'
           )
        then
          raise exception
            using
              errcode = '22023',
              message = 'Matched Playlist track presentation is owned by Registry.';
        end if;

        if p_payload ? 'artist_names' then
          select coalesce(array_agg(value), '{}'::text[])
          into v_artist_names
          from jsonb_array_elements_text(
            p_payload -> 'artist_names'
          ) value;
        else
          v_artist_names := v_item.artist_names;
        end if;

        update public.wk_playlist_items item
        set
          title = case
            when p_payload ? 'title'
              then nullif(btrim(p_payload ->> 'title'), '')
            else item.title
          end,
          artist_names = v_artist_names,
          release_title = case
            when p_payload ? 'release_title'
              then nullif(btrim(p_payload ->> 'release_title'), '')
            else item.release_title
          end,
          provider_url = case
            when p_payload ? 'provider_url'
              then nullif(btrim(p_payload ->> 'provider_url'), '')
            else item.provider_url
          end
        where item.id = p_playlist_item_id
        returning item.*
        into v_item;

        if v_item.registry_track_id is null
           and v_item.provider_key is null
           and (
             nullif(btrim(coalesce(v_item.title, '')), '') is null
             or cardinality(v_item.artist_names) = 0
           )
        then
          raise exception
            using
              errcode = '22023',
              message = 'External Playlist items must retain a title and artist.';
        end if;

        update public.wk_playlists playlist
        set authority_revision = playlist.authority_revision + 1
        where playlist.id = p_playlist_id
        returning playlist.authority_revision
        into v_playlist.authority_revision;

        v_result := jsonb_build_object(
          'playlist_id', p_playlist_id,
          'playlist_item_id', p_playlist_item_id,
          'authority_revision', v_playlist.authority_revision,
          'correlation_id', v_correlation_id
        );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      end if;
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    v_begin.idempotent_replay
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  playlist_item_id := p_playlist_item_id;
  authority_revision := nullif(v_read.result_payload ->> 'authority_revision', '')::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := v_read.idempotent_replay;
  return next;
end;
$function$

