)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
as $function$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_note text := nullif(btrim(p_note), '');
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
