  receipt_status text,
  playlist_id uuid,
  resource_id uuid,
  authority_revision bigint,
  result_payload jsonb,
  idempotent_replay boolean
)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
as $function$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_active_count integer;
  v_distinct_count integer;
  v_offset integer;
  v_current_order uuid[];
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist and expected authority revision are required.';
  end if;

  if p_ordered_item_ids is null then
    raise exception
      using errcode = '22023', message = 'Complete ordered Playlist item identity is required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision', p_expected_authority_revision,
    'ordered_item_ids', to_jsonb(p_ordered_item_ids),
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.items.reorder',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if not v_begin.idempotent_replay then
    if v_playlist.authority_revision <> p_expected_authority_revision then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_revision_changed',
        'The Playlist changed before this order could be applied.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      select
        count(*),
        coalesce(max(item.position), 0),
        coalesce(array_agg(item.id order by item.position), '{}'::uuid[])
      into
        v_active_count,
        v_offset,
        v_current_order
      from public.wk_playlist_items item
      where item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active';

      select count(distinct item_id)
      into v_distinct_count
      from unnest(p_ordered_item_ids) item_id;

      if cardinality(p_ordered_item_ids) <> v_active_count
         or v_distinct_count <> v_active_count
         or exists (
           select 1
           from unnest(p_ordered_item_ids) requested(item_id)
           where not exists (
             select 1
             from public.wk_playlist_items item
             where item.id = requested.item_id
               and item.playlist_id = p_playlist_id
               and item.lifecycle_state = 'active'
           )
         )
      then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'invalid_playlist_order',
          'Reorder must contain every active Playlist item exactly once.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision,
            'active_item_count', v_active_count
          )
        );
      elsif v_current_order = p_ordered_item_ids then
        v_result := jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision,
          'active_item_count', v_active_count,
          'changed', false,
          'correlation_id', v_correlation_id
        );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      else
        v_offset := v_offset + v_active_count + 1;

        update public.wk_playlist_items item
        set position = item.position + v_offset
        where item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active';

        with requested as (
          select
            requested.item_id,
            requested.ordinality::integer as new_position
          from unnest(p_ordered_item_ids)
            with ordinality as requested(item_id, ordinality)
        )
        update public.wk_playlist_items item
        set position = requested.new_position
        from requested
        where item.id = requested.item_id
          and item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active';

        if exists (
          select 1
          from (
            select
              item.position,
              row_number() over (
                order by item.position
              )::integer as expected_position
            from public.wk_playlist_items item
            where item.playlist_id = p_playlist_id
              and item.lifecycle_state = 'active'
          ) ordered
          where ordered.position <> ordered.expected_position
        ) then
          raise exception 'Playlist reorder did not converge to a continuous position sequence.';
        end if;

        update public.wk_playlists playlist
        set authority_revision = playlist.authority_revision + 1
        where playlist.id = p_playlist_id
        returning playlist.authority_revision
        into v_playlist.authority_revision;

        v_result := jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision,
          'active_item_count', v_active_count,
          'changed', true,
          'correlation_id', v_correlation_id
        );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      end if;
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    v_begin.idempotent_replay
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision := nullif(v_read.result_payload ->> 'authority_revision', '')::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := v_read.idempotent_replay;
  return next;
end;
$function$

do $phase_5a_m209_postconditions$
declare
  v_command_count bigint;
  v_authenticated_write_grants bigint;
  v_institute_policy_count bigint;
begin
  select count(*)
  into v_command_count
  from platform_private.command_types
  where command_type in (
    'playlist.create',
    'playlist.metadata.update',
    'playlist.item.add',
    'playlist.item.update',
    'playlist.item.remove',
    'playlist.items.reorder',
    'playlist.item.note.save',
    'playlist.item.match.resolve'
  )
    and enabled;

  if v_command_count <> 8 then
    raise exception
      'STOP: Expected 8 enabled Playlist command types, found %',
      v_command_count;
  end if;

  select count(*)
  into v_authenticated_write_grants
  from information_schema.role_table_grants grant_row
  where grant_row.table_schema = 'public'
    and grant_row.table_name in (
      'wk_playlists',
      'wk_playlist_items'
    )
    and grant_row.grantee = 'authenticated'
    and grant_row.privilege_type in (
      'INSERT',
      'UPDATE',
      'DELETE',
      'TRUNCATE'
    );

  if v_authenticated_write_grants <> 0 then
    raise exception
      'STOP: Authenticated direct Playlist write grants remain';
  end if;

  select count(*)
  into v_institute_policy_count
  from pg_policies policy_row
  where policy_row.schemaname = 'public'
    and policy_row.tablename in (
      'wk_playlists',
      'wk_playlist_items'
    )
    and policy_row.policyname like '%institute%';

  if v_institute_policy_count <> 0 then
    raise exception
      'STOP: Institute Playlist RLS policies remain';
  end if;

  if to_regprocedure(
       'public.reorder_playlist_items(uuid,bigint,uuid[],text,uuid)'
     ) is null
     or to_regprocedure(
       'public.add_playlist_item(uuid,bigint,text,uuid,text,text,text,text,text[],text,uuid)'
     ) is null
  then
    raise exception 'STOP: One or more canonical Playlist item commands are missing';
  end if;
end;
$phase_5a_m209_postconditions$

do $phase_5a_m210_preflight$
begin
  if to_regprocedure(
       'editorial.current_user_can_view_playlist(uuid)'
     ) is null
  then
    raise exception
      'STOP: Migration 209 Playlist view authority helper is missing';
  end if;

  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'wk_playlists'
      and policyname = 'wk_playlists_authenticated_read'
  ) then
    raise exception
      'STOP: Migration 209 Playlist authenticated read policy is missing';
  end if;

  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'wk_playlist_items'
      and policyname = 'wk_playlist_items_authenticated_read'
  ) then
    raise exception
      'STOP: Migration 209 Playlist-item authenticated read policy is missing';
  end if;

  if exists (
    select 1
    from public.wk_playlists
  ) or exists (
    select 1
    from public.wk_playlist_items
  ) then
    raise exception
      'STOP: Migration 210 expects no persisted Playlist acceptance data';
  end if;
end;
$phase_5a_m210_preflight$

create policy wk_playlists_authenticated_read
on public.wk_playlists
for select
to authenticated
using (
  editorial.current_user_can_view_playlist_id(
    wk_playlists.id
  )
)

create policy wk_playlist_items_authenticated_read
on public.wk_playlist_items
for select
to authenticated
using (
  editorial.current_user_can_view_playlist_id(
    wk_playlist_items.playlist_id
  )
)

do $phase_5a_m210_postconditions$
declare
  v_policy_count bigint;
  v_direct_binding_policy_count bigint;
begin
  if to_regprocedure(
       'editorial.current_user_can_view_playlist_id(uuid)'
     ) is null
  then
    raise exception
      'STOP: RLS-safe Playlist identity predicate was not created';
  end if;

  select count(*)
  into v_policy_count
  from pg_policies
  where schemaname = 'public'
    and (
      (
        tablename = 'wk_playlists'
        and policyname = 'wk_playlists_authenticated_read'
        and qual like '%current_user_can_view_playlist_id%'
      )
      or (
        tablename = 'wk_playlist_items'
        and policyname = 'wk_playlist_items_authenticated_read'
        and qual like '%current_user_can_view_playlist_id%'
      )
    );

  if v_policy_count <> 2 then
    raise exception
      'STOP: Expected 2 repaired authenticated Playlist read policies, found %',
      v_policy_count;
  end if;

  select count(*)
  into v_direct_binding_policy_count
  from pg_policies
  where schemaname = 'public'
    and tablename in (
      'wk_playlists',
      'wk_playlist_items'
    )
    and policyname in (
      'wk_playlists_authenticated_read',
      'wk_playlist_items_authenticated_read'
    )
    and qual like '%playlist_resources%';

  if v_direct_binding_policy_count <> 0 then
    raise exception
      'STOP: Authenticated Playlist policy still crosses Playlist Resource RLS directly';
  end if;
end;
$phase_5a_m210_postconditions$

do $phase_5a_m211_preflight$
begin
  if to_regclass('public.wk_playlists') is null
     or to_regclass('public.wk_playlist_items') is null
     or to_regclass('editorial.playlist_resources') is null
     or to_regclass('editorial.playlist_item_resources') is null
     or to_regclass('editorial.playlist_versions') is null
     or to_regclass('editorial.playlist_version_items') is null
  then
    raise exception
      'STOP: Phase 5A Playlist authority foundation is incomplete';
  end if;

  if to_regprocedure(
       'platform_private.begin_authenticated_resource_command(text,uuid,text,jsonb)'
     ) is null
     or to_regprocedure(
       'platform_private.complete_resource_command(uuid,jsonb)'
     ) is null
     or to_regprocedure(
       'platform_private.reject_resource_command(uuid,text,text,jsonb)'
     ) is null
  then
    raise exception
      'STOP: Authenticated command substrate is incomplete';
  end if;

  if to_regprocedure(
       'editorial.current_user_can_edit_playlist(uuid)'
     ) is null
  then
    raise exception
      'STOP: Canonical Playlist edit authority is missing';
  end if;

  if not exists (
    select 1
    from public.capability_definitions
    where capability_key = 'manage_review_queue'
  ) or not exists (
    select 1
    from public.capability_definitions
    where capability_key = 'view_review_queue'
  ) then
    raise exception
      'STOP: Shared Review capability authority is missing';
  end if;

  if exists (select 1 from public.wk_playlists)
     or exists (select 1 from public.wk_playlist_items)
     or exists (select 1 from editorial.playlist_versions)
     or exists (select 1 from editorial.playlist_version_items)
  then
    raise exception
      'STOP: Migration 211 expects the accepted zero-Playlist production state';
  end if;

  if to_regclass('editorial.playlist_review_events') is not null then
    raise exception
      'STOP: Playlist Review event ledger already exists';
  end if;

  if exists (
    select 1
    from platform_private.command_types
    where command_type in (
      'playlist.version.snapshot_working',
      'playlist.review.submit',
      'playlist.review.decide'
    )
  ) then
    raise exception
      'STOP: Migration 211 Playlist Review command types already exist';
  end if;
end;
$phase_5a_m211_preflight$

create or replace function
  editorial.assert_playlist_version_cover_identity()
returns trigger
language plpgsql
security invoker
set search_path to 'pg_catalog', 'media'
as $function$
begin
  if new.cover_asset_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from media.asset_revisions revision
    where revision.id = new.cover_asset_revision_id
      and revision.asset_id = new.cover_asset_id
  ) then
    raise exception
      'Playlist version cover revision must belong to the same Media asset';
  end if;

  return new;
end;
$function$

create or replace function
  editorial.current_user_can_participate_playlist_review(
    p_resource_id uuid
  )
returns boolean
language sql
stable
security definer
set search_path to 'pg_catalog', 'public', 'editorial'
as $function$
  select
    auth.uid() is not null
    and (
      coalesce(
        editorial.current_user_can_edit_playlist(
          p_resource_id
        ),
        false
      )
      or coalesce(
        public.current_user_is_administrator(),
        false
      )
      or coalesce(
        public.current_user_has_capability(
          'view_review_queue'
        ),
        false
      )
      or coalesce(
        public.current_user_has_capability(
          'manage_review_queue'
        ),
        false
      )
    );
$function$

create policy playlist_review_events_participant_read
on editorial.playlist_review_events
for select
to authenticated
using (
  editorial.current_user_can_participate_playlist_review(
    resource_id
  )
)

create or replace function
  editorial.assert_resource_version_trust_attachment()
returns trigger
language plpgsql
security invoker
set search_path to
  'pg_catalog',
  'editorial'
as $function$
declare
  v_playlist_version
    editorial.playlist_versions%rowtype;
begin
  if new.resource_kind = 'article' then
    if new.target_version_type <> 'article_version'
    then
      raise exception
        'Article Trust attachments require article_version targets';
    end if;

    if not exists (
      select 1
      from editorial.article_versions version
      where version.id = new.target_version_id
        and version.resource_id = new.resource_id
    ) then
      raise exception
        'Trust attachment Article version must belong to the supplied resource';
    end if;

    if not exists (
      select 1
      from editorial.article_resources binding
      where binding.resource_id = new.resource_id
        and binding.resource_kind = 'article'
        and exists (
          select 1
          from editorial.article_versions version
          where version.id = new.target_version_id
            and version.article_id =
                  binding.article_id
        )
    ) then
      raise exception
        'Trust attachment requires a valid Article resource binding';
    end if;

    insert into editorial.article_version_trust_revisions (
      article_version_id
    )
    values (
      new.target_version_id
    )
    on conflict (article_version_id)
    do nothing;

    perform 1
    from editorial.article_version_trust_revisions revision
    where revision.article_version_id =
            new.target_version_id
    for update;

  elsif new.resource_kind in (
    'playlist',
    'playlist_item'
  ) then
    if new.target_version_type <> 'playlist_version'
    then
      raise exception
        'Playlist Trust attachments require playlist_version targets';
    end if;

    select version.*
    into v_playlist_version
    from editorial.playlist_versions version
    where version.id = new.target_version_id;

    if not found then
      raise exception
        'Playlist Trust attachment version was not found';
    end if;

    if new.resource_kind = 'playlist' then
      if v_playlist_version.resource_id <>
           new.resource_id
      then
        raise exception
          'Playlist Trust attachment must target the Playlist Resource belonging to the version';
      end if;

    elsif not exists (
      select 1
      from editorial.playlist_version_items item
      where item.playlist_version_id =
              new.target_version_id
        and item.playlist_item_resource_id =
              new.resource_id
    ) then
      raise exception
        'Playlist-item Trust attachment must target an item present in the Playlist version';
    end if;

    insert into editorial.playlist_version_trust_revisions (
      playlist_version_id
    )
    values (
      new.target_version_id
    )
    on conflict (playlist_version_id)
    do nothing;

    perform 1
    from editorial.playlist_version_trust_revisions revision
    where revision.playlist_version_id =
            new.target_version_id
    for update;

  else
    raise exception
      'Unsupported Trust attachment Resource kind: %',
      new.resource_kind;
  end if;

  if tg_table_name = 'resource_citations' then
    perform editorial.validate_citation_target_anchor(
      new.target_anchor_type,
      new.target_anchor_data
    );

    if new.public_safe
       and not exists (
         select 1
         from editorial.citations citation
         where citation.id = new.citation_id
           and citation.public_safe
           and citation.citation_state = 'active'
       )
    then
      raise exception
        'Public-safe Citation attachment requires an active public-safe Citation';
    end if;

  elsif tg_table_name = 'resource_credits' then
    if new.public_safe
       and not exists (
         select 1
         from editorial.credit_governance governance
         where governance.credit_id = new.credit_id
           and governance.public_safe
           and governance.credit_state = 'active'
       )
    then
      raise exception
        'Public-safe Credit attachment requires active public-safe governance';
    end if;

  else
    raise exception
      'Unsupported Trust attachment table: %',
      tg_table_name;
  end if;

  return new;
end;
$function$

create or replace function
  editorial.protect_playlist_immutable_trust_attachment()
returns trigger
language plpgsql
security invoker
set search_path to
  'pg_catalog',
  'editorial'
as $function$
declare
  v_version_kind text;
begin
  if old.target_version_type <> 'playlist_version'
  then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  select version.version_kind
  into v_version_kind
  from editorial.playlist_versions version
  where version.id = old.target_version_id;

  if v_version_kind in (
    'submitted',
    'approved',
    'published'
  ) then
    raise exception
      'Trust attachments on submitted, approved, or published Playlist versions are immutable';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$

create or replace function
  editorial.playlist_working_trust_target(
    p_playlist_version_id uuid,
    p_target_resource_id uuid
  )
returns table(
  root_resource_id uuid,
  target_resource_kind text,
  playlist_id uuid
)
language plpgsql
stable
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_version editorial.playlist_versions%rowtype;
  v_current_fingerprint text;
begin
  select version.*
  into v_version
  from editorial.playlist_versions version
  where version.id = p_playlist_version_id
    and version.version_kind = 'working';

  if not found then
    raise exception
      'Playlist Trust can be edited only on a working Playlist version';
  end if;

  if not exists (
    select 1
    from editorial.playlist_resources binding
    where binding.resource_id = v_version.resource_id
      and binding.playlist_id = v_version.playlist_id
      and binding.current_working_version_id =
            p_playlist_version_id
  ) then
    raise exception
      'Playlist Trust target must be the current working version';
  end if;

  v_current_fingerprint :=
    editorial.playlist_current_content_fingerprint(
      v_version.playlist_id
    );

  if v_version.content_fingerprint <>
       v_current_fingerprint
  then
    raise exception
      'Create a fresh working Playlist snapshot before changing version-bound Trust';
  end if;

  if p_target_resource_id = v_version.resource_id
  then
    root_resource_id := v_version.resource_id;
    target_resource_kind := 'playlist';
    playlist_id := v_version.playlist_id;
    return next;
    return;
  end if;

  if exists (
    select 1
    from editorial.playlist_version_items item
    where item.playlist_version_id =
            p_playlist_version_id
      and item.playlist_item_resource_id =
            p_target_resource_id
  ) then
    root_resource_id := v_version.resource_id;
    target_resource_kind := 'playlist_item';
    playlist_id := v_version.playlist_id;
    return next;
    return;
  end if;

  raise exception
    'Trust target Resource is not part of the working Playlist version';
end;
$function$

-- ---------------------------------------------------------------------------
-- Working snapshot command.
-- ---------------------------------------------------------------------------

create or replace function
  public.snapshot_playlist_working_version(
    p_playlist_id uuid,
    p_expected_authority_revision bigint,
    p_idempotency_key text,
    p_correlation_id uuid default null
  )
returns table(
  command_receipt_id uuid,
  receipt_status text,
  playlist_id uuid,
  resource_id uuid,
  authority_revision bigint,
  version_id uuid,
  version_number bigint,
  lifecycle_status text,
  result_payload jsonb,
  idempotent_replay boolean
)
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'auth',
  'editorial',
  'platform_private'
as $function$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_current editorial.playlist_versions%rowtype;
  v_snapshot record;
  v_fingerprint text;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_reused boolean := false;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if v_binding.resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_edit_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist edit permission is required';
  end if;

  v_fingerprint :=
    editorial.playlist_current_content_fingerprint(
      p_playlist_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.version.snapshot_working',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'content_fingerprint',
        v_fingerprint,
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload
          ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload
          ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload
          ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload
        ->> 'lifecycle_status';
    result_payload :=
      v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before the working snapshot could be created.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision
      )
    );
  else
    if v_binding.current_working_version_id
         is not null
    then
      select version.*
      into v_current
      from editorial.playlist_versions version
      where version.id =
        v_binding.current_working_version_id;

      if found
         and v_current.version_kind =
               'working'
         and v_current.content_fingerprint =
               v_fingerprint
      then
        select
          v_current.id as version_id,
          v_current.version_number as version_number,
          v_current.content_fingerprint as content_fingerprint,
          v_current.item_count as item_count
        into v_snapshot;

        v_reused := true;
      end if;
    end if;

    if not v_reused then
      select *
      into v_snapshot
      from editorial.insert_playlist_current_snapshot(
        p_playlist_id,
        v_playlist.authority_revision,
        'working',
        v_playlist.status,
        v_actor
      );

      update editorial.playlist_resources binding_update
      set current_working_version_id =
            v_snapshot.version_id
      where binding_update.playlist_id = p_playlist_id;
    end if;

    v_result := jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'resource_id',
        v_binding.resource_id,
      'authority_revision',
        v_playlist.authority_revision,
      'version_id',
        v_snapshot.version_id,
      'version_number',
        v_snapshot.version_number,
      'content_fingerprint',
        v_snapshot.content_fingerprint,
      'item_count',
        v_snapshot.item_count,
      'lifecycle_status',
        v_playlist.status,
      'reused_existing_snapshot',
        v_reused,
      'correlation_id',
        v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload
        ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload
        ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload
        ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload
      ->> 'lifecycle_status';
  result_payload :=
    v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
