create or replace function public.move_playlist_pending_registry_intake(
  p_playlist_id uuid,
  p_suggestion_id uuid,
  p_expected_authority_revision bigint,
  p_direction text,
  p_idempotency_key text,
  p_correlation_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'auth',
  'public',
  'editorial',
  'platform_private'
as $function$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_target_item_id uuid;
  v_target_suggestion_id uuid;
  v_target_position integer;
  v_temp_position integer;
  v_direction text := lower(btrim(coalesce(p_direction, '')));
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_changed boolean := false;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  if p_playlist_id is null
     or p_suggestion_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_direction not in ('up', 'down')
  then
    raise exception
      'Playlist, pending Registry track, expected revision, and move direction are required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'suggestion_id', p_suggestion_id,
    'expected_authority_revision', p_expected_authority_revision,
    'direction', v_direction,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.items.reorder',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );
    return v_read.result_payload;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this pending track could be moved.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    select suggestion.*
    into v_suggestion
    from public.registry_provider_track_suggestions suggestion
    where suggestion.id = p_suggestion_id
      and suggestion.source_playlist_id = p_playlist_id
      and suggestion.status = 'needs_review'
      and suggestion.source_playlist_item_id is null
      and suggestion.canonical_track_id is null
    for update;

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_pending_registry_intake_missing',
        'That pending Registry track is no longer reorderable in this Playlist.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      v_target_position :=
        v_suggestion.reserved_position
        + case when v_direction = 'up' then -1 else 1 end;

      if v_target_position > 0 then
        select item.id
        into v_target_item_id
        from public.wk_playlist_items item
        where item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active'
          and item.position = v_target_position
        for update;

        select suggestion.id
        into v_target_suggestion_id
        from public.registry_provider_track_suggestions suggestion
        where suggestion.source_playlist_id = p_playlist_id
          and suggestion.id <> p_suggestion_id
          and suggestion.status = 'needs_review'
          and suggestion.source_playlist_item_id is null
          and suggestion.canonical_track_id is null
          and suggestion.reserved_position = v_target_position
        for update;

        if v_target_item_id is not null
           and v_target_suggestion_id is not null
        then
          raise exception
            'Playlist position authority is corrupt: two entries occupy the target position.';
        end if;

        if v_target_item_id is not null
           or v_target_suggestion_id is not null
        then
          select greatest(
            coalesce(
              (
                select max(item.position)
                from public.wk_playlist_items item
                where item.playlist_id = p_playlist_id
                  and item.lifecycle_state = 'active'
              ),
              0
            ),
            coalesce(
              (
                select max(suggestion.reserved_position)
                from public.registry_provider_track_suggestions suggestion
                where suggestion.source_playlist_id = p_playlist_id
                  and suggestion.status = 'needs_review'
                  and suggestion.source_playlist_item_id is null
                  and suggestion.canonical_track_id is null
              ),
              0
            )
          ) + 100
          into v_temp_position;

          update public.registry_provider_track_suggestions suggestion
          set reserved_position = v_temp_position
          where suggestion.id = p_suggestion_id;

          if v_target_item_id is not null then
            update public.wk_playlist_items item
            set position = v_suggestion.reserved_position
            where item.id = v_target_item_id;
          else
            update public.registry_provider_track_suggestions suggestion
            set reserved_position = v_suggestion.reserved_position
            where suggestion.id = v_target_suggestion_id;
          end if;

          update public.registry_provider_track_suggestions suggestion
          set reserved_position = v_target_position
          where suggestion.id = p_suggestion_id;

          update public.wk_playlists playlist
          set authority_revision = playlist.authority_revision + 1
          where playlist.id = p_playlist_id
          returning playlist.authority_revision
          into v_playlist.authority_revision;

          v_changed := true;
        end if;
      end if;

      v_result := jsonb_build_object(
        'playlist_id', p_playlist_id,
        'suggestion_id', p_suggestion_id,
        'authority_revision', v_playlist.authority_revision,
        'changed', v_changed,
        'reserved_position',
          case
            when v_changed then v_target_position
            else v_suggestion.reserved_position
          end,
        'correlation_id', v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  return v_read.result_payload;
end;
$function$

-- Phase 5A Migration 216: Playlist/Registry review unification.
--
-- Product correction:
-- A Playlist entry remains a Playlist entry while Registry identity is pending.
-- Registry review changes identity state, not Playlist editing behaviour.
--
-- This migration:
-- 1. materializes pending Registry-intake tracks as ordinary wk_playlist_items;
-- 2. makes the existing Playlist note/reorder commands the only editor UX authority;
-- 3. keeps Registry review metadata attached to the same Playlist item;
-- 4. updates that same Playlist item in place when Registry canonicalizes it;
-- 5. exposes a governed Music Registry Track Intake review queue;
-- 6. allows Registry reviewers to resolve to an existing canonical track or reject;
-- 7. aligns legacy Media compatibility with canonical playlist_cover purpose.

begin

do $phase_5a_m216_preflight$
declare
  v_media_constraint text;
begin
  if to_regclass('public.wk_playlists') is null
     or to_regclass('public.wk_playlist_items') is null
     or to_regclass('public.registry_provider_track_suggestions') is null
     or to_regclass('public.registry_provider_track_suggestion_artists') is null
     or to_regclass('editorial.playlist_resources') is null
     or to_regclass('media.asset_purposes') is null
     or to_regclass('public.registry_media_assets') is null
  then
    raise exception
      'STOP: Required Playlist, Registry, or Media authority is missing';
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'registry_provider_track_suggestions'
      and column_name = 'playlist_note'
  ) then
    raise exception
      'STOP: M215 pending-note authority is missing';
  end if;

  if to_regprocedure(
       'public.reorder_playlist_items_with_intake_slots(uuid,bigint,uuid[],text,uuid)'
     ) is null
     or to_regprocedure(
       'public.save_playlist_item_note(uuid,uuid,bigint,text,text,uuid)'
     ) is null
  then
    raise exception
      'STOP: Canonical Playlist reorder or note authority is missing';
  end if;

  if not exists (
    select 1
    from media.asset_purposes purpose
    where purpose.asset_purpose = 'playlist_cover'
      and purpose.enabled
  ) then
    raise exception
      'STOP: Canonical Media purpose playlist_cover is not enabled';
  end if;

  select pg_get_constraintdef(c.oid)
  into v_media_constraint
  from pg_constraint c
  where c.conrelid = 'public.registry_media_assets'::regclass
    and c.conname = 'registry_media_assets_asset_purpose_check';

  if v_media_constraint is null then
    raise exception
      'STOP: Legacy Media asset-purpose compatibility constraint is missing';
  end if;

  if position('playlist_cover' in v_media_constraint) > 0 then
    raise exception
      'STOP: Media compatibility already accepts playlist_cover';
  end if;

  if to_regprocedure(
       'editorial.ensure_playlist_registry_intake_item(uuid)'
     ) is not null
     or to_regprocedure(
       'public.admin_get_registry_track_intake_queue(text,integer,integer,uuid,uuid)'
     ) is not null
     or to_regprocedure(
       'public.admin_resolve_registry_track_intake(uuid,uuid,text)'
     ) is not null
     or to_regprocedure(
       'public.admin_reject_registry_track_intake(uuid,text)'
     ) is not null
  then
    raise exception
      'STOP: One or more M216 authorities already exist';
  end if;
end;
$phase_5a_m216_preflight$

-- M216 materializes Registry-review tracks as Editorial playlist_item
-- resources. The generic deferred resource-binding invariant must therefore
-- understand the playlist_item typed binding before any new item is committed.
create or replace function editorial.assert_resource_binding_integrity()
returns trigger
language plpgsql
set search_path to 'pg_catalog', 'editorial'
as $function$
declare
  target_resource_id uuid;
  target_kind text;
  binding_count integer;
begin
  if tg_table_name = 'resources' then
    if tg_op = 'DELETE' then
      return null;
    end if;

    target_resource_id := new.id;
  else
    if tg_op = 'DELETE' then
      target_resource_id := old.resource_id;
    else
      target_resource_id := new.resource_id;
    end if;
  end if;

  select resource_kind
  into target_kind
  from editorial.resources
  where id = target_resource_id;

  if not found then
    return null;
  end if;

  case target_kind
    when 'article' then
      select count(*)
      into binding_count
      from editorial.article_resources
      where resource_id = target_resource_id;

    when 'playlist' then
      select count(*)
      into binding_count
      from editorial.playlist_resources
      where resource_id = target_resource_id;

    when 'playlist_item' then
      select count(*)
      into binding_count
      from editorial.playlist_item_resources
      where resource_id = target_resource_id;

    when 'registry_artist' then
      select count(*)
      into binding_count
      from editorial.registry_artist_resources
      where resource_id = target_resource_id;

    when 'correction_case' then
      select count(*)
      into binding_count
      from editorial.correction_cases
      where resource_id = target_resource_id;

    when 'media_asset' then
      select count(*)
      into binding_count
      from editorial.media_asset_resources
      where resource_id = target_resource_id;

    else
      raise exception
        'Unsupported resource kind: %',
        target_kind;
  end case;

  if binding_count <> 1 then
    raise exception
      'Resource % with kind % must have exactly one typed binding.',
      target_resource_id,
      target_kind;
  end if;

  return null;
end;
$function$

