create or replace function
  public.publish_playlist_version(
    p_playlist_id uuid,
    p_expected_authority_revision bigint,
    p_approved_version_id uuid,
    p_idempotency_key text,
    p_note text default null,
    p_correlation_id uuid default null
  )
returns table(
  command_receipt_id uuid,
  receipt_status text,
  playlist_id uuid,
  resource_id uuid,
  authority_revision bigint,
  version_id uuid,
  version_number bigint,
  lifecycle_status text,
  result_payload jsonb,
  idempotent_replay boolean
)
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'auth',
  'editorial',
  'platform_private'
as $function$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_approved editorial.playlist_versions%rowtype;
  v_published record;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_snapshot_id uuid;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
  v_source_version_id uuid;
  v_published_at timestamptz := now();
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if v_binding.resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_publish_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist publication permission is required';
  end if;

  v_source_version_id :=
    coalesce(
      p_approved_version_id,
      v_binding.current_approved_version_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.publish',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'approved_version_id',
        v_source_version_id,
      'note',
        nullif(btrim(p_note), ''),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload
          ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload
          ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload
          ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload
        ->> 'lifecycle_status';
    result_payload :=
      v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before it could be published.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );

  elsif v_playlist.status <> 'approved'
        or v_source_version_id is null
        or v_binding.current_approved_version_id
             is distinct from v_source_version_id
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_not_publishable',
      'Only the exact current approved Playlist version can be published.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status,
        'current_approved_version_id',
          v_binding.current_approved_version_id
      )
    );

  else
    select approved.*
    into v_approved
    from editorial.playlist_versions approved
    where approved.id = v_source_version_id
      and approved.resource_id =
            v_binding.resource_id
      and approved.playlist_id =
            p_playlist_id
      and approved.version_kind = 'approved';

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'approved_version_invalid',
        'The approved Playlist version is no longer publishable.',
        jsonb_build_object(
          'playlist_id',
            p_playlist_id,
          'approved_version_id',
            v_source_version_id
        )
      );
    end if;

    if exists (
      select 1
      from platform_private.command_receipts receipt
      where receipt.id =
              v_begin.command_receipt_id
        and receipt.status = 'accepted'
    ) then
      select *
      into v_published
      from editorial.copy_playlist_published_version(
        v_approved.id,
        v_actor
      );

      update editorial.playlist_resources binding_update
      set current_published_version_id =
            v_published.version_id
      where binding_update.playlist_id =
              p_playlist_id;

      update editorial.resources resource
      set
        current_published_version_id =
          v_published.version_id,
        lifecycle_state = 'published',
        visibility = 'public',
        updated_at = now()
      where resource.id =
              v_binding.resource_id;

      update public.wk_playlists playlist
      set
        status = 'published',
        published_at = v_published_at,
        canonical_url =
          'https://wakilisha.africa/playlists/'
          || v_approved.slug,
        authority_revision =
          playlist.authority_revision + 1,
        updated_at = now()
      where playlist.id = p_playlist_id
      returning playlist.*
      into v_playlist;

      v_snapshot_id :=
        editorial.materialize_playlist_publication_snapshot(
          v_published.version_id,
          v_published_at,
          v_actor,
          v_begin.command_receipt_id
        );

      v_result := jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'resource_id',
          v_binding.resource_id,
        'authority_revision',
          v_playlist.authority_revision,
        'approved_version_id',
          v_approved.id,
        'version_id',
          v_published.version_id,
        'version_number',
          v_published.version_number,
        'publication_snapshot_id',
          v_snapshot_id,
        'published_at',
          v_published_at,
        'lifecycle_status',
          'published',
        'correlation_id',
          v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload
        ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload
        ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload
        ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload
      ->> 'lifecycle_status';
  result_payload :=
    v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$function$

do $phase_5b_m219_preflight$
begin
  if to_regprocedure(
       'editorial.materialize_playlist_publication_snapshot(uuid,timestamp with time zone,uuid,uuid)'
     ) is null
  then
    raise exception
      'STOP: M218 Playlist publication materializer is missing';
  end if;

  if to_regclass(
       'public.registry_track_provider_links'
     ) is null
  then
    raise exception
      'STOP: Registry provider-link authority is missing';
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'registry_tracks'
      and column_name = 'metadata'
  ) then
    raise exception
      'STOP: Registry track metadata compatibility source is missing';
  end if;
end;
$phase_5b_m219_preflight$

create or replace function public.community_create_context_anchor_comment(
  p_thread_id uuid,
  p_body_markdown text,
  p_body_plain text default null,
  p_body_html text default null,
  p_anchor_type text default null,
  p_context_entity_type text default null,
  p_context_entity_id text default null,
  p_context_entity_slug text default null,
  p_context_label text default null,
  p_anchor_label text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
  v_comment_id uuid;
  v_comment public.community_comments%rowtype;
  v_anchor_type text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if nullif(trim(coalesce(p_body_markdown, '')), '') is null then
    raise exception 'Comment body cannot be empty' using errcode = '22023';
  end if;

  v_anchor_type := nullif(trim(coalesce(p_anchor_type, '')), '');

  if v_anchor_type is null
    or v_anchor_type not in (
      'release_track',
      'chart_entry',
      'playlist_track'
    )
  then
    raise exception 'Unsupported context anchor type' using errcode = '22023';
  end if;

  if nullif(trim(coalesce(p_context_entity_type, '')), '') is null then
    raise exception 'Context entity type is required' using errcode = '22023';
  end if;

  if nullif(
    trim(
      coalesce(
        p_context_entity_id,
        p_context_entity_slug,
        ''
      )
    ),
    ''
  ) is null
  then
    raise exception 'Context entity id or slug is required' using errcode = '22023';
  end if;

  select public.community_create_comment(
    p_thread_id,
    null,
    p_body_markdown,
    p_body_plain,
    p_body_html,
    'visible'
  )
  into v_result;

  v_comment_id := (v_result->'comment'->>'id')::uuid;

  update public.community_comments
  set
    anchor_type = v_anchor_type,
    context_entity_type = nullif(
      trim(coalesce(p_context_entity_type, '')),
      ''
    ),
    context_entity_id = nullif(
      trim(coalesce(p_context_entity_id, '')),
      ''
    ),
    context_entity_slug = nullif(
      trim(coalesce(p_context_entity_slug, '')),
      ''
    ),
    context_label = nullif(
      trim(coalesce(p_context_label, '')),
      ''
    ),
    anchor_label = nullif(
      trim(
        coalesce(
          p_anchor_label,
          p_context_label,
          ''
        )
      ),
      ''
    ),
    updated_at = now()
  where id = v_comment_id
  returning * into v_comment;

  return jsonb_build_object(
    'comment',
    to_jsonb(v_comment)
  );
end;
$$

create or replace function public.community_vote_comment(
  p_comment_id uuid,
  p_vote_value integer
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_user_id uuid := auth.uid();
  v_existing integer;
  v_current integer;
  v_upvote_count integer;
  v_downvote_count integer;
  v_score integer;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if p_vote_value not in (-1, 1) then
    raise exception
      'Invalid vote value'
      using errcode = '22023';
  end if;

  perform 1
  from public.community_comments comment
  where comment.id = p_comment_id
  for update;

  if not found then
    raise exception
      'Comment not found'
      using errcode = '22023';
  end if;

  select vote.vote_value
  into v_existing
  from public.community_votes vote
  where vote.user_id = v_user_id
    and vote.comment_id = p_comment_id;

  if v_existing is null then
    insert into public.community_votes (
      user_id,
      comment_id,
      vote_value
    )
    values (
      v_user_id,
      p_comment_id,
      p_vote_value
    );

    v_current := p_vote_value;

  elsif v_existing = p_vote_value then
    delete from public.community_votes
    where user_id = v_user_id
      and comment_id = p_comment_id;

    v_current := 0;

  else
    update public.community_votes
    set
      vote_value = p_vote_value,
      updated_at = now()
    where user_id = v_user_id
      and comment_id = p_comment_id;

    v_current := p_vote_value;
  end if;

  select
    count(*) filter (
      where vote.vote_value = 1
    )::integer,
    count(*) filter (
      where vote.vote_value = -1
    )::integer,
    coalesce(
      sum(vote.vote_value),
      0
    )::integer
  into
    v_upvote_count,
    v_downvote_count,
    v_score
  from public.community_votes vote
  where vote.comment_id = p_comment_id;

  update public.community_comments
  set
    upvote_count = v_upvote_count,
    downvote_count = v_downvote_count,
    score = v_score
  where id = p_comment_id;

  return jsonb_build_object(
    'vote_value',
      v_current,
    'existing',
      v_existing,
    'delta',
      v_current - coalesce(
        v_existing,
        0
      ),
    'upvote_count',
      v_upvote_count,
    'downvote_count',
      v_downvote_count,
    'score',
      v_score
  );
end;
$$

create or replace function public.community_react_to_target(
  p_target_type text,
  p_target_id uuid,
  p_reaction_type text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_user_id uuid := auth.uid();
  v_target_type text :=
    nullif(
      trim(
        coalesce(
          p_target_type,
          ''
        )
      ),
      ''
    );
  v_reaction_type text :=
    nullif(
      trim(
        coalesce(
          p_reaction_type,
          ''
        )
      ),
      ''
    );
  v_existing uuid;
  v_created boolean;
  v_reaction_count integer;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_target_type is null
     or p_target_id is null
  then
    raise exception
      'Reaction target is required'
      using errcode = '22023';
  end if;

  if v_reaction_type not in (
    'signal',
    'memory',
    'context',
    'fire',
    'agree'
  )
  then
    raise exception
      'Unsupported reaction type'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|'
      || v_target_type
      || '|'
      || p_target_id::text
      || '|'
      || v_reaction_type,
      0
    )
  );

  if v_target_type = 'comment' then
    perform 1
    from public.community_comments comment
    where comment.id = p_target_id
    for update;

    if not found then
      raise exception
        'Comment not found'
        using errcode = '22023';
    end if;
  end if;

  delete from public.community_reactions
  where user_id = v_user_id
    and target_type = v_target_type
    and target_id = p_target_id
    and reaction_type = v_reaction_type
  returning id
  into v_existing;

  if found then
    v_created := false;
  else
    insert into public.community_reactions (
      user_id,
      target_type,
      target_id,
      reaction_type
    )
    values (
      v_user_id,
      v_target_type,
      p_target_id,
      v_reaction_type
    );

    v_created := true;
  end if;

  if v_target_type = 'comment' then
    select count(*)::integer
    into v_reaction_count
    from public.community_reactions reaction
    where reaction.target_type = 'comment'
      and reaction.target_id = p_target_id;

    update public.community_comments
    set reaction_count = v_reaction_count
    where id = p_target_id;
  else
    v_reaction_count := null;
  end if;

  return jsonb_build_object(
    'created',
      v_created,
    'reaction_type',
      v_reaction_type,
    'reaction_count',
      v_reaction_count
  );
end;
$$

create or replace function public.community_set_follow_state(
  p_target_type text,
  p_target_id text,
  p_target_slug text,
  p_followed boolean
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_user_id uuid := auth.uid();
  v_target_type text :=
    nullif(
      trim(
        coalesce(
          p_target_type,
          ''
        )
      ),
      ''
    );
  v_target_id text :=
    nullif(
      trim(
        coalesce(
          p_target_id,
          ''
        )
      ),
      ''
    );
  v_target_slug text :=
    nullif(
      trim(
        coalesce(
          p_target_slug,
          ''
        )
      ),
      ''
    );
  v_followed boolean :=
    coalesce(
      p_followed,
      false
    );
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_target_type is null
     or v_target_id is null
  then
    raise exception
      'Follow target is required'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|follow|'
      || v_target_type
      || '|'
      || v_target_id,
      0
    )
  );

  if v_followed then
    insert into public.community_follows (
      user_id,
      target_type,
      target_id,
      target_slug
    )
    values (
      v_user_id,
      v_target_type,
      v_target_id,
      v_target_slug
    )
    on conflict (
      user_id,
      target_type,
      target_id
    )
    do update
    set target_slug =
      excluded.target_slug;
  else
    delete from public.community_follows
    where user_id = v_user_id
      and target_type = v_target_type
      and target_id = v_target_id;
  end if;

  return jsonb_build_object(
    'followed',
      v_followed
  );
end;
$$

create or replace function public.community_follow_target(
  p_target_type text,
  p_target_id text,
  p_target_slug text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_user_id uuid := auth.uid();
  v_target_type text :=
    nullif(
      trim(
        coalesce(
          p_target_type,
          ''
        )
      ),
      ''
    );
  v_target_id text :=
    nullif(
      trim(
        coalesce(
          p_target_id,
          ''
        )
      ),
      ''
    );
  v_current boolean;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_target_type is null
     or v_target_id is null
  then
    raise exception
      'Follow target is required'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|follow|'
      || v_target_type
      || '|'
      || v_target_id,
      0
    )
  );

  select exists (
    select 1
    from public.community_follows follow
    where follow.user_id = v_user_id
