-- People / Contributor Identity Migration A:
-- stable Person Resource identity foundation.
--
-- This migration creates only:
-- 1. the Person Resource kind and typed Person authority;
-- 2. explicit typed identity links to account, Registry Author, or external contributor;
-- 3. append-only Person identity events;
-- 4. public-safe Person presentation and canonical /people/ aliases;
-- 5. immediate account privacy and external-contributor consent visibility sync;
-- 6. exactly three conditional proof People in production data:
--    Hafare Segelan, one conservative public-account proof, and one
--    conservative public-safe external-contributor proof.
--
-- This migration does not:
-- - bulk backfill People;
-- - merge identities;
-- - expose current-public body of work;
-- - validate or enable Person Follow;
-- - expose follower counts;
-- - change frontend routes.

begin

do $people_migration_a_preflight$
declare
  v_resource_index_dependents integer;
  v_owner_index_dependents integer;
  v_binding_definition text;
begin
  if to_regclass('editorial.resources') is null
     or to_regclass('editorial.resource_kinds') is null
     or to_regclass('editorial.resource_aliases') is null
     or to_regclass('public.user_profiles') is null
     or to_regclass('public.registry_authors') is null
     or to_regclass('editorial.external_contributors') is null
     or to_regclass('public.wk_resource_index') is null
     or to_regclass('public.wk_resource_owner_index') is null
  then
    raise exception
      'STOP: Required Resource or identity authority is missing';
  end if;

  if to_regprocedure(
       'editorial.assert_resource_binding_integrity()'
     ) is null
  then
    raise exception
      'STOP: Resource binding integrity authority is missing';
  end if;

  select pg_get_functiondef(
    'editorial.assert_resource_binding_integrity()'::regprocedure
  )
  into v_binding_definition;

  if position('playlist_item' in v_binding_definition) = 0
     or position('registry_artist' in v_binding_definition) = 0
     or position('correction_case' in v_binding_definition) = 0
     or position('media_asset' in v_binding_definition) = 0
  then
    raise exception
      'STOP: Resource binding integrity is older than the accepted authority';
  end if;

  if exists (
    select 1
    from editorial.resource_kinds
    where kind = 'person'
  )
     or to_regclass('editorial.people') is not null
     or to_regclass('editorial.person_identity_links') is not null
     or to_regclass('editorial.person_identity_events') is not null
     or to_regprocedure(
          'public.get_public_person(text)'
        ) is not null
  then
    raise exception
      'STOP: Person identity authority already exists';
  end if;

  if exists (
    select 1
    from editorial.resource_aliases
    where path like '/people/%'
  ) then
    raise exception
      'STOP: /people/ Resource aliases already exist';
  end if;

  select count(*)
  into v_resource_index_dependents
  from pg_depend dependency
  join pg_rewrite rewrite_rule
    on rewrite_rule.oid = dependency.objid
  join pg_class dependent_relation
    on dependent_relation.oid = rewrite_rule.ev_class
  where dependency.refobjid =
        'public.wk_resource_index'::regclass
    and dependent_relation.oid <>
        'public.wk_resource_index'::regclass;

  if v_resource_index_dependents <> 0 then
    raise exception
      'STOP: public.wk_resource_index has % dependent database objects',
      v_resource_index_dependents;
  end if;

  select count(*)
  into v_owner_index_dependents
  from pg_depend dependency
  join pg_rewrite rewrite_rule
    on rewrite_rule.oid = dependency.objid
  join pg_class dependent_relation
    on dependent_relation.oid = rewrite_rule.ev_class
  where dependency.refobjid =
        'public.wk_resource_owner_index'::regclass
    and dependent_relation.oid <>
        'public.wk_resource_owner_index'::regclass;

  if v_owner_index_dependents <> 0 then
    raise exception
      'STOP: public.wk_resource_owner_index has % dependent database objects',
      v_owner_index_dependents;
  end if;
end;
$people_migration_a_preflight$

create or replace function
  editorial.assert_person_identity_integrity()
returns trigger
language plpgsql
set search_path to 'pg_catalog', 'editorial'
as $function$
declare
  v_person_resource_id uuid;
  v_preferred_identity_link_id uuid;
begin
  if tg_table_name = 'people' then
    v_person_resource_id := new.resource_id;
  elsif tg_op = 'DELETE' then
    v_person_resource_id := old.person_resource_id;
  else
    v_person_resource_id := new.person_resource_id;
  end if;

  select person.preferred_identity_link_id
  into v_preferred_identity_link_id
  from editorial.people person
  where person.resource_id = v_person_resource_id;

  if not found then
    return null;
  end if;

  if v_preferred_identity_link_id is not null
     and not exists (
       select 1
       from editorial.person_identity_links link
       where link.id = v_preferred_identity_link_id
         and link.person_resource_id = v_person_resource_id
         and link.link_state = 'active'
     )
  then
    raise exception
      'Preferred Person identity link must be active and belong to the same Person.';
  end if;

  return null;
end;
$function$

create or replace function
  editorial.assert_resource_binding_integrity()
returns trigger
language plpgsql
set search_path to 'pg_catalog', 'editorial'
as $function$
declare
  target_resource_id uuid;
  target_kind text;
  binding_count integer;
begin
  if tg_table_name = 'resources' then
    if tg_op = 'DELETE' then
      return null;
    end if;

    target_resource_id := new.id;
  else
    if tg_op = 'DELETE' then
      target_resource_id := old.resource_id;
    else
      target_resource_id := new.resource_id;
    end if;
  end if;

  select resource_kind
  into target_kind
  from editorial.resources
  where id = target_resource_id;

  if not found then
    return null;
  end if;

  case target_kind
    when 'article' then
      select count(*)
      into binding_count
      from editorial.article_resources
      where resource_id = target_resource_id;

    when 'playlist' then
      select count(*)
      into binding_count
      from editorial.playlist_resources
      where resource_id = target_resource_id;

    when 'playlist_item' then
      select count(*)
      into binding_count
      from editorial.playlist_item_resources
      where resource_id = target_resource_id;

    when 'registry_artist' then
      select count(*)
      into binding_count
      from editorial.registry_artist_resources
      where resource_id = target_resource_id;

    when 'correction_case' then
      select count(*)
      into binding_count
      from editorial.correction_cases
      where resource_id = target_resource_id;

    when 'media_asset' then
      select count(*)
      into binding_count
      from editorial.media_asset_resources
      where resource_id = target_resource_id;

    when 'person' then
      select count(*)
      into binding_count
      from editorial.people
      where resource_id = target_resource_id;

    else
      raise exception
        'Unsupported resource kind: %',
        target_kind;
  end case;

  if binding_count <> 1 then
    raise exception
      'Resource % with kind % must have exactly one typed binding.',
      target_resource_id,
      target_kind;
  end if;

  return null;
end;
$function$

create or replace function
  editorial.normalize_person_slug(
    p_seed text
  )
returns text
language plpgsql
immutable
set search_path to 'pg_catalog'
as $function$
declare
  v_slug text;
begin
  v_slug := lower(
    regexp_replace(
      btrim(
        coalesce(
          p_seed,
          ''
        )
      ),
      '[^[:alnum:]]+',
      '-',
      'g'
    )
  );

  v_slug := regexp_replace(
    v_slug,
    '(^-+|-+$)',
    '',
    'g'
  );

  return nullif(v_slug, '');
end;
$function$

create or replace function
  editorial.allocate_person_path(
    p_seed text,
    p_person_resource_id uuid
  )
returns text
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'editorial'
as $function$
declare
  v_slug text;
  v_path text;
  v_suffix text;
begin
  if p_person_resource_id is null then
    raise exception
      'Person Resource id is required.';
  end if;

  v_slug := coalesce(
    editorial.normalize_person_slug(p_seed),
    'person'
  );

  v_path := '/people/' || v_slug;

  if exists (
    select 1
    from editorial.resource_aliases alias
    where alias.path = v_path
  ) then
    v_suffix := substr(
      replace(
        p_person_resource_id::text,
        '-',
        ''
      ),
      1,
      8
    );

    v_path :=
      '/people/'
      || v_slug
      || '-'
      || v_suffix;
  end if;

  if exists (
    select 1
    from editorial.resource_aliases alias
    where alias.path = v_path
  ) then
    v_path :=
      '/people/person-'
      || replace(
           p_person_resource_id::text,
           '-',
           ''
         );
  end if;

  if exists (
    select 1
    from editorial.resource_aliases alias
    where alias.path = v_path
  ) then
    raise exception
      'Could not allocate a unique Person path.';
  end if;

  return v_path;
end;
$function$

create or replace function
  editorial.sync_person_visibility_from_identity_link()
returns trigger
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'editorial'
as $function$
begin
  if tg_op = 'DELETE' then
    perform editorial.refresh_person_visibility(
      old.person_resource_id
    );
    return old;
  end if;

  perform editorial.refresh_person_visibility(
    new.person_resource_id
  );

  if tg_op = 'UPDATE'
     and old.person_resource_id
         is distinct from new.person_resource_id
  then
    perform editorial.refresh_person_visibility(
      old.person_resource_id
    );
  end if;

  return new;
end;
$function$

create or replace function
  public.get_public_person(
    p_slug text
  )
returns jsonb
language plpgsql
stable
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_input text;
  v_path text;
  v_requested_person_id uuid;
  v_person_id uuid;
  v_person editorial.people%rowtype;
  v_resource editorial.resources%rowtype;
  v_presentation jsonb;
  v_canonical_path text;
  v_depth integer := 0;
begin
  v_input := lower(
    btrim(
      coalesce(
        p_slug,
        ''
      )
    )
  );

  if v_input = '' then
    return null;
  end if;

  if v_input like '/people/%' then
    v_path := regexp_replace(
      v_input,
      '/+$',
      ''
    );
  else
    v_input := trim(
      both '/'
      from v_input
    );

    if v_input = '' then
      return null;
    end if;

    v_path :=
      '/people/'
      || v_input;
  end if;

  select alias.resource_id
  into v_requested_person_id
  from editorial.resource_aliases alias
  join editorial.resources resource
    on resource.id = alias.resource_id
   and resource.resource_kind = 'person'
  where alias.path = v_path
    and alias.retired_at is null
  order by
    alias.is_canonical desc,
    alias.created_at
  limit 1;

  if not found then
    return null;
  end if;

  v_person_id :=
    v_requested_person_id;

  loop
    v_depth := v_depth + 1;

    if v_depth > 8 then
      return null;
    end if;

    select person.*
    into v_person
    from editorial.people person
    where person.resource_id =
          v_person_id;

    if not found then
      return null;
    end if;

    exit when
      v_person.person_state <> 'merged';

    if v_person.merged_into_person_resource_id
         is null
    then
      return null;
    end if;

    v_person_id :=
      v_person.merged_into_person_resource_id;
  end loop;

  if v_person.person_state <> 'active' then
    return null;
  end if;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id = v_person_id
    and resource.resource_kind = 'person';

  if not found
     or v_resource.visibility <> 'public'
     or v_resource.lifecycle_state <> 'active'
  then
    return null;
  end if;

  v_presentation :=
    editorial.resolve_person_presentation(
      v_person_id
    );

  if v_presentation is null then
    return null;
  end if;

  select alias.path
  into v_canonical_path
  from editorial.resource_aliases alias
  where alias.resource_id = v_person_id
    and alias.is_canonical
    and alias.retired_at is null;

  if v_canonical_path is null then
    return null;
  end if;

  return jsonb_strip_nulls(
    jsonb_build_object(
      'person_id',
        v_person_id,
      'canonical_path',
        v_canonical_path,
      'display_name',
        v_presentation ->> 'display_name',
      'bio',
        v_presentation ->> 'bio',
      'avatar_url',
        v_presentation ->> 'avatar_url',
      'cover_url',
        v_presentation ->> 'cover_url',
      'location',
        v_presentation ->> 'location',
      'username',
        v_presentation ->> 'username',
      'registry_author_slug',
        v_presentation
          ->> 'registry_author_slug',
      'redirect_to',
        case
          when v_requested_person_id
                 is distinct from v_person_id
            then v_canonical_path
          else null
        end
    )
  );
end;
$function$

do $people_migration_a_postconditions$
declare
  v_binding_definition text;
  v_public_definition text;
  v_presentation_definition text;
begin
  select pg_get_functiondef(
    'editorial.assert_resource_binding_integrity()'::regprocedure
  )
  into v_binding_definition;

  if position(
       'when ''person'''
       in lower(v_binding_definition)
     ) = 0
  then
    raise exception
      'STOP: Person Resource binding integrity was not installed';
  end if;

  select pg_get_functiondef(
    'public.get_public_person(text)'::regprocedure
  )
  into v_public_definition;

  if position(
       'follower_count'
       in lower(v_public_definition)
     ) > 0
     or position(
          'public_roles'
          in lower(v_public_definition)
        ) > 0
     or position(
          'contact_email'
          in lower(v_public_definition)
        ) > 0
     or position(
          'contact_phone'
          in lower(v_public_definition)
        ) > 0
     or position(
          'internal_notes'
          in lower(v_public_definition)
        ) > 0
  then
    raise exception
      'STOP: Migration A Person read exposes deferred social/body-of-work or private contributor data';
  end if;

  select pg_get_functiondef(
    'editorial.resolve_person_presentation(uuid)'::regprocedure
  )
  into v_presentation_definition;

  if position(
       'contact_email'
       in lower(v_presentation_definition)
     ) > 0
     or position(
          'contact_phone'
          in lower(v_presentation_definition)
        ) > 0
     or position(
          'internal_notes'
          in lower(v_presentation_definition)
        ) > 0
     or position(
          'profile.email'
          in lower(v_presentation_definition)
        ) > 0
  then
    raise exception
      'STOP: Person presentation resolver exposes private identity data';
  end if;

  if exists (
    select 1
    from information_schema.role_table_grants grant_row
    where grant_row.table_schema = 'editorial'
      and grant_row.table_name in (
        'people',
        'person_identity_links',
        'person_identity_events'
      )
      and lower(grant_row.grantee) in (
        'public',
        'anon',
        'authenticated'
      )
  ) then
    raise exception
      'STOP: Internal Person governance tables are directly granted to browser roles';
  end if;

  if has_function_privilege(
       'anon',
       'editorial.create_person_for_identity(uuid,uuid,uuid,text,text)',
       'EXECUTE'
     )
     or has_function_privilege(
          'authenticated',
          'editorial.create_person_for_identity(uuid,uuid,uuid,text,text)',
          'EXECUTE'
        )
     or has_function_privilege(
          'service_role',
          'editorial.ensure_person_for_user(uuid)',
          'EXECUTE'
        )
     or has_function_privilege(
          'service_role',
          'editorial.ensure_person_for_registry_author(uuid)',
          'EXECUTE'
        )
     or has_function_privilege(
          'service_role',
          'editorial.ensure_person_for_external_contributor(uuid)',
          'EXECUTE'
        )
     or has_function_privilege(
          'anon',
          'editorial.resolve_person_presentation(uuid)',
          'EXECUTE'
        )
     or has_function_privilege(
          'authenticated',
          'editorial.resolve_person_presentation(uuid)',
          'EXECUTE'
        )
  then
    raise exception
      'STOP: Migration A exposes Person provisioning authority before Migration C';
  end if;
end;
$people_migration_a_postconditions$

-- People / Contributor Identity Migration B:
-- governed reconciliation, merge continuity, and current-public body of work.
--
-- This migration:
-- 1. adds least-privilege People identity capabilities;
-- 2. registers durable link, unlink, and merge Resource commands;
-- 3. adds append-only Person Follow merge-transfer history;
-- 4. adds schema-level merge-cycle protection;
-- 5. adds governed identity link, unlink, and merge commands;
-- 6. resolves immutable Shared Credits to stable Person identity;
-- 7. exposes current-public Article and Playlist body of work;
-- 8. extends public Person presentation with Shared Credit roles.
--
-- This migration does not:
-- - enable public Person Follow;
-- - expose follower counts or follower identities;
-- - create a Person split command;
-- - bulk backfill People;
-- - bulk backfill Article or Playlist Resource aliases;
-- - mutate historical Credits;
-- - change frontend routes;
-- - add Guide body-of-work authority.

begin

do $people_migration_b_preflight$
declare
  v_required_function text;
  v_required_table text;
begin
  foreach v_required_table in array array[
    'editorial.people',
    'editorial.person_identity_links',
    'editorial.person_identity_events',
    'editorial.resources',
    'editorial.resource_aliases',
    'editorial.resource_credits',
    'editorial.credits',
    'editorial.credit_governance',
    'editorial.article_versions',
    'editorial.playlist_resources',
    'editorial.playlist_publication_snapshots',
    'editorial.external_contributors',
    'public.user_profiles',
    'public.registry_authors',
    'public.community_follows',
    'public.capability_definitions',
    'public.role_capabilities',
    'public.role_definitions',
    'platform_private.command_types',
    'platform_private.command_receipts',
    'platform_private.outbox_events'
  ]
  loop
    if to_regclass(v_required_table) is null then
      raise exception
        'STOP: Required Migration B authority is missing: %',
        v_required_table;
    end if;
  end loop;

  foreach v_required_function in array array[
    'public.current_user_has_capability(text)',
    'public.get_public_person(text)',
    'public.community_get_user_follows(uuid)',
    'editorial.refresh_person_visibility(uuid)',
    'editorial.resolve_person_presentation(uuid)',
    'platform_private.begin_authenticated_resource_command(text,uuid,text,jsonb)',
    'platform_private.read_authenticated_resource_command_result(uuid,boolean)',
    'platform_private.complete_resource_command(uuid,jsonb)',
    'platform_private.reject_resource_command(uuid,text,text,jsonb)'
  ]
  loop
    if to_regprocedure(v_required_function) is null then
      raise exception
        'STOP: Required Migration B function is missing: %',
        v_required_function;
    end if;
  end loop;

  if to_regclass(
       'editorial.person_follow_merge_transfers'
     ) is not null
  then
    raise exception
      'STOP: Person Follow merge-transfer history already exists';
  end if;

  if exists (
    select 1
    from public.capability_definitions
    where capability_key in (
      'view_people_identity',
      'manage_people_identity',
      'merge_people_identity'
    )
  ) then
    raise exception
      'STOP: One or more Migration B People capabilities already exist';
  end if;

  if exists (
    select 1
    from platform_private.command_types
    where command_type in (
      'person.identity_link',
      'person.identity_unlink',
      'person.merge',
      'person.split'
    )
  ) then
    raise exception
      'STOP: One or more Migration B Person commands already exist';
  end if;

  if to_regprocedure(
       'editorial.resolve_credit_person(uuid)'
     ) is not null
     or to_regprocedure(
          'editorial.list_current_public_person_work(uuid)'
        ) is not null
     or to_regprocedure(
          'public.list_public_person_work(uuid,integer,timestamp with time zone,uuid)'
        ) is not null
     or to_regprocedure(
          'public.link_person_identity(uuid,bigint,uuid,uuid,uuid,text,text,text,uuid)'
        ) is not null
     or to_regprocedure(
          'public.unlink_person_identity(uuid,bigint,uuid,text,text,uuid)'
        ) is not null
     or to_regprocedure(
          'public.merge_people(uuid,uuid,bigint,bigint,text,text,uuid)'
        ) is not null
  then
    raise exception
      'STOP: One or more Migration B functions already exist';
  end if;

  if exists (
    select 1
    from (
      values
        ('administrator'),
        ('editor'),
        ('registry_editor')
    ) required(role_key)
    where not exists (
      select 1
      from public.role_definitions definition
      where definition.role_key = required.role_key
    )
  ) then
    raise exception
      'STOP: One or more required People role definitions are missing';
  end if;

  if not exists (
    select 1
    from pg_indexes
    where schemaname = 'editorial'
      and tablename = 'person_identity_links'
      and indexname =
        'person_identity_links_active_user_unique'
  )
     or not exists (
       select 1
       from pg_indexes
       where schemaname = 'editorial'
         and tablename = 'person_identity_links'
         and indexname =
           'person_identity_links_active_registry_author_unique'
     )
     or not exists (
       select 1
       from pg_indexes
       where schemaname = 'editorial'
         and tablename = 'person_identity_links'
         and indexname =
           'person_identity_links_active_external_contributor_unique'
     )
  then
    raise exception
      'STOP: Migration A active-source uniqueness authority is missing';
  end if;
end;
