create or replace function
  editorial.assert_person_merge_cycle_integrity()
returns trigger
language plpgsql
set search_path to 'pg_catalog', 'editorial'
as $function$
declare
  v_next uuid;
  v_seen uuid[];
  v_depth integer;
begin
  if new.person_state <> 'merged' then
    return null;
  end if;

  v_next :=
    new.merged_into_person_resource_id;
  v_seen :=
    array[new.resource_id];

  for v_depth in 1..64
  loop
    if v_next is null then
      return null;
    end if;

    if v_next = any(v_seen) then
      raise exception
        'Person merge cycle is not permitted.';
    end if;

    v_seen :=
      array_append(
        v_seen,
        v_next
      );

    select
      case
        when person.person_state = 'merged'
          then person.merged_into_person_resource_id
        else null
      end
    into v_next
    from editorial.people person
    where person.resource_id =
          v_next;

    if not found then
      return null;
    end if;
  end loop;

  raise exception
    'Person merge chain exceeds the supported safety depth.';
end;
$function$

create or replace function
  public.get_public_person(
    p_slug text
  )
returns jsonb
language plpgsql
stable
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_input text;
  v_path text;
  v_requested_person_id uuid;
  v_person_id uuid;
  v_person editorial.people%rowtype;
  v_resource editorial.resources%rowtype;
  v_presentation jsonb;
  v_canonical_path text;
  v_public_roles jsonb;
  v_depth integer := 0;
begin
  v_input :=
    lower(
      btrim(
        coalesce(
          p_slug,
          ''
        )
      )
    );

  if v_input = '' then
    return null;
  end if;

  if v_input like '/people/%' then
    v_path :=
      regexp_replace(
        v_input,
        '/+$',
        ''
      );
  else
    v_input :=
      trim(
        both '/'
        from v_input
      );

    if v_input = '' then
      return null;
    end if;

    v_path :=
      '/people/' ||
      v_input;
  end if;

  select alias.resource_id
  into v_requested_person_id
  from editorial.resource_aliases alias
  join editorial.resources resource
    on resource.id =
       alias.resource_id
   and resource.resource_kind =
       'person'
  where alias.path =
        v_path
    and alias.retired_at is null
  order by
    alias.is_canonical desc,
    alias.created_at
  limit 1;

  if not found then
    return null;
  end if;

  v_person_id :=
    v_requested_person_id;

  loop
    v_depth :=
      v_depth + 1;

    if v_depth > 8 then
      return null;
    end if;

    select person.*
    into v_person
    from editorial.people person
    where person.resource_id =
          v_person_id;

    if not found then
      return null;
    end if;

    exit when
      v_person.person_state <>
      'merged';

    if v_person.merged_into_person_resource_id
         is null
    then
      return null;
    end if;

    v_person_id :=
      v_person.merged_into_person_resource_id;
  end loop;

  if v_person.person_state <> 'active' then
    return null;
  end if;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id =
        v_person_id
    and resource.resource_kind =
        'person';

  if not found
     or v_resource.visibility <>
        'public'
     or v_resource.lifecycle_state <>
        'active'
  then
    return null;
  end if;

  v_presentation :=
    editorial.resolve_person_presentation(
      v_person_id
    );

  if v_presentation is null then
    return null;
  end if;

  select alias.path
  into v_canonical_path
  from editorial.resource_aliases alias
  where alias.resource_id =
        v_person_id
    and alias.is_canonical
    and alias.retired_at is null;

  if v_canonical_path is null then
    return null;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'role',
          role_summary.role_key,
        'label',
          role_summary.role_label
      )
      order by
        role_summary.first_display_order,
        role_summary.role_key
    ),
    '[]'::jsonb
  )
  into v_public_roles
  from (
    select
      role_item ->> 'role'
        as role_key,
      (
        array_agg(
          coalesce(
            nullif(
              btrim(
                role_item
                  ->> 'role_label'
              ),
              ''
            ),
            role_item ->> 'role'
          )
          order by
            (
              role_item
                ->> 'display_order'
            )::integer,
            coalesce(
              nullif(
                btrim(
                  role_item
                    ->> 'role_label'
                ),
                ''
              ),
              role_item ->> 'role'
            )
        )
      )[1] as role_label,
      min(
        (
          role_item
            ->> 'display_order'
        )::integer
      ) as first_display_order
    from editorial.list_current_public_person_work(
      v_person_id
    ) work
    cross join lateral
      jsonb_array_elements(
        work.roles
      ) role_item
    group by
      role_item ->> 'role'
  ) role_summary;

  return jsonb_strip_nulls(
    jsonb_build_object(
      'person_id',
        v_person_id,
      'canonical_path',
        v_canonical_path,
      'display_name',
        v_presentation
          ->> 'display_name',
      'bio',
        v_presentation
          ->> 'bio',
      'avatar_url',
        v_presentation
          ->> 'avatar_url',
      'cover_url',
        v_presentation
          ->> 'cover_url',
      'location',
        v_presentation
          ->> 'location',
      'username',
        v_presentation
          ->> 'username',
      'registry_author_slug',
        v_presentation
          ->> 'registry_author_slug',
      'public_roles',
        v_public_roles,
      'redirect_to',
        case
          when v_requested_person_id
                 is distinct from
               v_person_id
            then v_canonical_path
          else null
        end
    )
  );
end;
$function$

