do $people_migration_c_backfill$
declare
  v_people_before integer;
  v_links_before integer;
  v_nonperson_follow_hash_before text;
  v_nonperson_follow_hash_after text;
  v_profile record;
  v_author record;
  v_contributor record;
begin
  select count(*)
  into v_people_before
  from editorial.people;

  select count(*)
  into v_links_before
  from editorial.person_identity_links;

  select md5(
    coalesce(
      jsonb_agg(
        to_jsonb(follow_row)
        order by follow_row.id
      )::text,
      '[]'
    )
  )
  into v_nonperson_follow_hash_before
  from public.community_follows follow_row
  where follow_row.target_type <>
        'person';

  if v_people_before <> 3
     or v_links_before <> 3
  then
    raise exception
      'STOP: Migration C adoption no longer starts from 3 People / 3 identity links';
  end if;

  if (
    select count(*)
    from public.user_profiles profile
    left join editorial.person_identity_links link
      on link.user_id = profile.user_id
     and link.link_state = 'active'
    where link.id is null
  ) <> 10
  then
    raise exception
      'STOP: Migration C account adoption count changed before backfill';
  end if;

  if (
    select count(*)
    from public.registry_authors author
    left join editorial.person_identity_links link
      on link.registry_author_id = author.id
     and link.link_state = 'active'
    where link.id is null
  ) <> 12
  then
    raise exception
      'STOP: Migration C Registry Author adoption count changed before backfill';
  end if;

  if (
    select count(*)
    from editorial.external_contributors contributor
    left join editorial.person_identity_links link
      on link.external_contributor_id = contributor.id
     and link.link_state = 'active'
    where link.id is null
  ) <> 0
  then
    raise exception
      'STOP: Migration C external-contributor adoption count changed before backfill';
  end if;

  for v_profile in
    select profile.user_id
    from public.user_profiles profile
    left join editorial.person_identity_links link
      on link.user_id = profile.user_id
     and link.link_state = 'active'
    where link.id is null
    order by profile.user_id
  loop
    perform editorial.ensure_person_for_user(
      v_profile.user_id
    );
  end loop;

  for v_author in
    select author.id
    from public.registry_authors author
    left join editorial.person_identity_links link
      on link.registry_author_id = author.id
     and link.link_state = 'active'
    where link.id is null
    order by author.id
  loop
    perform editorial.ensure_person_for_registry_author(
      v_author.id
    );
  end loop;

  for v_contributor in
    select contributor.id
    from editorial.external_contributors contributor
    left join editorial.person_identity_links link
      on link.external_contributor_id = contributor.id
     and link.link_state = 'active'
    where link.id is null
    order by contributor.id
  loop
    perform editorial.ensure_person_for_external_contributor(
      v_contributor.id
    );
  end loop;

  if exists (
    select 1
    from public.user_profiles profile
    left join editorial.person_identity_links link
      on link.user_id = profile.user_id
     and link.link_state = 'active'
    where link.id is null
  )
     or exists (
       select 1
       from public.registry_authors author
       left join editorial.person_identity_links link
         on link.registry_author_id = author.id
        and link.link_state = 'active'
       where link.id is null
     )
     or exists (
       select 1
       from editorial.external_contributors contributor
       left join editorial.person_identity_links link
         on link.external_contributor_id = contributor.id
        and link.link_state = 'active'
       where link.id is null
     )
  then
    raise exception
      'STOP: Migration C did not complete exact-source Person adoption';
  end if;

  if (
    select count(*)
    from editorial.people
  ) <> 25
     or (
       select count(*)
       from editorial.person_identity_links
       where link_state = 'active'
     ) <> 25
  then
    raise exception
      'STOP: Migration C source adoption did not reconcile to 25 People / 25 active links';
  end if;

  if exists (
    select 1
    from public.community_follows
    where target_type = 'person'
  ) then
    raise exception
      'STOP: Migration C source adoption created Person Follow rows';
  end if;

  select md5(
    coalesce(
      jsonb_agg(
        to_jsonb(follow_row)
        order by follow_row.id
      )::text,
      '[]'
    )
  )
  into v_nonperson_follow_hash_after
  from public.community_follows follow_row
  where follow_row.target_type <>
        'person';

  if v_nonperson_follow_hash_after <>
     v_nonperson_follow_hash_before
  then
    raise exception
      'STOP: Migration C changed existing non-Person Follow authority';
  end if;
end;
$people_migration_c_backfill$

-- People frontend M1 support:
-- reconcile the 24 explicitly reviewed Hafare Segelan legacy Article bylines
-- into governed Shared Credit authority on their exact current published versions.
--
-- This migration is deliberately narrow:
-- - exact audited Article, Resource, and current-version ids only;
-- - one Registry Author identity only;
-- - no Article content, byline, lifecycle, ownership, or publication mutation;
-- - no broad author-name matching outside the locked manifest.

begin

do $hafare_credit_reconciliation_preflight$
declare
  v_count bigint;
  v_existing_credit_count bigint;
begin
  if (select count(*) from pg_temp.hafare_article_credit_manifest) <> 24 then
    raise exception
      'STOP: Hafare Article Credit manifest is not exactly 24 rows';
  end if;

  if not exists (
    select 1
    from public.registry_authors author_record
    where author_record.id =
          'c318a8c5-3ad8-4adc-9991-953ab24e7da6'::uuid
      and author_record.slug = 'hafare-segelan'
      and author_record.name = 'Hafare Segelan'
  ) then
    raise exception
      'STOP: Hafare Registry Author identity moved';
  end if;

  if not exists (
    select 1
    from editorial.person_identity_links link
    where link.person_resource_id =
          'd87022ed-5e25-4301-bb89-b059ca39cf0f'::uuid
      and link.registry_author_id =
          'c318a8c5-3ad8-4adc-9991-953ab24e7da6'::uuid
      and link.link_state = 'active'
  ) then
    raise exception
      'STOP: Hafare Registry Author is not actively linked to the accepted Person';
  end if;

  select count(*)
  into v_count
  from pg_temp.hafare_article_credit_manifest manifest
  join public.wk_articles article
    on article.id = manifest.article_id
   and article.slug = manifest.slug
   and btrim(coalesce(to_jsonb(article)->>'author', '')) =
       'Hafare Segelan'
  join editorial.article_resources binding
    on binding.article_id = manifest.article_id
   and binding.resource_id = manifest.resource_id
  join editorial.resources resource
    on resource.id = manifest.resource_id
   and resource.resource_kind = 'article'
   and resource.current_published_version_id =
       manifest.article_version_id
   and resource.visibility = 'public'
   and resource.lifecycle_state = 'published'
  join editorial.article_versions version
    on version.id = manifest.article_version_id
   and version.resource_id = manifest.resource_id
   and version.published_at is not null;

  if v_count <> 24 then
    raise exception
      'STOP: Only % of 24 locked Hafare Article/version rows still match the audited public boundary',
      v_count;
  end if;

  if exists (
    select 1
    from editorial.resource_credits attachment
    join pg_temp.hafare_article_credit_manifest manifest
      on manifest.article_version_id =
         attachment.target_version_id
  ) then
    raise exception
      'STOP: One or more locked Hafare current Article versions acquired Credits after audit';
  end if;

  select count(*)
  into v_existing_credit_count
  from editorial.credits credit
  join editorial.credit_governance governance
    on governance.credit_id = credit.id
  where credit.credit_role = 'author'
    and credit.registry_author_id =
        'c318a8c5-3ad8-4adc-9991-953ab24e7da6'::uuid
    and credit.display_name_snapshot = 'Hafare Segelan'
    and credit.registry_author_slug_snapshot = 'hafare-segelan'
    and governance.credit_state = 'active'
    and governance.public_safe;

  if v_existing_credit_count > 1 then
    raise exception
      'STOP: More than one active public Hafare author Credit already exists';
  end if;

  if (
    select count(*)
    from public.list_public_person_work(
      'd87022ed-5e25-4301-bb89-b059ca39cf0f'::uuid,
      50,
      null,
      null
    )
    where resource_kind = 'article'
  ) <> 0 then
    raise exception
      'STOP: Hafare already has governed public Article work before reconciliation';
  end if;

  if (
    select count(*)
    from public.list_public_person_work(
      'd87022ed-5e25-4301-bb89-b059ca39cf0f'::uuid,
      50,
      null,
      null
    )
    where resource_kind = 'playlist'
  ) <> 1 then
    raise exception
      'STOP: Hafare accepted Playlist body-of-work boundary moved';
  end if;
end;
$hafare_credit_reconciliation_preflight$

do $hafare_credit_reconciliation_postflight$
declare
  v_credit_id uuid;
begin
  select credit.id
  into v_credit_id
  from editorial.credits credit
  join editorial.credit_governance governance
    on governance.credit_id = credit.id
  where credit.credit_role = 'author'
    and credit.registry_author_id =
        'c318a8c5-3ad8-4adc-9991-953ab24e7da6'::uuid
    and credit.display_name_snapshot = 'Hafare Segelan'
    and credit.registry_author_slug_snapshot = 'hafare-segelan'
    and governance.credit_state = 'active'
    and governance.public_safe
  order by credit.created_at, credit.id
  limit 1;

  if v_credit_id is null then
    raise exception
      'STOP: Hafare author Credit was not established';
  end if;

  if (
    select count(*)
    from editorial.resource_credits attachment
    join pg_temp.hafare_article_credit_manifest manifest
      on manifest.article_version_id =
         attachment.target_version_id
    where attachment.resource_id = manifest.resource_id
      and attachment.resource_kind = 'article'
      and attachment.target_version_type = 'article_version'
      and attachment.credit_id = v_credit_id
      and attachment.display_order = 0
      and attachment.is_primary
      and attachment.public_safe
  ) <> 24 then
    raise exception
      'STOP: Hafare author Credit was not attached to all 24 exact Article versions';
  end if;

  if exists (
    select 1
    from pg_temp.hafare_article_credit_manifest manifest
    where (
      select count(*)
      from editorial.resource_credits attachment
      where attachment.target_version_id =
            manifest.article_version_id
    ) <> 1
  ) then
    raise exception
      'STOP: One or more reconciled Hafare Article versions do not have exactly one Credit';
  end if;

  if (
    select count(*)
    from public.list_public_person_work(
      'd87022ed-5e25-4301-bb89-b059ca39cf0f'::uuid,
      50,
      null,
      null
    )
    where resource_kind = 'article'
  ) <> 24 then
    raise exception
      'STOP: Hafare Person body of work does not expose all 24 reconciled Articles';
  end if;

  if (
    select count(*)
    from public.list_public_person_work(
      'd87022ed-5e25-4301-bb89-b059ca39cf0f'::uuid,
      50,
      null,
      null
    )
    where resource_kind = 'playlist'
  ) <> 1 then
    raise exception
      'STOP: Hafare Playlist work changed during Article Credit reconciliation';
  end if;

  if (
    select count(*)
    from public.list_public_person_work(
      'd87022ed-5e25-4301-bb89-b059ca39cf0f'::uuid,
      50,
      null,
      null
    )
  ) <> 25 then
    raise exception
      'STOP: Hafare Person body-of-work total is not exactly 25';
  end if;

  if exists (
    select 1
    from pg_temp.hafare_article_credit_manifest manifest
    join public.wk_articles article
      on article.id = manifest.article_id
    where btrim(coalesce(to_jsonb(article)->>'author', '')) <>
          'Hafare Segelan'
  ) then
    raise exception
      'STOP: Legacy Hafare Article byline changed during reconciliation';
  end if;
end;
$hafare_credit_reconciliation_postflight$

create or replace function
  public.community_generate_username(
    p_user_id uuid,
    p_email text,
    p_display_name text default null
  )
returns text
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_base text;
  v_candidate text;
  v_suffix text;
  v_attempt integer := 0;
  v_person_resource_id uuid;
begin
  select link.person_resource_id
  into v_person_resource_id
  from editorial.person_identity_links link
  where link.user_id = p_user_id
    and link.link_state = 'active'
  limit 1;

  if v_person_resource_id is not null then
    select resolved.person_resource_id
    into v_person_resource_id
    from editorial.resolve_person_follow_target(
      v_person_resource_id
    ) resolved;
  end if;

  v_base := public.community_username_seed(
    coalesce(
      nullif(p_display_name, ''),
      nullif(split_part(coalesce(p_email, ''), '@', 1), ''),
      'user'
    )
  );

  v_candidate := v_base;

  if public.community_username_is_reserved(v_candidate)
     or exists (
       select 1
       from public.user_profiles profile
       where profile.username_normalized = v_candidate
         and profile.user_id <> p_user_id
     )
     or exists (
       select 1
       from editorial.resource_aliases alias
       where alias.path = '/people/' || v_candidate
         and (
           v_person_resource_id is null
           or alias.resource_id <> v_person_resource_id
         )
     )
  then
    v_suffix := '_' || left(
      replace(
        coalesce(p_user_id::text, gen_random_uuid()::text),
        '-',
        ''
      ),
      8
    );

    v_candidate :=
      left(v_base, 30 - length(v_suffix))
      || v_suffix;
  end if;

  while public.community_username_is_reserved(v_candidate)
     or exists (
       select 1
       from public.user_profiles profile
       where profile.username_normalized = v_candidate
         and profile.user_id <> p_user_id
     )
     or exists (
       select 1
       from editorial.resource_aliases alias
       where alias.path = '/people/' || v_candidate
         and (
           v_person_resource_id is null
           or alias.resource_id <> v_person_resource_id
         )
     )
  loop
    v_attempt := v_attempt + 1;

    v_suffix := '_' || left(
      replace(
        coalesce(p_user_id::text, gen_random_uuid()::text),
        '-',
        ''
      ),
      6
    ) || v_attempt::text;

    v_candidate :=
      left(v_base, 30 - length(v_suffix))
      || v_suffix;

    if v_attempt > 99 then
      raise exception
        'could not generate unique username for user %',
        p_user_id;
    end if;
  end loop;

  return v_candidate;
end;
$function$

create or replace function
  editorial.sync_account_person_handle(
    p_user_id uuid
  )
returns text
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_username text;
  v_person_resource_id uuid;
  v_resolved_person_resource_id uuid;
  v_desired_path text;
  v_desired_alias_id uuid;
  v_desired_alias_resource_id uuid;
  v_current_alias_id uuid;
  v_current_path text;
  v_actor_id uuid := auth.uid();
begin
  if p_user_id is null then
    raise exception
      'Account user id is required for Person handle synchronization.';
  end if;

  select profile.username_normalized
  into v_username
  from public.user_profiles profile
  where profile.user_id = p_user_id;

  if not found then
    raise exception
      'Account profile % does not exist.',
      p_user_id;
  end if;

  if v_username is null
     or not public.community_username_is_valid(v_username)
  then
    raise exception
      'Account profile % does not have a valid normalized username.',
      p_user_id;
  end if;

  select link.person_resource_id
  into v_person_resource_id
  from editorial.person_identity_links link
  where link.user_id = p_user_id
    and link.link_state = 'active'
  limit 1;

  if not found then
    return null;
  end if;

  select resolved.person_resource_id
  into v_resolved_person_resource_id
  from editorial.resolve_person_follow_target(
    v_person_resource_id
  ) resolved;

  if v_resolved_person_resource_id is null then
    raise exception
      'Linked Person % could not resolve to a stable Person survivor.',
      v_person_resource_id;
  end if;

  v_person_resource_id :=
    v_resolved_person_resource_id;

  v_desired_path :=
    '/people/' || v_username;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'person-handle-user|' || p_user_id::text,
      0
    )
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'person-path|' || v_username,
      0
    )
  );

  select
    alias.id,
    alias.resource_id
  into
    v_desired_alias_id,
    v_desired_alias_resource_id
  from editorial.resource_aliases alias
  where alias.path = v_desired_path
  for update;

  if found
     and v_desired_alias_resource_id <>
         v_person_resource_id
  then
    raise exception
      using
        errcode = '23505',
        message = format(
          'Handle %s is permanently reserved by another Person route.',
          v_username
        );
  end if;

  select
    alias.id,
    alias.path
  into
    v_current_alias_id,
    v_current_path
  from editorial.resource_aliases alias
  where alias.resource_id = v_person_resource_id
    and alias.is_canonical
    and alias.retired_at is null
  order by alias.created_at, alias.id
  limit 1
  for update;

  if not found then
    raise exception
      'Linked Person % has no active canonical route.',
      v_person_resource_id;
  end if;

  if v_current_path = v_desired_path then
    return v_desired_path;
  end if;

  if v_desired_alias_id is null then
    insert into editorial.resource_aliases (
      resource_id,
      path,
      is_canonical,
      redirect_status,
      created_by
    )
    values (
      v_person_resource_id,
      v_desired_path,
      false,
      308,
      v_actor_id
    )
    returning id
    into v_desired_alias_id;
  end if;

  update editorial.resource_aliases alias
  set
    is_canonical = false,
    redirect_status = 308,
    retired_at = now(),
    replacement_alias_id = v_desired_alias_id
  where alias.id = v_current_alias_id;

  update editorial.resource_aliases alias
  set
    is_canonical = true,
    redirect_status = 308,
    retired_at = null,
    replacement_alias_id = null
  where alias.id = v_desired_alias_id
    and alias.resource_id = v_person_resource_id;

  if not found then
    raise exception
      'Could not promote % as the canonical route for Person %.',
      v_desired_path,
      v_person_resource_id;
  end if;

  update editorial.people person
  set
    updated_by = coalesce(v_actor_id, person.updated_by),
    updated_at = now()
  where person.resource_id = v_person_resource_id;

  return v_desired_path;
end;
$function$

create or replace function
  editorial.sync_person_handle_from_user_profile()
returns trigger
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'editorial'
as $function$
begin
  if new.username_normalized is null then
    return new;
  end if;

  perform editorial.sync_account_person_handle(
    new.user_id
  );

  return new;
end;
$function$

create or replace function
  editorial.provision_person_for_user_profile_insert()
returns trigger
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_username text;
  v_email text;
  v_display_name text;
begin
  select
    profile.username_normalized,
    profile.email,
    profile.display_name
  into
    v_username,
    v_email,
    v_display_name
  from public.user_profiles profile
  where profile.user_id = new.user_id;

  if not found then
    return null;
  end if;

  if v_username is null then
    v_username :=
      public.community_generate_username(
        new.user_id,
        v_email,
        v_display_name
      );

    update public.user_profiles profile
    set
      username = v_username,
      username_normalized = v_username,
      username_updated_at =
        coalesce(
          profile.username_updated_at,
          now()
        ),
      updated_at = now()
    where profile.user_id = new.user_id;
  end if;

  perform editorial.ensure_person_for_user(
    new.user_id
  );

  perform editorial.sync_account_person_handle(
    new.user_id
  );

  return null;
end;
$function$

create or replace function
  public.community_username_available(
    p_username text
  )
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_username text;
  v_existing_user_id uuid;
  v_current_user_id uuid := auth.uid();
  v_current_person_resource_id uuid;
  v_path_holder_resource_id uuid;
begin
  v_username :=
    public.community_normalize_username(
      p_username
    );

  if v_username is null
     or not public.community_username_is_valid(
       v_username
     )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'invalid_format',
      'message', 'Use 3-30 lowercase letters, numbers, and underscores. Start and end with a letter or number.'
    );
  end if;

  if public.community_username_is_reserved(
       v_username
     )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'reserved',
      'message', 'That handle is reserved.'
    );
  end if;

  select profile.user_id
  into v_existing_user_id
  from public.user_profiles profile
  where profile.username_normalized =
        v_username;

  if found
     and v_existing_user_id = v_current_user_id
  then
    return jsonb_build_object(
      'available', true,
      'normalized', v_username,
      'reason', 'current',
      'message', 'This is your current handle.'
    );
  end if;

  if found then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'taken',
      'message', 'That handle is already taken.'
    );
  end if;

  if v_current_user_id is not null then
    select link.person_resource_id
    into v_current_person_resource_id
    from editorial.person_identity_links link
    where link.user_id = v_current_user_id
      and link.link_state = 'active'
    limit 1;

    if v_current_person_resource_id is not null then
      select resolved.person_resource_id
      into v_current_person_resource_id
      from editorial.resolve_person_follow_target(
        v_current_person_resource_id
      ) resolved;
    end if;
  end if;

  select alias.resource_id
  into v_path_holder_resource_id
  from editorial.resource_aliases alias
  where alias.path =
        '/people/' || v_username;

  if found
     and (
       v_current_person_resource_id is null
       or v_path_holder_resource_id <>
          v_current_person_resource_id
     )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'person_path_reserved',
      'message', 'That handle is permanently reserved by another Person route.'
    );
  end if;

  if exists (
    select 1
    from public.user_profile_username_history history
    where history.old_username_normalized =
          v_username
      and history.user_id <>
          coalesce(
            v_current_user_id,
            '00000000-0000-0000-0000-000000000000'::uuid
          )
      and history.created_at >
          now() - interval '30 days'
  )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'recently_released',
      'message', 'That handle was recently released and is temporarily protected.'
    );
  end if;

  return jsonb_build_object(
    'available', true,
    'normalized', v_username,
    'reason', 'available',
    'message', 'Handle available.'
  );
end;
$function$

create or replace function
  public.community_update_username(
    p_username text
  )
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_user_id uuid;
  v_username text;
  v_profile public.user_profiles%rowtype;
  v_old_username text;
  v_old_username_normalized text;
  v_is_admin boolean;
  v_person_resource_id uuid;
  v_path_holder_resource_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception
      'authentication required';
  end if;

  perform public.community_ensure_user_account(
    v_user_id
  );

  v_username :=
    public.community_normalize_username(
      p_username
    );

  if v_username is null
     or not public.community_username_is_valid(
       v_username
     )
  then
    raise exception
      'invalid handle: use 3-30 lowercase letters, numbers, and underscores; start and end with a letter or number';
  end if;

  if public.community_username_is_reserved(
       v_username
     )
  then
    raise exception
      'handle % is reserved',
      v_username;
  end if;

  v_is_admin :=
    public.current_user_is_administrator();

  select profile.*
  into v_profile
  from public.user_profiles profile
  where profile.user_id = v_user_id
  for update;

  if not found then
    raise exception
      'profile % not found',
      v_user_id;
  end if;

  if v_profile.username_normalized =
     v_username
  then
    return jsonb_build_object(
      'changed', false,
      'profile',
        public.community_profile_json(
          v_profile
        )
    );
  end if;

  if not v_is_admin
     and coalesce(
       v_profile.username_change_count,
       0
     ) > 0
     and v_profile.username_updated_at is not null
     and v_profile.username_updated_at >
         now() - interval '14 days'
  then
    raise exception
      'handle can only be changed once every 14 days';
  end if;

  if exists (
    select 1
    from public.user_profiles profile
    where profile.username_normalized =
          v_username
      and profile.user_id <> v_user_id
  )
  then
    raise exception
      'handle % is already taken',
      v_username;
  end if;

  if exists (
    select 1
    from public.user_profile_username_history history
    where history.old_username_normalized =
          v_username
      and history.user_id <> v_user_id
      and history.created_at >
          now() - interval '30 days'
  )
  then
    raise exception
      'handle % was recently released and is temporarily protected',
      v_username;
  end if;

  select link.person_resource_id
  into v_person_resource_id
  from editorial.person_identity_links link
  where link.user_id = v_user_id
    and link.link_state = 'active'
  limit 1;

  if v_person_resource_id is not null then
    select resolved.person_resource_id
    into v_person_resource_id
    from editorial.resolve_person_follow_target(
      v_person_resource_id
    ) resolved;
  end if;

  select alias.resource_id
  into v_path_holder_resource_id
  from editorial.resource_aliases alias
  where alias.path =
        '/people/' || v_username;

  if found
     and (
       v_person_resource_id is null
       or v_path_holder_resource_id <>
          v_person_resource_id
     )
  then
    raise exception
      'handle % is permanently reserved by another Person route',
      v_username;
  end if;

  v_old_username :=
    v_profile.username;
  v_old_username_normalized :=
    v_profile.username_normalized;

  update public.user_profiles profile
  set
    username = v_username,
    username_normalized = v_username,
    username_updated_at = now(),
    username_change_count =
      coalesce(
        profile.username_change_count,
        0
      ) + 1,
    updated_at = now()
  where profile.user_id = v_user_id
  returning profile.*
  into v_profile;

  insert into public.user_profile_username_history (
    user_id,
    old_username,
    old_username_normalized,
    new_username,
    new_username_normalized,
    changed_by,
    change_reason
  )
  values (
    v_user_id,
    v_old_username,
    v_old_username_normalized,
    v_profile.username,
    v_profile.username_normalized,
    v_user_id,
    'user_update'
  );

  return jsonb_build_object(
    'changed', true,
    'profile',
      public.community_profile_json(
        v_profile
      )
  );
end;
$function$

