create or replace function
  private.community_resolve_follow_target(
    p_target_type text,
    p_target_id text,
    p_target_slug text
  )
returns table(
  canonical_type text,
  canonical_id text,
  canonical_slug text,
  followable boolean
)
language plpgsql
stable
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial',
  'private'
as $function$
declare
  v_type text :=
    nullif(
      btrim(
        coalesce(
          p_target_type,
          ''
        )
      ),
      ''
    );
  v_id text :=
    nullif(
      btrim(
        coalesce(
          p_target_id,
          ''
        )
      ),
      ''
    );
  v_slug text :=
    nullif(
      btrim(
        coalesce(
          p_target_slug,
          ''
        )
      ),
      ''
    );
  v_person_id uuid;
  v_person record;
  v_status text;
begin
  if v_type not in (
    'person',
    'artist',
    'genre',
    'label',
    'chart_program'
  ) then
    raise exception
      'Unsupported Follow target type'
      using errcode = '22023';
  end if;

  if v_id is null then
    raise exception
      'Stable Follow target identity is required'
      using errcode = '22023';
  end if;

  canonical_type :=
    v_type;

  if v_type = 'person' then
    begin
      v_person_id :=
        v_id::uuid;
    exception
      when invalid_text_representation then
        raise exception
          'Person Follow target must be a UUID'
          using errcode = '22023';
    end;

    select *
    into v_person
    from editorial.resolve_person_follow_target(
      v_person_id
    );

    canonical_id :=
      v_person.person_resource_id::text;

    canonical_slug :=
      case
        when v_person.canonical_path
               ~ '^/people/[^/]+$'
          then split_part(
            v_person.canonical_path,
            '/',
            3
          )
        else null
      end;

    followable :=
      coalesce(
        v_person.followable,
        false
      );

    return next;
    return;
  end if;

  if v_type = 'artist' then
    select
      artist.id::text,
      artist.slug,
      artist.status
    into
      canonical_id,
      canonical_slug,
      v_status
    from public.registry_artists artist
    where artist.id::text =
          v_id
    limit 1;

    if canonical_id is null then
      select
        resolved.canonical_artist_id::text,
        resolved.canonical_slug,
        'active'::text
      into
        canonical_id,
        canonical_slug,
        v_status
      from public.registry_resolve_artist_slug_for_public(
        coalesce(
          v_slug,
          v_id
        )
      ) resolved
      limit 1;
    end if;

    if canonical_id is null then
      raise exception
        'Artist Follow target does not exist'
        using errcode = 'P0002';
    end if;

    followable :=
      v_status = 'active';

    return next;
    return;
  end if;

  if v_type = 'genre' then
    select
      genre.id::text,
      genre.slug,
      genre.status
    into
      canonical_id,
      canonical_slug,
      v_status
    from public.registry_genres genre
    where genre.id::text =
          v_id
       or lower(
            genre.slug
          ) =
          lower(
            coalesce(
              v_slug,
              v_id
            )
          )
    order by
      case
        when genre.id::text =
             v_id
          then 0
        else 1
      end
    limit 1;

    if canonical_id is null then
      raise exception
        'Genre Follow target does not exist'
        using errcode = 'P0002';
    end if;

    followable :=
      v_status = 'active';

    return next;
    return;
  end if;

  if v_type = 'label' then
    select
      label.id::text,
      label.slug,
      label.status
    into
      canonical_id,
      canonical_slug,
      v_status
    from public.registry_labels label
    where label.id::text =
          v_id
       or lower(
            label.slug
          ) =
          lower(
            coalesce(
              v_slug,
              v_id
            )
          )
    order by
      case
        when label.id::text =
             v_id
          then 0
        else 1
      end
    limit 1;

    if canonical_id is null then
      raise exception
        'Label Follow target does not exist'
        using errcode = 'P0002';
    end if;

    followable :=
      v_status = 'active';

    return next;
    return;
  end if;

  select
    program.id,
    program.public_slug
  into
    canonical_id,
    canonical_slug
  from public.wk_chart_programs_v2 program
  where program.id =
        v_id
     or lower(
          program.public_slug
        ) =
        lower(
          coalesce(
            v_slug,
            v_id
          )
        )
  order by
    case
      when program.id =
           v_id
        then 0
      else 1
    end
  limit 1;

  if canonical_id is null then
    raise exception
      'Chart programme Follow target does not exist'
      using errcode = 'P0002';
  end if;

  followable :=
    true;

  return next;
end;
$function$

create or replace function
  public.community_follow_target(
    p_target_type text,
    p_target_id text,
    p_target_slug text default null
  )
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'private'
as $function$
declare
  v_user_id uuid :=
    auth.uid();
  v_target record;
  v_current boolean;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  select *
  into v_target
  from private.community_resolve_follow_target(
    p_target_type,
    p_target_id,
    p_target_slug
  );

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|follow|'
      || v_target.canonical_type
      || '|'
      || v_target.canonical_id,
      0
    )
  );

  select exists (
    select 1
    from public.community_follows follow
    where follow.user_id =
          v_user_id
      and follow.target_type =
          v_target.canonical_type
      and follow.target_id =
          v_target.canonical_id
  )
  into v_current;

  return public.community_set_follow_state(
    v_target.canonical_type,
    v_target.canonical_id,
    v_target.canonical_slug,
    not v_current
  );
end;
$function$

do $following_person_artist_feed_m3_preflight$
declare
  v_definition text;
begin
  if to_regclass(
       'public.community_follows'
     ) is null
     or to_regclass(
       'public.registry_artists'
     ) is null
     or to_regclass(
       'public.registry_releases'
     ) is null
     or to_regclass(
       'public.registry_release_artists'
     ) is null
     or to_regclass(
       'private.phase_0a_rpc_classification'
     ) is null
  then
    raise exception
      'STOP: Required Person/Artist Following feed source authority is missing';
  end if;

  if to_regprocedure(
       'private.community_resolve_follow_target(text,text,text)'
     ) is null
     or to_regprocedure(
       'public.community_get_user_follows(uuid)'
     ) is null
     or to_regprocedure(
       'editorial.list_current_public_person_work(uuid)'
     ) is null
  then
    raise exception
      'STOP: Follow M1 / Person current-public work authority is incomplete';
  end if;

  if to_regprocedure(
       'public.community_get_following_feed(integer,timestamp with time zone,text)'
     ) is not null
  then
    raise exception
      'STOP: Following feed read authority already exists';
  end if;

  if exists (
    select 1
    from private.phase_0a_rpc_classification
    where function_signature =
          'community_get_following_feed(integer,timestamp with time zone,text)'
  ) then
    raise exception
      'STOP: Following feed RPC classification already exists';
  end if;

  if has_table_privilege(
       'anon',
       'public.community_follows',
       'SELECT'
     )
     or has_table_privilege(
       'authenticated',
       'public.community_follows',
       'SELECT'
     )
  then
    raise exception
      'STOP: Browser role gained direct Follow-table read access before M3';
  end if;

  v_definition :=
    pg_get_functiondef(
      'public.community_get_user_follows(uuid)'::regprocedure
    );

  if position(
       'auth.uid()'
       in v_definition
     ) = 0
  then
    raise exception
      'STOP: Existing self-only Follow reader no longer binds to auth.uid()';
  end if;
end;
$following_person_artist_feed_m3_preflight$

do $following_person_artist_feed_m3_postflight$
declare
  v_definition text;
begin
  if to_regprocedure(
       'public.community_get_following_feed(integer,timestamp with time zone,text)'
     ) is null
  then
    raise exception
      'FAIL: Person/Artist Following feed read authority was not created';
  end if;

  if has_function_privilege(
       'anon',
       'public.community_get_following_feed(integer,timestamp with time zone,text)',
       'EXECUTE'
     )
     or not has_function_privilege(
       'authenticated',
       'public.community_get_following_feed(integer,timestamp with time zone,text)',
       'EXECUTE'
     )
  then
    raise exception
      'FAIL: Following feed execute privileges are incorrect';
  end if;

