create or replace function
  public.community_admin_set_registry_onboarding_artists(
    p_artist_slugs text[],
    p_fallback_enabled boolean default true
  )
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'private'
as $function$
declare
  v_artist_slugs text[] :=
    coalesce(
      p_artist_slugs,
      array[]::text[]
    );

  v_count integer :=
    cardinality(
      coalesce(
        p_artist_slugs,
        array[]::text[]
      )
    );

  v_resolved_count integer;
begin
  if auth.uid() is null
     or not public.current_user_is_administrator()
  then
    raise exception
      'Administrator access required'
      using errcode = '42501';
  end if;

  if v_count > 24
  then
    raise exception
      'Onboarding opening field supports at most 24 Artists'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(
      v_artist_slugs
    ) requested(
      slug
    )
    where nullif(
            btrim(
              requested.slug
            ),
            ''
          ) is null
  ) then
    raise exception
      'Artist slugs must be non-empty'
      using errcode = '22023';
  end if;

  if (
    select
      count(*)
    from unnest(
      v_artist_slugs
    ) requested(
      slug
    )
  ) <>
  (
    select
      count(
        distinct btrim(
          requested.slug
        )
      )
    from unnest(
      v_artist_slugs
    ) requested(
      slug
    )
  ) then
    raise exception
      'Onboarding opening field cannot contain duplicate Artists'
      using errcode = '22023';
  end if;

  select
    count(*)
  into
    v_resolved_count
  from public.registry_artists
    artist
  where artist.status =
        'active'
    and nullif(
          btrim(
            coalesce(
              artist.display_name,
              ''
            )
          ),
          ''
        ) is not null
    and nullif(
          btrim(
            coalesce(
              artist.public_image_url,
              ''
            )
          ),
          ''
        ) is not null
    and artist.slug = any (
      select
        btrim(
          requested.slug
        )
      from unnest(
        v_artist_slugs
      ) requested(
        slug
      )
    );

  if v_resolved_count <>
     v_count
  then
    raise exception
      'Every onboarding Artist must resolve to one active Registry Artist'
      using errcode = '22023';
  end if;

  delete from
    private.registry_onboarding_editorial_artists;

  insert into
    private.registry_onboarding_editorial_artists (
      artist_id,
      display_order,
      created_by
    )
  select
    artist.id,
    requested.ordinality::integer - 1,
    auth.uid()
  from unnest(
    v_artist_slugs
  ) with ordinality
    requested(
      slug,
      ordinality
    )
  join public.registry_artists
    artist
    on artist.slug =
       btrim(
         requested.slug
       )
   and artist.status =
       'active'
   and nullif(
         btrim(
           coalesce(
             artist.display_name,
             ''
           )
         ),
         ''
       ) is not null
   and nullif(
         btrim(
           coalesce(
             artist.public_image_url,
             ''
           )
         ),
         ''
       ) is not null
  order by
    requested.ordinality;

  insert into
    private.registry_onboarding_config (
      config_key,
      fallback_enabled,
      updated_by,
      created_at,
      updated_at
    )
  values (
    'default',
    coalesce(
      p_fallback_enabled,
      true
    ),
    auth.uid(),
    now(),
    now()
  )
  on conflict (
    config_key
  )
  do update
  set
    fallback_enabled =
      excluded.fallback_enabled,
    updated_by =
      excluded.updated_by,
    updated_at =
      now();

  return jsonb_build_object(
    'updated',
      true,
    'artist_count',
      v_count,
    'fallback_enabled',
      coalesce(
        p_fallback_enabled,
        true
      )
  );
end;
