create or replace function public.community_submit_artist_claim(
  p_artist_id uuid,
  p_claimant_role text,
  p_statement text,
  p_evidence jsonb default '[]'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_actor uuid := auth.uid();
  v_role text :=
    lower(
      trim(
        coalesce(
          p_claimant_role,
          ''
        )
      )
    );
  v_statement text :=
    trim(
      coalesce(
        p_statement,
        ''
      )
    );
  v_claim_id uuid;
  v_evidence jsonb;
  v_type text;
  v_reference text;
  v_note text;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if not exists (
    select 1
    from public.registry_artists artist
    where artist.id = p_artist_id
      and artist.status = 'active'
  ) then
    raise exception
      'artist_not_claimable';
  end if;

  if v_role not in (
    'artist',
    'manager',
    'label',
    'publicist',
    'team_member',
    'other'
  ) then
    raise exception
      'invalid_claimant_role';
  end if;

  if char_length(v_statement) < 10
     or char_length(v_statement) > 4000
  then
    raise exception
      'invalid_claim_statement';
  end if;

  if coalesce(
       jsonb_typeof(
         p_evidence
       ),
       'null'
     ) <> 'array'
  then
    raise exception
      'claim_evidence_must_be_array';
  end if;

  if jsonb_array_length(
       p_evidence
     ) > 10
  then
    raise exception
      'too_many_claim_evidence_items';
  end if;

  if exists (
    select 1
    from public.artist_representations representation
    where representation.artist_id = p_artist_id
      and representation.user_id = v_actor
      and representation.status in (
        'pending',
        'active'
      )
  ) then
    raise exception
      'representation_already_exists';
  end if;

  if exists (
    select 1
    from public.artist_claim_requests claim
    where claim.artist_id = p_artist_id
      and claim.claimant_user_id = v_actor
      and claim.status = 'pending'
  ) then
    raise exception
      'claim_already_pending';
  end if;

  insert into public.artist_claim_requests (
    artist_id,
    claimant_user_id,
    claimant_role,
    statement
  )
  values (
    p_artist_id,
    v_actor,
    v_role,
    v_statement
  )
  returning id
  into v_claim_id;

  for v_evidence
  in
    select value
    from jsonb_array_elements(
      p_evidence
    )
  loop
    v_type :=
      lower(
        trim(
          coalesce(
            v_evidence->>'type',
            ''
          )
        )
      );

    v_reference :=
      nullif(
        trim(
          coalesce(
            v_evidence->>'reference',
            ''
          )
        ),
        ''
      );

    v_note :=
      nullif(
        trim(
          coalesce(
            v_evidence->>'note',
            ''
          )
        ),
        ''
      );

    if v_type not in (
      'official_website',
      'official_social',
      'business_email',
      'label_or_distributor',
      'public_announcement',
      'other'
    ) then
      raise exception
        'invalid_claim_evidence_type';
    end if;

    if v_reference is null
       and v_note is null
    then
      raise exception
        'claim_evidence_requires_content';
    end if;

    if v_reference is not null
       and char_length(
         v_reference
       ) > 2048
    then
      raise exception
        'claim_evidence_reference_too_long';
    end if;

    if v_note is not null
       and char_length(
         v_note
       ) > 2000
    then
      raise exception
        'claim_evidence_note_too_long';
    end if;

    insert into public.artist_claim_evidence (
      claim_id,
      evidence_type,
      reference,
      note
    )
    values (
      v_claim_id,
      v_type,
      v_reference,
      v_note
    );
  end loop;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'claim_submitted',
    v_claim_id,
    null,
    v_actor,
    jsonb_build_object(
      'claimant_role',
      v_role
    )
  );

  perform editorial.sync_artist_portal_roles(
    v_actor
  );

  return jsonb_build_object(
    'claim_id',
      v_claim_id,
    'artist_id',
      p_artist_id,
    'status',
      'pending',
    'claimant_role',
      v_role
  );
end;
$function$

create or replace function public.community_withdraw_artist_claim(
  p_claim_id uuid,
  p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_actor uuid := auth.uid();
  v_claim public.artist_claim_requests%rowtype;
  v_reason text :=
    nullif(
      trim(
        coalesce(
          p_reason,
          ''
        )
      ),
      ''
    );
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  select *
  into v_claim
  from public.artist_claim_requests
  where id = p_claim_id
  for update;

  if not found
     or v_claim.claimant_user_id
        is distinct from v_actor
  then
    raise exception
      'claim_not_found';
  end if;

  if v_claim.status <> 'pending' then
    raise exception
      'claim_not_pending';
  end if;

  update public.artist_claim_requests
  set
    status = 'withdrawn',
    decision_reason =
      coalesce(
        v_reason,
        'Withdrawn by claimant'
      ),
    updated_at = now()
  where id = p_claim_id;

  perform editorial.record_artist_representation_event(
    v_claim.artist_id,
    'claim_withdrawn',
    v_claim.id,
    null,
    v_actor,
    jsonb_build_object(
      'reason',
      coalesce(
        v_reason,
        'Withdrawn by claimant'
      )
    )
  );

  perform editorial.sync_artist_portal_roles(
    v_actor
  );

  return jsonb_build_object(
    'claim_id',
      p_claim_id,
    'status',
      'withdrawn'
  );
end;
$function$

create or replace function public.community_artist_invite_representative(
  p_artist_id uuid,
  p_username text,
  p_representation_role text,
  p_can_manage_profile boolean default null,
  p_can_submit_releases boolean default null,
  p_can_post_updates boolean default null,
  p_can_manage_team boolean default null
)
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
  v_actor uuid := auth.uid();
  v_actor_rep public.artist_representations%rowtype;
  v_target_user uuid;
  v_role text :=
    lower(
      trim(
        coalesce(
          p_representation_role,
          ''
        )
      )
    );
  v_defaults record;
  v_profile boolean;
  v_releases boolean;
  v_updates boolean;
  v_team boolean;
  v_representation_id uuid;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if v_role not in (
    'manager',
    'label',
    'publicist',
    'team_member',
    'other'
  ) then
    raise exception
      'invalid_team_representation_role';
  end if;

  select *
  into v_actor_rep
  from public.artist_representations representation
  where representation.artist_id = p_artist_id
    and representation.user_id = v_actor
    and representation.status = 'active'
    and representation.can_manage_team = true
  order by representation.created_at desc
  limit 1;

  if not found then
    raise exception
      'insufficient_artist_team_privilege';
  end if;

  select profile.user_id
  into v_target_user
  from public.user_profiles profile
  where profile.username_normalized =
        public.community_normalize_username(
          p_username
        )
  limit 1;

  if v_target_user is null then
    raise exception
      'team_account_not_found';
  end if;

  if v_target_user = v_actor then
    raise exception
      'cannot_invite_self';
  end if;

  if exists (
    select 1
    from public.artist_representations representation
    where representation.artist_id = p_artist_id
      and representation.user_id =
          v_target_user
      and representation.status in (
        'pending',
        'active'
      )
  ) then
    raise exception
      'representation_already_exists';
  end if;

  select *
  into v_defaults
  from editorial.artist_representation_defaults(
    v_role
  );

  v_profile :=
    coalesce(
      p_can_manage_profile,
      v_defaults.can_manage_profile
    );

  v_releases :=
    coalesce(
      p_can_submit_releases,
      v_defaults.can_submit_releases
    );

  v_updates :=
    coalesce(
      p_can_post_updates,
      v_defaults.can_post_updates
    );

  v_team :=
    coalesce(
      p_can_manage_team,
      v_defaults.can_manage_team
    );

  if v_profile
     and not v_actor_rep.can_manage_profile
  then
    raise exception
      'cannot_delegate_profile_permission';
  end if;

  if v_releases
     and not v_actor_rep.can_submit_releases
  then
    raise exception
      'cannot_delegate_release_permission';
  end if;

  if v_updates
     and not v_actor_rep.can_post_updates
  then
    raise exception
      'cannot_delegate_update_permission';
  end if;

  if v_team
     and not v_actor_rep.can_manage_team
  then
    raise exception
      'cannot_delegate_team_permission';
  end if;

  insert into public.artist_representations (
    artist_id,
    user_id,
    representation_role,
    status,
    can_manage_profile,
    can_submit_releases,
    can_post_updates,
    can_manage_team,
    invited_by,
    invited_at
  )
  values (
    p_artist_id,
    v_target_user,
    v_role,
    'pending',
    v_profile,
    v_releases,
    v_updates,
    v_team,
    v_actor,
    now()
  )
  returning id
  into v_representation_id;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'representation_invited',
    null,
    v_representation_id,
    v_target_user,
    jsonb_build_object(
      'role',
        v_role,
      'permissions',
        jsonb_build_object(
          'profile',
            v_profile,
          'releases',
            v_releases,
          'updates',
            v_updates,
          'team',
            v_team
        )
    )
  );

  return jsonb_build_object(
    'representation_id',
      v_representation_id,
    'status',
      'pending',
    'user_id',
      v_target_user
  );
end;
$function$

create or replace function public.community_artist_accept_representation(
  p_representation_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path to
  'pg_catalog',
  'public',
  'editorial'
as $function$
declare
