$function$

create or replace function public.community_save_artist_profile_presentation(
  p_artist_id uuid,
  p_bio text default null,
  p_profile_image_url text default null,
  p_hero_image_url text default null,
  p_website_url text default null,
  p_public_email text default null,
  p_social_links jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, editorial
as $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_bio text := nullif(trim(coalesce(p_bio, '')), '');
  v_profile_image_url text := nullif(trim(coalesce(p_profile_image_url, '')), '');
  v_hero_image_url text := nullif(trim(coalesce(p_hero_image_url, '')), '');
  v_website_url text := nullif(trim(coalesce(p_website_url, '')), '');
  v_public_email text := nullif(lower(trim(coalesce(p_public_email, ''))), '');
  v_social_links jsonb := coalesce(p_social_links, '{}'::jsonb);
  v_key text;
  v_value text;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_manage_profile
  then
    raise exception 'insufficient_artist_profile_privilege';
  end if;

  if v_bio is not null
     and char_length(v_bio) > 4000
  then
    raise exception 'artist_bio_too_long';
  end if;

  if v_profile_image_url is not null
     and (
       char_length(v_profile_image_url) > 2048
       or v_profile_image_url !~* '^https?://'
     )
  then
    raise exception 'invalid_profile_image_url';
  end if;

  if v_hero_image_url is not null
     and (
       char_length(v_hero_image_url) > 2048
       or v_hero_image_url !~* '^https?://'
     )
  then
    raise exception 'invalid_hero_image_url';
  end if;

  if v_website_url is not null
     and (
       char_length(v_website_url) > 2048
       or v_website_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_website_url';
  end if;

  if v_public_email is not null
     and (
       char_length(v_public_email) > 320
       or v_public_email !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
     )
  then
    raise exception 'invalid_public_email';
  end if;

  if jsonb_typeof(v_social_links) <> 'object' then
    raise exception 'artist_social_links_must_be_object';
  end if;

  for v_key, v_value in
    select key, value
    from jsonb_each_text(v_social_links)
  loop
    if v_key not in (
      'instagram',
      'tiktok',
      'x',
      'youtube',
      'facebook',
      'spotify',
      'soundcloud'
    ) then
      raise exception 'unsupported_artist_social_link';
    end if;

    if nullif(trim(v_value), '') is not null
       and (
         char_length(v_value) > 2048
         or v_value !~* '^https?://'
       )
    then
      raise exception 'invalid_artist_social_link';
    end if;
  end loop;

  insert into public.artist_profile_presentations (
    artist_id,
    bio,
    profile_image_url,
    hero_image_url,
    website_url,
    public_email,
    social_links,
    updated_by
  )
  values (
    p_artist_id,
    v_bio,
    v_profile_image_url,
    v_hero_image_url,
    v_website_url,
    v_public_email,
    v_social_links,
    v_actor
  )
  on conflict (artist_id)
  do update set
    bio = excluded.bio,
    profile_image_url = excluded.profile_image_url,
    hero_image_url = excluded.hero_image_url,
    website_url = excluded.website_url,
    public_email = excluded.public_email,
    social_links = excluded.social_links,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning jsonb_build_object(
    'artist_id', artist_id,
    'bio', bio,
    'profile_image_url', profile_image_url,
    'hero_image_url', hero_image_url,
    'website_url', website_url,
    'public_email', public_email,
    'social_links', social_links,
    'updated_at', updated_at
  )
  into v_result;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'profile_presentation_updated',
    null,
    v_rep.id,
    v_actor,
    jsonb_build_object(
      'presentation_updated_at', now()
    )
  );

  return v_result;
end;
$$

create or replace function public.community_submit_artist_registry_correction(
  p_artist_id uuid,
  p_field_key text,
  p_proposed_value text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, editorial
as $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_artist_slug text;
  v_field_key text := lower(trim(coalesce(p_field_key, '')));
  v_proposed_value text := trim(coalesce(p_proposed_value, ''));
  v_reason text := trim(coalesce(p_reason, ''));
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_manage_profile
  then
    raise exception 'insufficient_artist_profile_privilege';
  end if;

  if v_field_key not in (
    'display_name',
    'artist_type',
    'origin_iso2',
    'discography',
    'credits',
    'other'
  ) then
    raise exception 'unsupported_registry_correction_field';
  end if;

  if char_length(v_proposed_value) < 1
     or char_length(v_proposed_value) > 4000
  then
    raise exception 'invalid_registry_correction_value';
  end if;

  if char_length(v_reason) < 10
     or char_length(v_reason) > 4000
  then
    raise exception 'invalid_registry_correction_reason';
  end if;

  select artist.slug
  into v_artist_slug
  from public.registry_artists artist
  where artist.id = p_artist_id
    and artist.status = 'active';

  if v_artist_slug is null then
    raise exception 'artist_not_found';
  end if;

  v_result := public.community_create_contribution(
    null,
    'artist',
    p_artist_id::text,
    v_artist_slug,
    'artist_registry_correction',
    jsonb_build_object(
      'field_key', v_field_key,
      'proposed_value', v_proposed_value,
      'reason', v_reason,
      'representation_id', v_rep.id
    )
  );

  return v_result;
end;
$$

create or replace function public.community_publish_artist_update(
  p_artist_id uuid,
  p_body text,
  p_image_url text default null,
  p_link_url text default null,
  p_link_label text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, editorial
as $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_artist_slug text;
  v_body text := btrim(coalesce(p_body, ''));
  v_image_url text := nullif(btrim(coalesce(p_image_url, '')), '');
  v_link_url text := nullif(btrim(coalesce(p_link_url, '')), '');
  v_link_label text := nullif(btrim(coalesce(p_link_label, '')), '');
  v_update public.artist_updates%rowtype;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_post_updates
  then
    raise exception 'insufficient_artist_update_privilege';
  end if;

  select artist.slug
  into v_artist_slug
  from public.registry_artists artist
  where artist.id = p_artist_id
    and artist.status = 'active';

  if v_artist_slug is null then
    raise exception 'artist_not_found';
  end if;

  if char_length(v_body) < 1
     or char_length(v_body) > 2000
  then
    raise exception 'invalid_artist_update_body';
  end if;

  if v_image_url is not null
     and (
       char_length(v_image_url) > 2048
       or v_image_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_update_image_url';
  end if;

  if v_link_url is not null
     and (
       char_length(v_link_url) > 2048
       or v_link_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_update_link_url';
  end if;

  if v_link_label is not null
     and (
       char_length(v_link_label) > 120
       or v_link_url is null
     )
  then
    raise exception 'invalid_artist_update_link_label';
  end if;

  insert into public.artist_updates (
    artist_id,
    representation_id,
    author_user_id,
    body,
    image_url,
    link_url,
    link_label,
    status
  )
  values (
    p_artist_id,
    v_rep.id,
    v_actor,
    v_body,
    v_image_url,
    v_link_url,
    v_link_label,
    'published'
  )
  returning *
  into v_update;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'artist_update_published',
    null,
    v_rep.id,
    v_actor,
    jsonb_build_object(
      'artist_update_id', v_update.id,
      'published_at', v_update.published_at
    )
  );

  return jsonb_build_object(
    'id', v_update.id,
    'artist_id', v_update.artist_id,
    'body', v_update.body,
    'image_url', v_update.image_url,
    'link_url', v_update.link_url,
    'link_label', v_update.link_label,
    'status', v_update.status,
    'published_at', v_update.published_at,
    'updated_at', v_update.updated_at,
    'canonical_path',
      '/artists/' || v_artist_slug || '/updates/' || v_update.id::text
  );
end;
$$

