create or replace function public.community_get_artist_manage_updates(
  p_artist_id uuid,
  p_limit integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, editorial
as $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_limit integer :=
    least(
      greatest(
        coalesce(p_limit, 30),
        1
      ),
      100
    );
  v_artist_slug text;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_post_updates
  then
    raise exception 'insufficient_artist_update_privilege';
  end if;

  select slug
  into v_artist_slug
  from public.registry_artists
  where id = p_artist_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', managed.id,
        'artist_id', managed.artist_id,
        'body', managed.body,
        'image_url', managed.image_url,
        'link_url', managed.link_url,
        'link_label', managed.link_label,
        'status', managed.status,
        'published_at', managed.published_at,
        'withdrawn_at', managed.withdrawn_at,
        'updated_at', managed.updated_at,
        'canonical_path',
          '/artists/' || v_artist_slug || '/updates/' || managed.id::text
      )
      order by managed.published_at desc, managed.id desc
    ),
    '[]'::jsonb
  )
  into v_result
  from (
    select artist_update.*
    from public.artist_updates artist_update
    where artist_update.artist_id = p_artist_id
    order by artist_update.published_at desc, artist_update.id desc
    limit v_limit
  ) managed;

  return v_result;
end;
$$

create or replace function public.community_react_to_target(
  p_target_type text,
  p_target_id uuid,
  p_reaction_type text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_user_id uuid := auth.uid();
  v_target_type text :=
    nullif(
      trim(
        coalesce(
          p_target_type,
          ''
        )
      ),
      ''
    );
  v_reaction_type text :=
    nullif(
      trim(
        coalesce(
          p_reaction_type,
          ''
        )
      ),
      ''
    );
  v_existing uuid;
  v_created boolean;
  v_reaction_count integer;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_target_type is null
     or p_target_id is null
  then
    raise exception
      'Reaction target is required'
      using errcode = '22023';
  end if;

  if v_reaction_type is null
     or char_length(v_reaction_type) > 32
     or v_reaction_type ~ '[[:cntrl:]]'
     or v_reaction_type ~ '[[:space:]]'
     or (
       octet_length(v_reaction_type) =
       char_length(v_reaction_type)
       and v_reaction_type not in (
         'signal',
         'memory',
         'context',
         'fire',
         'agree'
       )
     )
  then
    raise exception
      'Unsupported reaction type'
      using errcode = '22023';
  end if;

  if v_target_type = 'artist_update' then
    perform 1
    from public.artist_updates artist_update
    join public.registry_artists artist
      on artist.id = artist_update.artist_id
    where artist_update.id = p_target_id
      and artist_update.status = 'published'
      and artist.status = 'active';

    if not found then
      raise exception
        'Reaction target is not currently public'
        using errcode = '22023';
    end if;
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|'
      || v_target_type
      || '|'
      || p_target_id::text
      || '|'
      || v_reaction_type,
      0
    )
  );

  if v_target_type = 'comment' then
    perform 1
    from public.community_comments comment
    where comment.id = p_target_id
    for update;

    if not found then
      raise exception
        'Comment not found'
        using errcode = '22023';
    end if;
  end if;

  delete from public.community_reactions
  where user_id = v_user_id
    and target_type = v_target_type
    and target_id = p_target_id
    and reaction_type = v_reaction_type
  returning id
  into v_existing;

  if found then
    v_created := false;
  else
    insert into public.community_reactions (
      user_id,
      target_type,
      target_id,
      reaction_type
    )
    values (
      v_user_id,
      v_target_type,
      p_target_id,
      v_reaction_type
    );

    v_created := true;
  end if;

  if v_target_type = 'comment' then
    select count(*)::integer
    into v_reaction_count
    from public.community_reactions reaction
    where reaction.target_type = 'comment'
      and reaction.target_id = p_target_id;

    update public.community_comments
    set reaction_count = v_reaction_count
    where id = p_target_id;
  else
    v_reaction_count := null;
  end if;

  return jsonb_build_object(
    'created', v_created,
    'reaction_type', v_reaction_type,
    'reaction_count', v_reaction_count
  );
end;
$$

do $m4_artist_updates_postflight$
declare
  v_event_constraint text;
  v_save_constraint text;
  v_publish_definition text;
  v_edit_definition text;
  v_withdraw_definition text;
  v_public_reader_definition text;
  v_feed_definition text;
  v_save_definition text;
  v_reaction_reader_definition text;
  v_reaction_writer_definition text;
begin
  if to_regclass('public.artist_updates') is null then
    raise exception 'FAIL: Artist Update table was not created';
  end if;

  if not exists (
    select 1
    from pg_class c
    join pg_namespace n
      on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'artist_updates'
      and c.relrowsecurity
  ) then
    raise exception 'FAIL: Artist Update RLS is not enabled';
  end if;

  if has_table_privilege(
       'anon',
       'public.artist_updates',
       'SELECT'
     )
     or has_table_privilege(
       'authenticated',
       'public.artist_updates',
       'SELECT'
     )
     or has_table_privilege(
       'authenticated',
       'public.artist_updates',
       'INSERT'
     )
  then
    raise exception 'FAIL: Direct Artist Update table privilege leaked';
  end if;

  if to_regprocedure('public.community_publish_artist_update(uuid,text,text,text,text)') is null
     or to_regprocedure('public.community_edit_artist_update(uuid,text,text,text,text)') is null
     or to_regprocedure('public.community_withdraw_artist_update(uuid,text)') is null
     or to_regprocedure('public.community_get_artist_update(uuid)') is null
     or to_regprocedure('public.community_get_artist_manage_updates(uuid,integer)') is null
  then
    raise exception 'FAIL: One or more M4 Artist Update functions are missing';
  end if;

  select pg_get_constraintdef(oid)
  into v_event_constraint
  from pg_constraint
  where conrelid = 'public.artist_representation_events'::regclass
    and conname = 'artist_representation_events_event_type_check';

  if v_event_constraint is null
     or position('artist_update_published' in v_event_constraint) = 0
     or position('artist_update_edited' in v_event_constraint) = 0
     or position('artist_update_withdrawn' in v_event_constraint) = 0
  then
    raise exception 'FAIL: Artist representation event ledger was not extended for M4';
  end if;

  select pg_get_constraintdef(oid)
  into v_save_constraint
  from pg_constraint
  where conrelid = 'public.community_saves'::regclass
    and conname = 'community_saves_entity_type_capability_check';

  if v_save_constraint is null
     or position('artist_update' in v_save_constraint) = 0
  then
    raise exception 'FAIL: Save capability does not include Artist Updates';
  end if;

  select pg_get_functiondef(
    'public.community_publish_artist_update(uuid,text,text,text,text)'::regprocedure
  ) into v_publish_definition;

  select pg_get_functiondef(
    'public.community_edit_artist_update(uuid,text,text,text,text)'::regprocedure
  ) into v_edit_definition;

  select pg_get_functiondef(
    'public.community_withdraw_artist_update(uuid,text)'::regprocedure
  ) into v_withdraw_definition;

  select pg_get_functiondef(
    'public.community_get_artist_update(uuid)'::regprocedure
  ) into v_public_reader_definition;

  select pg_get_functiondef(
    'public.community_get_following_feed(integer,timestamp with time zone,text)'::regprocedure
  ) into v_feed_definition;

  select pg_get_functiondef(
    'public.community_set_saved_state(text,text,text,text,text,text,text,boolean)'::regprocedure
  ) into v_save_definition;

  select pg_get_functiondef(
    'public.community_get_reaction_state_for_public_targets(jsonb)'::regprocedure
  ) into v_reaction_reader_definition;

  select pg_get_functiondef(
    'public.community_react_to_target(text,uuid,text)'::regprocedure
  ) into v_reaction_writer_definition;

  if position('can_post_updates' in v_publish_definition) = 0
     or position('can_post_updates' in v_edit_definition) = 0
     or position('can_post_updates' in v_withdraw_definition) = 0
  then
    raise exception 'FAIL: Artist Update writes are not bound to can_post_updates';
  end if;

  if position('status = ''published''' in v_public_reader_definition) = 0 then
    raise exception 'FAIL: Public Artist Update reader is not publication-bound';
  end if;

  if position('artist_updates' in v_feed_definition) = 0
     or position('registry_release_artists' in v_feed_definition) = 0
     or position('artist_raw_outputs' in v_feed_definition) = 0
  then
    raise exception 'FAIL: Following does not merge Artist Updates with Registry Releases';
  end if;

  if position('artist_update' in v_save_definition) = 0
     or position('artist_update' in v_reaction_reader_definition) = 0
     or position('artist_update' in v_reaction_writer_definition) = 0
  then
    raise exception 'FAIL: Artist Update Save or Reaction capability is incomplete';
  end if;

  if v_publish_definition ~* '(insert|update|delete)[[:space:]]+(into[[:space:]]+)?public[.]registry_artists'
     or v_edit_definition ~* '(insert|update|delete)[[:space:]]+(into[[:space:]]+)?public[.]registry_artists'
     or v_withdraw_definition ~* '(insert|update|delete)[[:space:]]+(into[[:space:]]+)?public[.]registry_artists'
  then
    raise exception 'FAIL: Artist Update command can write canonical Registry Artist rows';
  end if;
end;
$m4_artist_updates_postflight$

create or replace function editorial.artist_music_submission_review_due_at(
  p_submitted_at timestamptz
)
returns timestamptz
language plpgsql
immutable
set search_path = pg_catalog
as $$
declare
  v_due timestamptz := p_submitted_at;
  v_business_days integer := 0;
begin
  if p_submitted_at is null then
    return null;
  end if;

  while v_business_days < 3 loop
    v_due := v_due + interval '1 day';

    if extract(
      isodow
      from v_due at time zone 'Africa/Nairobi'
    ) between 1 and 5
    then
      v_business_days := v_business_days + 1;
    end if;
  end loop;

  return v_due;
end;
$$

create or replace function public.admin_resolve_registry_track_intake(
  p_suggestion_id uuid,
  p_registry_track_id uuid,
  p_review_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, auth, public
as $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_track public.registry_tracks%rowtype;
  v_artist_sync jsonb;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status <> 'needs_review' then
    raise exception
      'Only Track Intake items awaiting review can be resolved.';
  end if;

  if v_suggestion.source_playlist_item_id is null
     and v_suggestion.intake_origin not in (
       'public_contribution',
       'artist_submission'
     )
  then
    raise exception
      'Track Intake item has not been materialized into its Playlist.';
  end if;

  select track.*
  into v_track
  from public.registry_tracks track
  where track.id = p_registry_track_id
    and track.status = 'active';

  if not found then
    raise exception 'Selected Music Registry track is unavailable.';
  end if;

  select public.sync_registry_track_intake_artist_credits(
    p_suggestion_id,
    p_registry_track_id
  )
  into v_artist_sync;

  update public.registry_provider_track_suggestions suggestion
  set
    status = 'canonicalized',
    canonical_track_id = p_registry_track_id,
    canonicalized_track_id = p_registry_track_id,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_note = nullif(btrim(p_review_note), '')
  where suggestion.id = p_suggestion_id;

  return jsonb_build_object(
    'suggestion_id', p_suggestion_id,
    'playlist_id', v_suggestion.source_playlist_id,
    'playlist_item_id', v_suggestion.source_playlist_item_id,
    'intake_origin', v_suggestion.intake_origin,
    'source_contribution_id', v_suggestion.source_contribution_id,
    'status', 'canonicalized',
    'registry_track_id', p_registry_track_id,
    'registry_track_title', v_track.title,
    'artist_sync', v_artist_sync
  );
end;
$$

do $m5_postflight$
declare
  v_origin_constraint text;
  v_event_constraint text;
  v_submit_definition text;
  v_reader_definition text;
  v_resolver_definition text;
begin
  if to_regclass('platform_private.artist_music_submission_validations') is null then
    raise exception 'FAIL: Artist music validation table was not created';
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'registry_provider_track_suggestions'
      and column_name = 'source_playlist_id'
      and is_nullable = 'YES'
  ) then
    raise exception 'FAIL: Track Intake still requires Playlist identity';
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'registry_provider_track_suggestions'
      and column_name = 'review_due_at'
      and data_type = 'timestamp with time zone'
  ) then
    raise exception 'FAIL: Artist submission review deadline is missing';
  end if;

  select pg_get_constraintdef(oid)
  into v_origin_constraint
  from pg_constraint
  where conrelid = 'public.registry_provider_track_suggestions'::regclass
    and conname = 'registry_provider_track_suggestions_intake_origin_check';

  if position('artist_submission' in coalesce(v_origin_constraint, '')) = 0 then
    raise exception 'FAIL: Track Intake does not recognize Artist submission origin';
  end if;

  select pg_get_constraintdef(oid)
  into v_event_constraint
  from pg_constraint
  where conrelid = 'public.artist_representation_events'::regclass
    and conname = 'artist_representation_events_event_type_check';

  if position('music_submission_created' in coalesce(v_event_constraint, '')) = 0 then
    raise exception 'FAIL: Artist representation audit does not include music submission';
  end if;

  select pg_get_functiondef(
    'public.community_submit_artist_music(uuid,uuid,jsonb,text)'::regprocedure
  )
  into v_submit_definition;

  select pg_get_functiondef(
    'public.community_get_artist_music_submissions(uuid,integer)'::regprocedure
  )
  into v_reader_definition;

  select pg_get_functiondef(
    'public.admin_resolve_registry_track_intake(uuid,uuid,text)'::regprocedure
  )
  into v_resolver_definition;

  if position('can_submit_releases' in v_submit_definition) = 0
     or position('artist_submission' in v_submit_definition) = 0
     or position('artist_music_submission_review_due_at' in v_submit_definition) = 0
  then
    raise exception 'FAIL: Artist music submit authority or review SLA is incomplete';
  end if;

  if position('submitted_for_artist_id = p_artist_id' in v_reader_definition) = 0
     or position('can_submit_releases' in v_reader_definition) = 0
  then
    raise exception 'FAIL: Artist music history is not bounded to Artist authority';
  end if;

  if position('artist_submission' in v_resolver_definition) = 0 then
    raise exception 'FAIL: Registry review cannot resolve Artist submissions';
  end if;

  if v_submit_definition ~* '(insert|update|delete)[[:space:]]+(into[[:space:]]+)?public[.](registry_tracks|registry_releases|registry_artists)'
  then
    raise exception 'FAIL: Artist submission command can write canonical Registry rows';
  end if;

  if has_table_privilege(
       'authenticated',
       'platform_private.artist_music_submission_validations',
       'SELECT'
     )
     or has_table_privilege(
       'authenticated',
       'platform_private.artist_music_submission_validations',
       'INSERT'
     )
  then
    raise exception 'FAIL: Artist validation storage leaked to authenticated clients';
  end if;
end;
$m5_postflight$

do $m5_trigger_boundary_preflight$
declare
  v_definition text;
begin
  if to_regprocedure('editorial.sync_playlist_registry_intake_item_artists()') is null
     or to_regprocedure('editorial.ensure_playlist_registry_intake_item(uuid)') is null
  then
    raise exception 'STOP: Playlist Registry intake synchronization authority is missing';
  end if;

  select pg_get_functiondef(
    'editorial.sync_playlist_registry_intake_item_artists()'::regprocedure
  )
  into v_definition;

  if position(
       'v_intake_origin = ''public_contribution'''
       in v_definition
     ) = 0
  then
    raise exception
      'STOP: Expected pre-repair Playlist Artist-credit synchronization definition is not present';
  end if;

  if position(
       'v_intake_origin <> ''playlist_editor'''
       in v_definition
     ) > 0
  then
    raise exception
      'STOP: Playlist Artist-credit synchronization boundary is already repaired';
  end if;
end;
$m5_trigger_boundary_preflight$

create or replace function editorial.sync_playlist_registry_intake_item_artists()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, editorial
as $$
declare
  v_suggestion_id uuid;
  v_intake_origin text;
  v_item_id uuid;
  v_artist_names text[];
begin
  v_suggestion_id :=
    coalesce(
      new.suggestion_id,
      old.suggestion_id
    );

  select suggestion.intake_origin
  into v_intake_origin
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = v_suggestion_id;

  if not found
     or v_intake_origin <> 'playlist_editor'
  then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  v_item_id :=
    editorial.ensure_playlist_registry_intake_item(
      v_suggestion_id
    );

  if v_item_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  select coalesce(
    array_agg(
      coalesce(
        artist.display_name,
        credit.observed_name
      )
      order by credit.credit_order
    ) filter (
      where coalesce(
        artist.display_name,
        credit.observed_name
      ) is not null
    ),
    '{}'::text[]
  )
  into v_artist_names
  from public.registry_provider_track_suggestion_artists credit
  left join public.registry_artists artist
    on artist.id = credit.registry_artist_id
  where credit.suggestion_id = v_suggestion_id;

  update public.wk_playlist_items item
  set artist_names =
    coalesce(
      v_artist_names,
      '{}'::text[]
    )
  where item.id = v_item_id
    and item.lifecycle_state = 'active';

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$

do $m5_trigger_boundary_postflight$
declare
  v_definition text;
begin
  select pg_get_functiondef(
    'editorial.sync_playlist_registry_intake_item_artists()'::regprocedure
  )
  into v_definition;

  if position(
       'v_intake_origin <> ''playlist_editor'''
       in v_definition
     ) = 0
  then
    raise exception
      'FAIL: Playlist synchronization is not bounded to playlist_editor intake';
  end if;

  if position(
       'editorial.ensure_playlist_registry_intake_item'
       in v_definition
     ) = 0
  then
    raise exception
      'FAIL: Playlist intake synchronization lost its Playlist materialization authority';
  end if;

  if not exists (
    select 1
    from pg_trigger trigger_row
    where not trigger_row.tgisinternal
      and trigger_row.tgrelid =
        'public.registry_provider_track_suggestion_artists'::regclass
      and trigger_row.tgname =
        'registry_provider_track_suggestion_sync_playlist_item_artists'
  ) then
    raise exception
      'FAIL: Registry intake Artist-credit synchronization trigger is missing';
  end if;
end;
$m5_trigger_boundary_postflight$
